// plx-wall — wallpaper-клиент для parallax.
// Использование: plx-wall [путь к картинке]
// Сигнал USR1 → следующие обои
// Сигнал USR2 → показать/скрыть оверлей
//
// В parallax config.lua (Super+W уже занят toggle_floating, поэтому Alt):
//   bind{ mods = "alt", key = "w", action = "spawn",
//         cmd = "pkill -USR1 -x plx-wall" }
//   bind{ mods = "alt+shift", key = "w", action = "spawn",
//         cmd = "pkill -USR2 -x plx-wall" }

