use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

mod ffmpeg_sys;
mod hwvideo;
mod online;
mod palette;
mod preview;
mod ui;

/// Замер времени кадра — включается переменной `PLX_WALL_PROFILE=1`.
///
/// Заведён после жалобы «анимации очень лагают, а на ноуте лагает всё»:
/// профилировщика (perf) на этих машинах нет, а гадать, где уходит время,
/// дороже, чем измерить. Выключенный замер стоит одного чтения статического
/// флага на кадр.
///
/// Цифры печатаются раз в секунду в stderr, то есть в лог сеанса:
/// `plx-wall: меню 42 кадра, среднее 3.1 мс, худший 21.7 мс`. Худший важнее
/// среднего: лаг — это как раз он.
mod замер {
    use std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};
    use std::time::Instant;

    static ВКЛЮЧЁН: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    static КАДРОВ: AtomicUsize = AtomicUsize::new(0);
    static СУММА_НС: AtomicU64 = AtomicU64::new(0);
    static ХУДШИЙ_НС: AtomicU64 = AtomicU64::new(0);
    static ЖДЁМ_НАЧАЛА: AtomicBool = AtomicBool::new(true);

    fn включён() -> bool {
        *ВКЛЮЧЁН.get_or_init(|| std::env::var_os("PLX_WALL_PROFILE").is_some())
    }

    /// Точка отсчёта. `None`, когда замер выключен, — тогда часы не читаются
    /// вовсе: на слабой машине это не пустяк, `Instant::now` под виртуализацией
    /// стоит сотни наносекунд.
    pub fn пора() -> Option<Instant> {
        включён().then(Instant::now)
    }

    /// Накопитель по ФАЗАМ кадра: стекло, карточки, перестановка байтов, отдача
    /// буфера. Без разбивки видно только «кадр стоит 33 мс», а чинить надо то,
    /// что внутри.
    static ФАЗЫ: std::sync::Mutex<Vec<(&'static str, u64, usize)>> =
        std::sync::Mutex::new(Vec::new());

    pub fn фаза(имя: &'static str, начало: Option<Instant>) {
        let Some(начало) = начало else { return };
        let нс = начало.elapsed().as_nanos() as u64;
        let mut т = ФАЗЫ.lock().unwrap();
        match т.iter_mut().find(|(и, _, _)| *и == имя) {
            Some((_, сумма, счёт)) => {
                *сумма += нс;
                *счёт += 1;
            }
            None => т.push((имя, нс, 1)),
        }
    }

    pub fn кадр_меню(начало: Option<Instant>) {
        let Some(начало) = начало else { return };
        let нс = начало.elapsed().as_nanos() as u64;
        КАДРОВ.fetch_add(1, Ordering::Relaxed);
        СУММА_НС.fetch_add(нс, Ordering::Relaxed);
        ХУДШИЙ_НС.fetch_max(нс, Ordering::Relaxed);
    }

    /// Раз в секунду вывести и обнулить накопленное.
    pub fn отчёт() {
        if !включён() {
            return;
        }
        // Отсчёт секунды ведём от первого вызова, а не от запуска процесса:
        // до первого кадра меню может пройти сколько угодно.
        static НАЧАЛО: std::sync::OnceLock<Instant> = std::sync::OnceLock::new();
        let начало = НАЧАЛО.get_or_init(Instant::now);
        static ПОСЛЕДНИЙ_ОТЧЁТ: AtomicU64 = AtomicU64::new(0);
        let прошло = начало.elapsed().as_millis() as u64;
        let был = ПОСЛЕДНИЙ_ОТЧЁТ.load(Ordering::Relaxed);
        if прошло < был + 1000 {
            return;
        }
        ПОСЛЕДНИЙ_ОТЧЁТ.store(прошло, Ordering::Relaxed);
        let кадров = КАДРОВ.swap(0, Ordering::Relaxed);
        let сумма = СУММА_НС.swap(0, Ordering::Relaxed);
        let худший = ХУДШИЙ_НС.swap(0, Ordering::Relaxed);
        if кадров == 0 {
            ЖДЁМ_НАЧАЛА.store(true, Ordering::Relaxed);
            return;
        }
        ЖДЁМ_НАЧАЛА.store(false, Ordering::Relaxed);
        let mut строка = format!(
            "plx-wall: меню {} кадров, среднее {:.1} мс, худший {:.1} мс",
            кадров,
            сумма as f64 / кадров as f64 / 1e6,
            худший as f64 / 1e6,
        );
        {
            let mut т = ФАЗЫ.lock().unwrap();
            // По убыванию доли: самое дорогое сразу видно, а не ищется глазами.
            т.sort_by_key(|(_, сумма, _)| std::cmp::Reverse(*сумма));
            for (имя, сумма_ф, счёт) in т.iter() {
                if *счёт == 0 {
                    continue;
                }
                строка.push_str(&format!(
                    " | {имя} {:.1} мс",
                    *сумма_ф as f64 / кадров.max(1) as f64 / 1e6
                ));
            }
            т.clear();
        }
        eprintln!("{строка}");
    }
}

