// ── Константы UI ────────────────────────────────────────────────────────────

// ── Размер меню: РАНТАЙМОВЫЙ ────────────────────────────────────────────────
//
// Раньше меню было фиксированным окошком 740×576 посреди экрана: четыре
// колонки, три видимых ряда, всё остальное — прокруткой. На 2560×1080 это
// восьмая часть экрана, и выбирать обои приходилось в замочную скважину.
// Теперь выбор занимает ЭКРАН целиком (минус поле по краям), а число колонок и
// рядов считается от того, сколько влезло.
//
// Значения — атомики, а не поля Config: размеры спрашивают и свободные
// функции раскладки (`tab_rects`, `card_rect`, `ui_cells`), которым Config не
// передан, и протаскивать его туда ради двух чисел — шум на десятки сигнатур.
// Ставятся один раз, когда стал известен размер выхода.
use std::sync::atomic::{AtomicU32, Ordering as ПорядокАтомика};

static МЕНЮ_W: AtomicU32 = AtomicU32::new(740);
static МЕНЮ_H: AtomicU32 = AtomicU32::new(576);
/// Высота ВЫХОДА (не меню). Нужна отдельно, потому что высота меню теперь
/// считается ОТ ленты, а не наоборот: узнать «сколько там экрана» из ui_h()
/// стало нельзя.
static ЭКРАН_H: AtomicU32 = AtomicU32::new(1080);

/// Поле от края экрана до края меню.
const МЕНЮ_ПОЛЕ: u32 = 64;

fn ui_w() -> u32 { МЕНЮ_W.load(ПорядокАтомика::Relaxed) }
fn ui_h() -> u32 { МЕНЮ_H.load(ПорядокАтомика::Relaxed) }

/// Подогнать меню под экран. Возвращает true, если размер изменился, — тогда
/// буферы надо пересоздать (см. render_overlay).
///
/// **Меню больше НЕ во весь экран.** Оно было им, пока внутри лежала сетка
/// карточек: рядов много, и они экран заполняли. Ленте нужен один ряд, и на
/// полном экране вокруг него оставалось поле в две трети высоты — пустота, в
/// которой лента терялась. Теперь меню это ПОЛОСА: во всю ширину (минус поле)
/// и ровно такой высоты, сколько нужно ленте. По вертикали её центрирует сам
/// layer-shell — поверхность без якорей встаёт посреди выхода.
fn установить_размер_меню(sw: u32, sh: u32) -> bool {
    let прежние = (ui_w(), ui_h());
    // На совсем маленьком выходе поле съело бы всё меню целиком.
    let w = sw.saturating_sub(МЕНЮ_ПОЛЕ * 2).max(360);
    // Порядок важен: `карта_h()` спрашивает ui_w() и ЭКРАН_H, поэтому оба
    // должны быть уже записаны.
    МЕНЮ_W.store(w, ПорядокАтомика::Relaxed);
    ЭКРАН_H.store(sh.max(1), ПорядокАтомика::Relaxed);
    let h = (MY + карта_h() + ЛЕНТА_НИЗ)
        .min(sh.saturating_sub(16).max(160))
        .max(160);
    МЕНЮ_H.store(h, ПорядокАтомика::Relaxed);
    прежние != (w, h)
}

// ── Лента ────────────────────────────────────────────────────────────────────
//
// Сетка квадратиков 155×155 заменена на ЛЕНТУ: один ряд крупных карточек 16:9,
// листающийся вбок. Так просил Ярик 24.08.2026, и причина не только во вкусе:
// обои — это картинка 16:9, а квадратная карточка показывала её обрезанной по
// бокам, то есть врала о том, что ты выбираешь. В ряду из четырёх карточек по
// 568 px обои видно целиком и крупно, а не почтовой маркой.

/// Отношение сторон карточки — то же, что у экрана.
const КАРТА_W_К_H: (u32, u32) = (16, 9);
/// Пределы высоты карточки. Верхний нужен, чтобы на 4K лента не выродилась в
/// две исполинские карточки; нижний — чтобы на маленьком выходе от неё
/// осталось хоть что-то узнаваемое.
const КАРТА_H_МАКС: u32 = 340;
const КАРТА_H_МИН: u32 = 110;
/// Полоса под лентой: прокрутка и воздух под ней.
const ЛЕНТА_НИЗ: u32 = 44;
/// Поле по бокам ленты — под стрелки листания. Их место резервируется ЗАРАНЕЕ,
/// а не отдаётся тому, что осталось: иначе на широком выходе карточки съедали
/// всю ширину, и стрелка ложилась поверх крайней карточки.
const ЛЕНТА_БОК: u32 = ARROW + 16;

/// Высота карточки ленты.
///
/// Считается от ЭКРАНА, а не от меню: высота меню сама выводится отсюда
/// (см. `установить_размер_меню`), и спрашивать её здесь значило бы замкнуть
/// круг. Три ограничителя, каждый по своей причине:
///  · по ширине — две карточки обязаны влезать всегда, иначе «лента»
///    превращается в один слайд;
///  · по экрану — лента остаётся ПОЛОСОЙ поверх рабочего стола, а не
///    занавесом на пол-экрана;
///  · потолок КАРТА_H_МАКС — чтобы на 4K не вышло две исполинские карточки.
fn карта_h() -> u32 {
    let по_ширине = (ui_w().saturating_sub(ЛЕНТА_БОК * 2 + GAP) / 2)
        * КАРТА_W_К_H.1 / КАРТА_W_К_H.0;
    let экран = ЭКРАН_H.load(ПорядокАтомика::Relaxed);
    let по_экрану = (экран * 2 / 5).max(КАРТА_H_МИН);
    по_ширине.min(по_экрану).min(КАРТА_H_МАКС).max(КАРТА_H_МИН)
}

/// Ширина карточки ленты.
fn карта_w() -> u32 {
    (карта_h() * КАРТА_W_К_H.0 / КАРТА_W_К_H.1).max(1)
}

/// Сколько карточек видно в ленте разом.
fn видно_карт() -> u32 {
    let доступно = ui_w().saturating_sub(ЛЕНТА_БОК * 2);
    ((доступно + GAP) / (карта_w() + GAP)).max(1)
}

/// Левый край первой карточки — лента стоит по центру меню.
fn лента_x() -> u32 {
    let n = видно_карт();
    let ширина = n * карта_w() + (n - 1) * GAP;
    (ui_w().saturating_sub(ширина)) / 2
}

/// Верх карточек: лента висит по центру между полосой кнопок и прокруткой.
fn лента_y() -> u32 {
    let поле = ui_h().saturating_sub(MY + ЛЕНТА_НИЗ);
    MY + поле.saturating_sub(карта_h()) / 2
}

const CORNER: u32 = 14;
/// Размер миниатюры, которую считает `load_thumbnails`. Это НЕ размер
/// карточки: карточка зависит от выхода, а пересчитывать миниатюры (то есть
/// декодировать все обои заново) при каждом изменении размера меню слишком
/// дорого. Рисуется миниатюра с масштабированием — см. `draw_thumbnail`.
const МИНИ_W: u32 = 640;
const МИНИ_H: u32 = 360;
const GAP: u32 = 12;
/// Отступ сетки сверху.
const MY: u32 = 60;
/// Полоса прокрутки в правом поле.
const SB_W: u32 = 6;
const SB_COLOR: u32 = 0x24FFFFFF;
const SB_THUMB_COLOR: u32 = 0xCCE8E8EE;
/// Стрелки прокрутки — кликабельные, если мыши без колеса.
const ARROW: u32 = 26;
/// Длительность перехода между обоями — косой шторки (см. render_wallpaper).
/// Дольше прежнего растворения (380 мс): шторка проходит через весь экран, и
/// на коротком времени она читается рывком, а не движением.
const FADE_MS: u64 = 750;
/// Наклон шторки: на сколько ширин кадра её край сдвинут внизу против верха.
const ШТОРКА_НАКЛОН: f32 = 0.55;
/// Ширина мягкого края шторки в долях ширины кадра.
const ШТОРКА_КРАЙ: f32 = 0.035;

// ── Палитра ─────────────────────────────────────────────────────────────────
//
// Цвета задаются ОБЫЧНЫМИ `0xAARRGGBB` — премультиплицирует их `ui::Цвет`
// один раз на входе (см. `ui.rs`, там же про грабли Wayland с альфой).
//
// Прежняя палитра была построена так, будто меню непрозрачное: фон 0xCC, а всё
// остальное — сплошные серые плашки поверх него. Смысла в полупрозрачном фоне
// от этого не было никакого: сквозь него просвечивал ровно один прямоугольник
// по краям. Теперь прозрачны и карточки, и кнопки, и обои под меню видно
// насквозь — а разделяются элементы не заливкой, а светлым кантом.

/// Фон меню: почти чёрное стекло. Верх чуть светлее низа — градиент дают
/// [`ФОН_ВЕРХ`]/[`ФОН_НИЗ`].
const ФОН_ВЕРХ: u32 = 0xD91A1A22;
const ФОН_НИЗ: u32 = 0xD90E0E14;
/// Светлая линия по верхней кромке — она и делает стекло стеклом.
const БЛИК: u32 = 0x26FFFFFF;
/// Кант вокруг меню и вокруг плашек.
const КАНТ: u32 = 0x1FFFFFFF;
/// Тень под меню.
const ТЕНЬ: u32 = 0x66000000;
/// Пустая карточка и фон кнопки.
const CARD_COLOR: u32 = 0x40FFFFFF;
/// Карточка «плюс» — ещё тише, она не выбор, а приглашение.
const PLUS_COLOR: u32 = 0x1AFFFFFF;
/// Подсветка под курсором. Наводится поверх обычного фона, поэтому светлая и
/// полупрозрачная — плотность даёт анимация подсветки, а не сам цвет.
const HOVER_COLOR: u32 = 0x2EFFFFFF;
/// Выбранное: белый кант и белая полоска под вкладкой.
const SEL_COLOR: u32 = 0xFFFFFFFF;
/// Значки и подписи: яркие у выбранного, приглушённые у остального.
const ТЕКСТ_ЯРКО: u32 = 0xFFF2F2F5;
const ТЕКСТ_ТИХО: u32 = 0x99C8C8D0;
/// Сторона кнопки удаления в углу карточки.
const DEL_SIZE: u32 = 28;
const DEL_BG: u32 = 0xB3101014;
const DEL_FG: u32 = 0xFFEDEDED;
/// Скругление кнопок и плашек в верхней полосе.
const УГОЛ_КНОПКИ: u32 = 8;
/// Кегль подписей у кнопок-источников.
const КЕГЛЬ: u32 = 13;

/// На сколько меню выезжает снизу, открываясь.
const ВЫЕЗД: f32 = 22.0;

/// Что показывает сетка меню.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Вкладка {
    /// Свои обои — то, что было в plx-wall всегда.
    Мои,
    /// Статичные картинки с openverse.
    Картинки,
    /// Живые обои с moewalls.
    Живые,
}

impl Вкладка {
    fn источник(self) -> Option<online::Источник> {
        match self {
            Вкладка::Мои => None,
            Вкладка::Картинки => Some(online::Источник::Картинки),
            Вкладка::Живые => Some(online::Источник::Живые),
        }
    }
}

/// Ответ фонового потока, ходившего в сеть.
enum ИзСети {
    /// Список находок вместе с уже разобранными миниатюрами.
    Список(Vec<online::Находка>, Vec<(u32, u32, Vec<u8>)>),
    /// Скачанные обои — путь к файлу.
    Скачано(std::path::PathBuf),
    Ошибка(String),
}

/// Миниатюры, УЖЕ приведённые к размеру карточки.
///
/// Заведён после замера 04.09.2026: из 11 мс кадра меню 7.5 уходило на
/// миниатюры, и каждый кадр анимации пересчитывал одно и то же — карточки за
/// кадр не меняются, а масштаб их и подавно. Теперь пересчёт идёт при смене
/// размера карточки или самих миниатюр, а кадр только укладывает готовые
/// строки (см. [`ui::Холст::картинка_готовая`]).
#[derive(Default)]
struct КэшКарточек {
    /// Под какой размер карточки посчитано. Не совпал — весь кэш недействителен.
    размер: (u32, u32),
    /// Готовая карточка и признак «в ней нет ни одной прозрачной точки» —
    /// по нему укладка идёт целой строкой (memcpy), а не по точкам.
    свои: Vec<Option<(Vec<u8>, bool)>>,
    сетевые: Vec<Option<(Vec<u8>, bool)>>,
    /// Карточки, уже ужатые под свою даль (см. [`Ужатая`]). Последние сверху.
    ужатые: Vec<Ужатая>,
    /// Карточки, которые прямо сейчас считаются в фоне: (сетевая, номер) →
    /// номер задания. Ответ принимается, только если номер совпал, — иначе
    /// миниатюра успела смениться, и результат посчитан по старой.
    в_работе: std::collections::HashMap<(bool, usize), u64>,
    след_задание: u64,
    /// Куда фоновые потоки кладут готовое (см. [`ГотоваяКарточка`]).
    канал: Option<(
        std::sync::mpsc::Sender<ГотоваяКарточка>,
        std::sync::mpsc::Receiver<ГотоваяКарточка>,
    )>,
}

/// Карточка, ужатая под размер ленты в фоновом потоке.
///
/// Ланцош на одну карточку — это десятки миллисекунд (замер 05.10.2026:
/// худшие кадры листания 88–125 мс, фаза «кэш карточек»), а при листании
/// длинного списка новые карточки въезжают в ленту каждые несколько кадров.
/// Считать их внутри кадра значило бы дёргать ленту ровно тогда, когда она
/// движется; поэтому кадр рисует сырую миниатюру, а готовая приходит сюда.
struct ГотоваяКарточка {
    сетевая: bool,
    idx: usize,
    задание: u64,
    размер: (u32, u32),
    готовая: (Vec<u8>, bool),
}

/// Карточка ленты, ужатая под свою даль, вместе с пеленой глубины.
///
/// Пока лента стоит, меню всё равно перерисовывается — от наведения мыши,
/// подсветки, спиннера загрузки, — и каждая дальняя карточка пересчитывалась
/// билинейно заново, хотя размер у неё прежний. Замер 27.09.2026: это и есть
/// фаза «карточки», 4–7 мс из кадра. Здесь хранится готовый результат, и
/// кадр кладёт его строками.
struct Ужатая {
    ключ: (bool, usize, u32, u32, u16),
    пиксели: Vec<u8>,
}

impl Ужатая {
    /// Сколько ужатых держим: видимых карточек в ленте не больше семи, и у
    /// каждой — своя даль. Двенадцать с запасом, это ~8 МБ на 604×340.
    const ПРЕДЕЛ: usize = 12;

    fn ключ(сетевая: bool, idx: usize, w: u32, h: u32, пелена: f32) -> (bool, usize, u32, u32, u16) {
        (сетевая, idx, w, h, (пелена * 1000.0).round() as u16)
    }
}

impl КэшКарточек {
    /// Выбросить всё: миниатюры сменились или карточка стала другого размера.
    fn сбросить(&mut self) {
        self.свои.clear();
        self.сетевые.clear();
        self.ужатые.clear();
        self.в_работе.clear();
    }

    /// Забыть ОДНУ карточку: пришла её миниатюра. Раньше на каждую пришедшую
    /// миниатюру выбрасывался весь кэш, и видимые карточки пересчитывались
    /// заново столько раз, сколько миниатюр в списке.
    fn забыть(&mut self, сетевая: bool, idx: usize) {
        let ряд = if сетевая { &mut self.сетевые } else { &mut self.свои };
        if let Some(место) = ряд.get_mut(idx) {
            *место = None;
        }
        self.ужатые.retain(|у| !(у.ключ.0 == сетевая && у.ключ.1 == idx));
        self.в_работе.remove(&(сетевая, idx));
    }

    fn ужатая(&self, ключ: &(bool, usize, u32, u32, u16)) -> Option<&Ужатая> {
        self.ужатые.iter().find(|ужатая| ужатая.ключ == *ключ)
    }

    fn положить_ужатую(&mut self, новая: Ужатая) {
        self.ужатые.retain(|старая| старая.ключ != новая.ключ);
        self.ужатые.insert(0, новая);
        self.ужатые.truncate(Ужатая::ПРЕДЕЛ);
    }

    /// Есть ли для карточки ГОТОВАЯ и притом полностью непрозрачная картинка.
    /// По этому ответу решается, рисовать ли под ней подложку.
    fn готова_непрозрачной(&self, сетевая: bool, idx: usize, карточка_с_обоями: bool) -> bool {
        if !карточка_с_обоями {
            return false;
        }
        let ряд = if сетевая { &self.сетевые } else { &self.свои };
        ряд.get(idx)
            .and_then(|м| м.as_ref())
            .map(|(_, непрозрачная)| *непрозрачная)
            .unwrap_or(false)
    }
}

/// Одна идущая загрузка обоев.
///
/// Их может быть сколько угодно разом: сеть у одного файла всё равно ждёт, а
/// не считает, и вторая загрузка первой не мешает. Ограничения нет намеренно —
/// щёлкать по карточкам быстрее, чем несколько раз в секунду, человек не
/// станет, а очередь с пределом добавила бы состояние, которое пришлось бы
/// показывать.
struct Загрузка {
    rx: std::sync::mpsc::Receiver<ИзСети>,
    /// Какая карточка выдачи качается — по ней рисуется отметка.
    карточка: usize,
}

#[derive(Clone, Copy)]
enum UiAction {
    SelectWallpaper(usize),
    AddWallpaper,
    DeleteWallpaper(usize),
    Scroll(i32),
    /// Переключить вкладку сетки.
    Вкладка(Вкладка),
    /// Скачать и поставить обои из сетевой выдачи.
    ВзятьИзСети(usize),
    /// Спросить, что искать, и перезапросить выдачу.
    Поиск,
    /// Показать меню фильтров выдачи.
    Фильтр,
    /// Взять обои из этого источника — индекс в [`ИСТОЧНИКИ`].
    Источник(usize),
    /// Дозапросить следующую страницу выдачи — карточка «далее» в конце ленты.
    Далее,
    /// Галочка «cycle»: бесконечные обои плиткой по холсту композитора.
    Цикл,
}

/// Переход между обоями: косая шторка — новые обои наползают на старые
/// наклонной полосой с мягким краем справа налево.
///
/// `from` — снимок ТОГО, ЧТО БЫЛО НА ЭКРАНЕ (готовый кадр из буфера показа), а
/// не исходная картинка: так один и тот же код работает и для статичных обоев,
/// и для видео, где «текущего кадра» в виде файла нет вообще.
///
/// `start` заводится не в момент клика, а когда пришёл ПЕРВЫЙ кадр новых
/// обоев: 4K-PNG декодируется сотни миллисекунд, и если пустить часы сразу,
/// переход успел бы кончиться до того, как появилось что показывать, — вместо
/// плавной смены был бы рывок.
struct Fade {
    from: Vec<u8>,
    /// Размер снимка. С viewporter буфер равен размеру КАДРА, а не экрана, и у
    /// новых обоев он свой — снимок приходится подгонять (см. render_wallpaper).
    dims: (u32, u32),
    start: Option<std::time::Instant>,
    /// Новых обоев ещё нет — они декодируются в фоне. Пока флаг стоит, часы
    /// не идут и смешивать нечего: на экране просто остаётся старый кадр.
    ждём: bool,
}

struct HitRect { x: u32, y: u32, w: u32, h: u32, action: UiAction }

/// Обои НА ОДНОМ выходе: своя layer-поверхность, свой viewport, свой размер.
///
/// **Почему на каждый выход своя.** Раньше plx-wall заводил ровно одну фоновую
/// поверхность — на `outputs.first()`. Второму монитору не доставалось ничего, и
/// parallax выкручивался тем, что брал чужой Background-слой и укладывал его плиткой
/// по холсту (`udev::build_wallpaper_tiles`). Плитка при этом была размером с
/// ЧУЖОЙ экран: на ультрашироком 2560×1080 картинка шириной 1920 не сходилась с
/// экраном и повторялась с видимым швом — это и есть жалоба «обои дублируются»
/// (замер 26.08.2026 на двухмониторном харнессе).
///
/// Буфер у всех фонов ОБЩИЙ и остаётся один: с `wp_viewporter` он равен кадру
/// картинки, а не экрана, и от размера выхода не зависит вовсе. Экраны
/// разводятся только прямоугольниками viewport — `src` (какой кусок кадра взять
/// под пропорцию этого экрана) и `dst` (куда растянуть). Платы за второй монитор
/// поэтому нет никакой: ни лишнего декодирования, ни лишней памяти.
struct Фон {
    /// Выход, на котором висит поверхность. Нужен, чтобы не заводить второй фон
    /// тому же выходу и чтобы убрать фон вместе с отключённым монитором.
    выход: WlOutput,
    surface: WlSurface,
    layer: ZwlrLayerSurfaceV1,
    /// Нет viewporter — нет и виевпорта; тогда работает прежний путь с
    /// растягиванием на процессоре, и он умеет только один экран (см.
    /// `render_wallpaper`).
    viewport: Option<WpViewport>,
    /// До первого `configure` протокол запрещает `attach`.
    configured: bool,
    /// Логический размер, который композитор отвёл этой поверхности. Берётся из
    /// `configure`, а не из `wl_output.Mode`: Mode отдаёт физические пиксели
    /// режима, а при scale ≠ 1 это разные числа.
    размер: (u32, u32),
}

/// Сколько фоновых поверхностей прямо сейчас держат буфер.
///
/// **Почему счётчик, а не флаг «свободен».** Мониторов у сеанса несколько, и
/// один и тот же кадр прицепляется к поверхности КАЖДОГО (см. `показать_на_фонах`).
/// Композитор шлёт `wl_buffer.release` отдельно на каждую поверхность, отпустившую
/// буфер, — то есть столько раз, сколько было `attach`. С прежним булевым флагом
/// первый же release объявлял слот свободным, пока второй монитор ещё показывал
/// из него кадр: декодер заливал туда следующий, и на втором экране получались
/// рваные полосы. Ноль — буфер не держит никто, писать можно.
type Занятость = std::sync::Arc<AtomicUsize>;

/// Постоянный буфер разделяемой памяти под кадр.
///
/// `занят` — сколько поверхностей ещё читают буфер. Писать можно только при нуле;
/// иначе на живых обоях получаются рваные кадры (полосы соседнего кадра). См.
/// [`Занятость`], `Dispatch<WlBuffer, Занятость>` и `take_free_slot`.
struct ShmSlot {
    buffer: WlBuffer,
    ptr: *mut u8,
    len: usize,
    занят: Занятость,
    /// Тот самый memfd, поверх которого лежит `ptr`.
    ///
    /// Раньше он закрывался сразу после создания буфера — отображение держит
    /// себя само. Теперь он нужен живым: декодер заливает кадр прямо в общую
    /// память через `splice`, а `splice` умеет писать только в файловый
    /// дескриптор (см. [`Заём`]).
    fd: OwnedFd,
}

impl Drop for ShmSlot {
    fn drop(&mut self) {
        self.buffer.destroy();
        unsafe { libc::munmap(self.ptr as *mut libc::c_void, self.len); }
    }
}

/// Завести пару постоянных буферов `w`×`h`. Пул уничтожаем сразу: отображение
/// держит сам wl_buffer, а живой пул на каждый кадр — это утечка и в памяти, и
/// в файловых дескрипторах КОМПОЗИТОРА (замер 04.08.2026: меню под курсором
/// добавляло parallax ~190 fd и 114 МБ за пару секунд, дальше он упирался в лимит
/// 1024 fd и рвал соединение).
fn make_slots(
    shm: &WlShm,
    qh: &QueueHandle<Config>,
    w: u32,
    h: u32,
) -> Option<Vec<ShmSlot>> {
    let size = (w * h * 4) as usize;
    let mut out = Vec::with_capacity(2);
    for _ in 0..2 {
        let (fd, ptr) = create_shm_fd(size)?;
        let owned = unsafe { OwnedFd::from_raw_fd(fd) };
        let pool = shm.create_pool(owned.as_fd(), size as i32, qh, ());
        // owned дальше переезжает в сам слот — см. поле ShmSlot::fd.
        let занят: Занятость = std::sync::Arc::new(AtomicUsize::new(0));
        let buffer = pool.create_buffer(
            0, w as i32, h as i32, (w * 4) as i32, wl_shm::Format::Argb8888, qh, занят.clone(),
        );
        pool.destroy(); // отображение держит сам буфер
        out.push(ShmSlot { buffer, ptr: ptr as *mut u8, len: size, занят, fd: owned });
    }
    Some(out)
}

/// Выбрать буфер, который композитор уже отпустил.
///
/// Если свободного нет (композитор ещё не прислал release), кадр пропускаем:
/// для обоев потерять кадр не страшно, а писать в показываемый буфер — это
/// видимые артефакты.
fn take_free_slot(slots: &[ShmSlot], last: usize) -> Option<usize> {
    for шаг in 1..=slots.len() {
        let i = (last + шаг) % slots.len();
        if slots[i].занят.load(Ordering::Relaxed) == 0 {
            return Some(i);
        }
    }
    None
}

/// Что декодер прислал главному циклу.
enum Кадр {
    /// Видео: кадр УЖЕ лежит в общей памяти, в слоте с этим номером.
    ///
    /// Так дешевле всего: `splice` перекладывает страницы трубы прямо в memfd
    /// слота, и ни одного копирования на нашей стороне не остаётся. Замер
    /// 14.08.2026 на 2560×1080 (свой стенд, 120 кадров): «прочитать в буфер и
    /// скопировать в общую память» — 12.77 мс CPU на кадр, `splice` — 7.94 мс.
    ВСлоте { слот: usize, шаг: std::time::Duration },
    /// gif: кадр приходит своим буфером. Там он собирается на холсте из
    /// заплаток (см. декодер gif), общей памятью это не заменить, да и незачем
    /// — гифы мелкие.
    Буфером { w: u32, h: u32, px: Vec<u8>, шаг: std::time::Duration },
}

/// Слот, отданный декодеру во временное пользование.
///
/// Внутри — ДУБЛИКАТ дескриптора, а не сам слот: обои могут смениться, старые
/// слоты уйдут вместе с их памятью, и опоздавший декодер зальёт кадр в свою
/// копию memfd, которую никто не читает. Без дубликата он писал бы по номеру
/// дескриптора, который ядро успело выдать чему-то другому.
struct Заём {
    индекс: usize,
    fd: OwnedFd,
}

/// Проигрыватель живых обоев.
///
/// Кадры готовит фоновый поток и кладёт в канал ёмкостью 1 — он же служит
/// тормозом: пока главный цикл не забрал кадр, декодер стоит, и память не
/// растёт (у видео кадр в размер экрана — это 11 МБ, держать очередь нельзя).
/// Темп задаёт главный цикл по `delay`, а не декодер.
struct Anim {
    /// Кадр: ширина, высота, пиксели, СОБСТВЕННАЯ длительность кадра и признак
    /// «уже BGRA». Длительность — Duration, а не миллисекунды: у видео 60 к/с
    /// это 16 666 мкс, и округление до 16 мс дало бы 62.5 к/с вместо 60.
    rx: std::sync::mpsc::Receiver<Кадр>,
    /// Куда главный цикл кладёт свободные слоты для декодера. Он же и тормоз:
    /// пока слотов нет (кадр показывается, обои закрыты полноэкранным окном),
    /// декодер стоит на `recv`, очередь ffmpeg переполняется, и тот засыпает
    /// сам.
    слоты: std::sync::mpsc::Sender<Заём>,
    /// Размер кадра, который отдаёт декодер. Нужен ЗАРАНЕЕ: слоты общей памяти
    /// заводятся под него ещё до первого кадра — заливать-то декодер будет
    /// прямо в них.
    dims: (u32, u32),
    next_at: std::time::Instant,
    /// Живой ffmpeg. В Drop его обязательно убиваем: иначе при смене обоев
    /// процессы копятся и продолжают декодировать в никуда.
    ///
    /// Ручку делим с потоком-читателем: при провале аппаратного декодера тот
    /// перезапускает процесс программным (см. start_anim), и убивать надо уже
    /// новый. `stop` отличает «декодер сам кончился» от «обои сменили»: во
    /// втором случае перезапускать нечего.
    child: std::sync::Arc<std::sync::Mutex<Option<std::process::Child>>>,
    stop: std::sync::Arc<AtomicBool>,
}

impl Drop for Anim {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        if let Ok(mut guard) = self.child.lock() {
            if let Some(mut c) = guard.take() {
                let _ = c.kill();
                let _ = c.wait();
            }
        }
    }
}

/// Умеет ли ffmpeg на этой машине декодировать видеокартой (NVDEC через CUDA).
///
/// Проверяем ОДИН раз и самым дешёвым способом — созданием hw-устройства, без
/// файла и без декодирования. Проверка обязательна: `-hwaccel cuda` НЕ
/// откатывается на программный декодер сам — если устройства нет, ffmpeg
/// печатает «No device available for decoder» и не отдаёт ни одного кадра
/// (проверено 05.08.2026), то есть обои просто не появились бы.
fn cuda_available() -> bool {
    static ОК: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ОК.get_or_init(|| {
        std::process::Command::new("ffmpeg")
            .args([
                "-loglevel", "error", "-init_hw_device", "cuda",
                "-f", "lavfi", "-i", "nullsrc", "-frames:v", "1", "-f", "null", "-",
            ])
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .map(|s| s.success())
            .unwrap_or(false)
    })
}

/// Кодек видеодорожки (`h264`, `vp9`, `av1`…) — по нему подбирается декодер
/// NVDEC, см. [`cuvid_аргументы`].
fn кодек_видео(path: &str) -> Option<String> {
    let out = std::process::Command::new("ffprobe")
        .args([
            "-v", "error",
            "-select_streams", "v:0",
            "-show_entries", "stream=codec_name",
            "-of", "default=nw=1:nk=1",
            path,
        ])
        .output()
        .ok()?;
    let имя = String::from_utf8_lossy(&out.stdout).trim().to_string();
    (!имя.is_empty()).then_some(имя)
}

/// Есть ли в этой сборке ffmpeg декодер `<кодек>_cuvid`.
fn cuvid_есть(кодек: &str) -> bool {
    static СПИСОК: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    let список = СПИСОК.get_or_init(|| {
        std::process::Command::new("ffmpeg")
            .args(["-hide_banner", "-loglevel", "error", "-decoders"])
            .output()
            .map(|o| String::from_utf8_lossy(&o.stdout).into_owned())
            .unwrap_or_default()
    });
    список.contains(&format!("{кодек}_cuvid"))
}

/// Аргументы, которыми ресайз обоев переносится ВНУТРЬ видеокарты: декодер
/// `<кодек>_cuvid` умеет сам обрезать и ужимать кадр (`-crop`, `-resize`), и
/// тогда на процессоре не остаётся ни масштабирования, ни лишнего кадра 4K.
///
/// Замер 12.08.2026 на обоях 3840×2160@60 h264 → экран 2560×1080, 120 кадров:
///
/// | как декодируем | CPU |
/// |---|---|
/// | программно | 8.13 с |
/// | `-hwaccel cuda`, `scale` в swscale (было) | 3.67 с |
/// | `h264_cuvid` с `-crop`/`-resize` (стало) | **2.29 с** |
///
/// `sws_flags` при этом не значит ничего (проверено на fast_bilinear, neighbor,
/// bilinear — разброс в пределах погрешности): платим не за качество фильтра, а
/// за сам пересчёт 4K и за перевод nv12→bgra.
///
/// Возвращает (декодер, `-crop`, `-resize`). Кроп нужен, чтобы кадр сел в экран
/// «по заполнению», как это делал `force_original_aspect_ratio=increase`: сперва
/// от исходника отрезается лишнее по длинной стороне, потом остаток ужимается
/// ровно в цель. Числа кропа чётные — иначе не поделится цветоразностный канал.
fn cuvid_аргументы(path: &str, цель: (u32, u32)) -> Option<(String, String, String)> {
    let (tw, th) = цель;
    let (sw, sh) = размер_видео(path)?;
    if tw == 0 || th == 0 || sw == 0 || sh == 0 {
        return None;
    }
    let кодек = кодек_видео(path)?;
    if !cuvid_есть(&кодек) {
        return None;
    }
    let (сверху, слева) = cuvid_кроп((sw, sh), цель);
    Some((
        format!("{кодек}_cuvid"),
        // Порядок в ffmpeg: top x bottom x left x right.
        format!("{сверху}x{сверху}x{слева}x{слева}"),
        format!("{tw}x{th}"),
    ))
}

/// Сколько отрезать от исходника, чтобы остаток был ровно в пропорции экрана:
/// возвращает (сверху и снизу, слева и справа). Одно из двух чисел всегда ноль
/// — режем только по одной оси.
fn cuvid_кроп(исходник: (u32, u32), цель: (u32, u32)) -> (u32, u32) {
    let ((sw, sh), (tw, th)) = (исходник, цель);
    let чёт = |v: u32| v & !1;
    if (sw as u64) * (th as u64) > (tw as u64) * (sh as u64) {
        // Исходник шире цели — режем по бокам.
        let нужно = чёт(((sh as u64 * tw as u64) / th as u64) as u32).min(sw);
        (0, чёт((sw - нужно) / 2))
    } else {
        // Исходник выше цели — режем сверху и снизу.
        let нужно = чёт(((sw as u64 * th as u64) / tw as u64) as u32).min(sh);
        (чёт((sh - нужно) / 2), 0)
    }
}

/// Запустить ffmpeg на живые обои. `hw` — декодировать видеокартой.
/// Размер картинки в видеофайле. Нужен, чтобы не поручать ffmpeg то, что он
/// делать не должен, — растягивание (см. [`start_anim`]).
fn размер_видео(path: &str) -> Option<(u32, u32)> {
    let out = std::process::Command::new("ffprobe")
        .args([
            "-v", "error",
            "-select_streams", "v:0",
            "-show_entries", "stream=width,height",
            "-of", "csv=p=0:s=x",
            path,
        ])
        .output()
        .ok()?;
    let текст = String::from_utf8_lossy(&out.stdout);
    let (w, h) = текст.trim().split_once('x')?;
    Some((w.trim().parse().ok()?, h.trim().parse().ok()?))
}

/// Собственная частота кадров ролика.
///
/// ffprobe отдаёт её дробью («60000/1001» — это 59.94), поэтому делим сами.
/// Берём r_frame_rate: у VFR-роликов это ВЕРХНЯЯ частота, то есть темп, в
/// котором ffmpeg отдаёт кадры после фильтра `fps`.
fn частота_видео(path: &str) -> Option<f64> {
    let out = std::process::Command::new("ffprobe")
        .args([
            "-v", "error",
            "-select_streams", "v:0",
            "-show_entries", "stream=r_frame_rate",
            "-of", "csv=p=0",
            path,
        ])
        .output()
        .ok()?;
    let текст = String::from_utf8_lossy(&out.stdout);
    let текст = текст.trim();
    let (числитель, знаменатель) = текст.split_once('/').unwrap_or((текст, "1"));
    let (ч, з) = (числитель.parse::<f64>().ok()?, знаменатель.parse::<f64>().ok()?);
    // 1000 к/с в файле — это не обои, а испорченные метаданные; такому кадру
    // мы всё равно не успеем ни декодироваться, ни доехать до экрана.
    (з > 0.0 && ч > 0.0).then(|| (ч / з).clamp(1.0, 240.0))
}

/// Потолок частоты кадров живых обоев, если он вообще нужен.
///
/// По умолчанию потолка НЕТ: обои идут с той же частотой, что и файл. Если
/// живые обои на 60 к/с окажутся дороже, чем хочется, `PLX_WALL_FPS=30` вернёт
/// прежнее поведение — ffmpeg прорядит кадры ещё до масштабирования, то есть
/// сэкономит и на декодировании тоже.
fn потолок_fps() -> Option<f64> {
    static ПОТОЛОК: std::sync::OnceLock<Option<f64>> = std::sync::OnceLock::new();
    *ПОТОЛОК.get_or_init(|| {
        std::env::var("PLX_WALL_FPS").ok()
            .and_then(|v| v.parse::<f64>().ok())
            .filter(|v| *v > 0.0)
    })
}

/// `цель` — размер, в который ffmpeg должен ужать кадр; `None` — отдавать как
/// есть, без фильтра масштабирования. `fps` — потолок частоты; `None` —
/// отдавать все кадры файла, как они в нём лежат.
fn spawn_ffmpeg(path: &str, цель: Option<(u32, u32)>, fps: Option<f64>, hw: bool) -> Option<std::process::Child> {
    let mut args: Vec<String> = vec![
        "-loglevel".into(), "error".into(), "-nostdin".into(),
    ];
    // Ужимать кадр лучше всего прямо в декодере видеокарты — тогда на CPU не
    // приезжает кадр 4K и swscale не работает вовсе (см. cuvid_аргументы).
    // Не вышло (нет такого декодера, ffprobe промолчал) — обычный путь:
    // -hwaccel cuda и масштабирование фильтром.
    let cuvid = if hw { цель.and_then(|ц| cuvid_аргументы(path, ц)) } else { None };
    match &cuvid {
        Some((декодер, crop, resize)) => args.extend([
            "-c:v".to_string(), декодер.clone(),
            "-crop".into(), crop.clone(),
            "-resize".into(), resize.clone(),
        ]),
        None if hw => args.extend(["-hwaccel".to_string(), "cuda".into()]),
        None => {}
    }
    args.extend([
        "-stream_loop".to_string(), "-1".into(), "-i".into(), path.to_string(),
        "-an".into(), "-sn".into(),
        // ВАЖЕН ПОРЯДОК: `fps` (когда потолок вообще задан) стоит ПЕРВЫМ в
        // цепочке фильтров, до scale. Раньше частоту резал выходной ключ
        // `-r 15`, то есть уже ПОСЛЕ фильтров: масштабирование 4K→2560×1080
        // честно считалось на всех 60 кадрах источника, а три из четырёх
        // результатов выбрасывались. Замер на green-tree (3840×2160@60): 36.9 с
        // CPU на 12 с видео против 27.9 с после переноса fps в начало (−24%).
        //
        // Без потолка фильтра нет вовсе: `fps=<та же частота>` — это лишний
        // проход по кадру ради ничего, а прореживать нечего.
        "-vf".into(),
        {
            // Кадр, ужатый декодером, второй раз масштабировать нечем.
            let масштаб = цель.filter(|_| cuvid.is_none()).map(|(w, h)| {
                format!("scale={w}:{h}:force_original_aspect_ratio=increase,crop={w}:{h}")
            });
            match (fps, масштаб) {
                (Some(f), Some(s)) => format!("fps={f},{s}"),
                (Some(f), None) => format!("fps={f}"),
                (None, Some(s)) => s,
                // Пустая цепочка фильтров ffmpeg не нравится — просим копию.
                (None, None) => "null".to_string(),
            }
        },
        // bgra, а не rgba: ровно то, что ждёт wl_shm — попиксельный
        // своп на 2.7 млн пикселей за кадр просто исчезает.
        "-f".into(), "rawvideo".into(), "-pix_fmt".into(), "bgra".into(), "-".into(),
    ]);
    std::process::Command::new("ffmpeg")
        .args(&args)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null())
        .spawn()
        .map_err(|e| eprintln!("plx-wall: ffmpeg не запустился: {e}"))
        .ok()
}

/// Видео ли это (для них кадры гонит ffmpeg).
fn is_video(path: &str) -> bool {
    matches!(
        std::path::Path::new(path).extension().and_then(|e| e.to_str())
            .unwrap_or("").to_lowercase().as_str(),
        "mp4" | "webm" | "mkv" | "mov" | "avi"
    )
}

/// Залить очередной кадр из трубы ffmpeg прямо в общую память слота.
///
/// `splice` перекладывает страницы трубы в memfd силами ядра — на нашей
/// стороне не остаётся ни чтения в буфер, ни копирования из него в общую
/// память. Замер 14.08.2026 на стенде (2560×1080, 120 кадров, тот же ffmpeg):
///
/// | как забираем кадр | CPU на кадр |
/// |---|---|
/// | `read_exact` в буфер + копия в общую память | 12.77 мс |
/// | `splice` прямо в memfd слота | **7.94 мс** |
///
/// Расширение самой трубы (`F_SETPIPE_SZ` до мегабайта) на том же стенде не
/// дало НИЧЕГО (9.0 против 9.5 мс на кадр) — платим не за системные вызовы, а
/// за перекладывание мегабайтов, поэтому его и не делаем.
///
/// `false` = труба кончилась (ffmpeg завершился или его убили).
fn залить_кадр(труба: &impl std::os::fd::AsRawFd, заём: &Заём, размер: usize) -> bool {
    use std::os::fd::AsRawFd;
    let mut залито = 0usize;
    while залито < размер {
        // Смещение в файле ведём сами: splice с указателем на смещение не
        // трогает позицию дескриптора, и слот можно заливать с начала снова и
        // снова.
        let mut смещение = залито as libc::loff_t;
        let n = unsafe {
            libc::splice(
                труба.as_raw_fd(), std::ptr::null_mut(),
                заём.fd.as_raw_fd(), &mut смещение,
                размер - залито, 0,
            )
        };
        match n {
            0 => return false,             // труба закрыта — ffmpeg кончился
            n if n < 0 => {
                let e = std::io::Error::last_os_error();
                if e.kind() == std::io::ErrorKind::Interrupted { continue; }
                eprintln!("plx-wall: splice кадра не удался: {e}");
                return false;
            }
            n => залито += n as usize,
        }
    }
    true
}

/// Ужатая под этот экран копия ролика — та, которую дешевле крутить.
///
/// Живые обои 4K на экране 2560×1080 стоят дороже всего не декодированием, а
/// тем, что КАЖДЫЙ кадр после декодера ужимается swscale'ом. Замер 20.09.2026
/// на «serene-cherry-blossom-tree» (3840×2160@30, 11.6 с видео):
///
/// | что крутим | CPU на эти 11.6 с |
/// |---|---|
/// | 4K + `scale=2560:1080` на каждом кадре | 25.0 с (≈215% ядра) |
/// | уже ужатая копия, фильтров нет | 13.8 с (≈119% ядра) |
///
/// Поэтому ужимаем ОДИН РАЗ и кладём рядом в кэш. Пока копии нет, ролик идёт
/// как раньше — ужимать на лету; копия считается фоном (`nice 19`), и её
/// подхватит следующий запуск обоев. Ждать её здесь нельзя: это полминуты, а
/// обои нужны сейчас.
///
/// Свежесть — по времени правки: исходник переписали, значит копия устарела.
/// Недосчитанная копия называется `*.часть.mp4` и переименовывается только целиком,
/// так что оборванный на полпути ffmpeg (выход из сеанса, выключение) не
/// оставляет обрубка, который потом покажут вместо обоев.
fn ужатая_копия(path: &str, w: u32, h: u32) -> Option<String> {
    use std::sync::Mutex;
    /// Что уже считается прямо сейчас: второй такой же ffmpeg не нужен.
    static СЧИТАЕМ: Mutex<Vec<String>> = Mutex::new(Vec::new());

    if w == 0 || h == 0 {
        return None;
    }
    let (iw, ih) = размер_видео(path)?;
    if iw == 0 || ih == 0 {
        return None;
    }
    // Ужимать имеет смысл, только когда ужимать есть что: копия того же
    // размера (или крупнее всего на четверть) не окупит ни места, ни счёта.
    if (iw as u64) * (ih as u64) < (w as u64) * (h as u64) * 5 / 4 {
        return None;
    }

    let исходник = std::path::Path::new(path);
    let имя = исходник.file_stem()?.to_string_lossy().to_string();
    let каталог = std::path::PathBuf::from(format!("{}/.cache/plx-wall/ужатые", home()));
    let цель = каталог.join(format!("{имя}-{w}x{h}.mp4"));

    let правка = |p: &std::path::Path| std::fs::metadata(p).and_then(|m| m.modified()).ok();
    if let (Some(готова), Some(своя)) = (правка(&цель), правка(исходник)) {
        if готова >= своя && std::fs::metadata(&цель).map(|m| m.len()).unwrap_or(0) > 0 {
            return Some(цель.to_string_lossy().to_string());
        }
    }

    // Копии нет — ставим её в очередь и уходим: этот запуск идёт по исходнику.
    let ключ = цель.to_string_lossy().to_string();
    {
        let Ok(mut считаем) = СЧИТАЕМ.lock() else { return None };
        if считаем.iter().any(|к| *к == ключ) {
            return None;
        }
        считаем.push(ключ.clone());
    }
    let путь = path.to_string();
    std::thread::spawn(move || {
        let _ = std::fs::create_dir_all(&каталог);
        // Расширение .mp4 обязано остаться ПОСЛЕДНИМ: формат вывода ffmpeg
        // выбирает по нему, и на `…mp4.part` он честно отвечает «Unable to
        // choose an output format» (поймано на харнессе 20.09.2026).
        let частями = format!("{ключ}.часть.mp4");
        // `nice 19`: считается это единожды и в фоне, а на переднем плане в
        // этот момент вполне может идти игра.
        let итог = std::process::Command::new("nice")
            .args([
                "-n", "19", "ffmpeg", "-loglevel", "error", "-nostdin", "-y",
                "-i", &путь, "-an", "-sn",
                "-vf", &format!("scale={w}:{h}:force_original_aspect_ratio=increase,crop={w}:{h}"),
                // veryfast + crf 20: ужимаем ОДИН раз и смотрим потом всегда,
                // но платить за это минутами счёта незачем — на глаз разница с
                // медленными пресетами на обоях не читается.
                "-c:v", "libx264", "-preset", "veryfast", "-crf", "20",
                "-pix_fmt", "yuv420p", "-movflags", "+faststart",
                &частями,
            ])
            .status();
        match итог {
            Ok(код) if код.success() => {
                if std::fs::rename(&частями, &ключ).is_ok() {
                    eprintln!("plx-wall: ужатая копия обоев готова: {ключ}");
                }
            }
            _ => {
                let _ = std::fs::remove_file(&частями);
                eprintln!("plx-wall: ужать обои не вышло, крутим исходник");
            }
        }
        if let Ok(mut считаем) = СЧИТАЕМ.lock() {
            считаем.retain(|к| *к != ключ);
        }
    });
    None
}

/// Запускает фоновое декодирование живых обоев под размер экрана `w`×`h`.
fn start_anim(path: &str, w: u32, h: u32) -> Option<Anim> {
    use std::sync::mpsc::sync_channel;
    let (tx, rx) = sync_channel::<Кадр>(1);

    if is_video(path) {
        // Ужатая под этот экран копия ролика, если она уже посчитана (см.
        // `ужатая_копия`): её размер ровно экранный, и ужимать каждый кадр
        // фильтром ffmpeg не придётся вовсе — это вдвое меньше CPU на обои.
        // Копии ещё нет — крутим исходник, как раньше; копия считается фоном и
        // подхватится следующим запуском.
        let ужатая = ужатая_копия(path, w, h);
        let path: &str = ужатая.as_deref().unwrap_or(path);

        // Канал слотов: главный цикл кладёт сюда свободную общую память,
        // декодер заливает в неё кадр. Ёмкости не задаём — слотов всего два,
        // больше в канале и не окажется.
        let (выдать_слот, взять_слот) = std::sync::mpsc::channel::<Заём>();
        // Кадры просим в BGRA — конвертировать на нашей стороне дороже.
        // -stream_loop -1 — бесконечный повтор.
        //
        // Частота — РОДНАЯ частота файла. Раньше здесь стоял жёсткий потолок в
        // 15 к/с «обои не стоят 60 к/с процессорного времени», и он был виден
        // глазом: плавная панорама в ролике на 60 к/с шла рывками. Потолок
        // остался, но только по требованию — PLX_WALL_FPS (см. потолок_fps).
        //
        // Декодируем видеокартой, когда она есть: 4K@60 h264 — это ~28 с CPU на
        // каждые 12 с видео (замер 05.08.2026, зелёное дерево 3840×2160),
        // против 5.7 с через NVDEC.
        let своя = частота_видео(path).unwrap_or(30.0);
        let потолок = потолок_fps().filter(|п| *п < своя);
        let fps = потолок.unwrap_or(своя);
        // Длительность кадра считаем в микросекундах: 60 к/с — это 16 666 мкс,
        // и округление до миллисекунд промахнулось бы мимо частоты экрана.
        let шаг = std::time::Duration::from_micros((1_000_000.0 / fps).round() as u64);

        // Размер, в котором просим кадры. Ужимать большой ролик в ffmpeg —
        // полезно: меньше и счёта, и данных через трубу. А вот РАСТЯГИВАТЬ там
        // мелкий ролик — чистая потеря, потому что то же самое кадрирование с
        // центрированием делает blit_scaled уже на нашей стороне.
        //
        // Замер 09.08.2026 на этих обоях (AV1 1280×720 → экран 3840×2160),
        // 120 кадров: с масштабированием в ffmpeg — 13.4 с CPU и 474 МБ/с
        // через трубу, без него — 3.8 с и 52 МБ/с. Разница в 3.5 раза, и
        // ffmpeg на живой машине держал 264% CPU при неподвижной картинке.
        // Аппаратный декодер тут не помог бы: у Comet Lake нет AV1 вовсе.
        //
        // Цена — качество растягивания: blit_scaled берёт ближайшего соседа,
        // ffmpeg брал бикубик. Ролик мельче экрана станет заметно грубее.
        let (вых_w, вых_h, цель) = match размер_видео(path) {
            Some((iw, ih)) if iw > 0 && ih > 0
                && (w as f64 / iw as f64).max(h as f64 / ih as f64) >= 1.0 =>
            {
                // Исходник мельче экрана — берём как есть, растянет blit_scaled.
                // Равный экрану — тем более: это ровно случай ужатой копии
                // (см. `ужатая_копия`), и звать там scale значило бы гонять
                // swscale ради тождества.
                (iw, ih, None)
            }
            // Исходник крупнее экрана (или ffprobe промолчал) — ужимаем в
            // ffmpeg, как и раньше.
            _ => (w, h, Some((w, h))),
        };

        let hw = cuda_available();
        let child = std::sync::Arc::new(std::sync::Mutex::new(Some(
            spawn_ffmpeg(path, цель, потолок, hw)?,
        )));
        let stop = std::sync::Arc::new(AtomicBool::new(false));
        let (поток_child, поток_stop) = (child.clone(), stop.clone());
        let путь = path.to_string();
        std::thread::spawn(move || {
            // Размер кадра — тот, в котором его отдаёт ffmpeg, а он теперь не
            // обязан совпадать с экраном (см. выбор `цель` выше).
            let кадр = (вых_w as usize) * (вых_h as usize) * 4;
            let mut hw = hw;
            loop {
                // Забираем stdout только что запущенного процесса.
                let out = поток_child.lock().ok().and_then(|mut g| {
                    g.as_mut().and_then(|c| c.stdout.take())
                });
                let Some(out) = out else { return };

                let mut кадров = 0u64;
                loop {
                    // Ждём, пока главный цикл отдаст свободный слот. Это и есть
                    // тормоз всего конвейера: пока показывать некуда, мы стоим
                    // здесь, труба ffmpeg переполняется, и он засыпает сам.
                    // Ошибка = главный цикл выбросил Anim, уходим.
                    let Ok(заём) = взять_слот.recv() else { return };
                    if !залить_кадр(&out, &заём, кадр) {
                        break; // ffmpeg закончился или его убили
                    }
                    кадров += 1;
                    // Свежий буфер вместо clone: read_exact всё равно перезапишет
                    // его целиком, а копия 11 МБ на кадр — это 165 МБ/с memcpy
                    // впустую.
                    // Ошибка отправки = главный цикл выбросил Anim, уходим.
                    if tx.send(Кадр::ВСлоте { слот: заём.индекс, шаг }).is_err() {
                        return;
                    }
                }

                if поток_stop.load(Ordering::SeqCst) {
                    return; // обои сменили — перезапускать нечего
                }
                // Аппаратный декодер не отдал НИ ОДНОГО кадра: устройство есть,
                // но этот кодек ему не по зубам (AV1 на старой карте, редкий
                // профиль). Молча повторяем программным — обои важнее экономии.
                if hw && кадров == 0 {
                    hw = false;
                    eprintln!("plx-wall: аппаратный декодер не справился, повтор программным");
                    let Some(новый) = spawn_ffmpeg(&путь, цель, потолок, false) else { return };
                    match поток_child.lock() {
                        Ok(mut g) => *g = Some(новый),
                        Err(_) => return,
                    }
                    continue;
                }
                return;
            }
        });
        return Some(Anim {
            rx,
            слоты: выдать_слот,
            dims: (вых_w, вых_h),
            next_at: std::time::Instant::now(),
            child,
            stop,
        });
    }

    // ── GIF ──────────────────────────────────────────────────────────────────
    //
    // Кадр в gif — это НЕ картинка целиком, а заплатка: свой прямоугольник
    // (left, top, width, height), своя прозрачность и правило, что делать с
    // предыдущим кадром (dispose). Раньше plx-wall брал буфер кадра как есть и
    // растягивал его на весь экран, игнорируя и смещение, и прозрачность.
    // Итог ровно тот, на который жаловались: у живых обоев поверх картинки
    // мигали прямоугольные куски — то чёрные (там, где в заплатке
    // прозрачность), то не на своём месте (заплатку в пол-экрана тянуло на
    // весь экран). Проверено 04.08.2026: `test_anim.gif` показывался красной
    // кашей с радужной полосой снизу.
    //
    // Теперь собираем кадры как положено: держим ХОЛСТ в логический размер
    // gif, накладываем на него каждую заплатку, отдаём наружу снимок холста и
    // применяем dispose. Кадры не копим — декодер идёт потоком (канал ёмкостью
    // 1 его тормозит), а на повтор просто перечитываем файл: иначе гиф в
    // 1080p на сотню кадров занял бы гигабайт.
    let path = path.to_string();

    // Проба: анимация ли это вообще. Одиночный кадр — обычная картинка, и
    // показывать её должен статичный путь (иначе мы зря держим поток).
    {
        let file = std::fs::File::open(&path).ok()?;
        let mut d = gif::DecodeOptions::new();
        d.set_color_output(gif::ColorOutput::RGBA);
        let mut r = d.read_info(file).ok()?;
        let mut n = 0;
        while n < 2 {
            match r.read_next_frame() {
                Ok(Some(_)) => n += 1,
                _ => break,
            }
        }
        if n < 2 { return None; }
    }

    std::thread::spawn(move || {
        loop {
            let Ok(file) = std::fs::File::open(&path) else { return };
            let mut d = gif::DecodeOptions::new();
            d.set_color_output(gif::ColorOutput::RGBA);
            let Ok(mut r) = d.read_info(file) else { return };
            let (sw, sh) = (r.width() as usize, r.height() as usize);
            if sw == 0 || sh == 0 { return; }
            // Холст живёт от кадра к кадру: заплатки накладываются на него.
            let mut холст = vec![0u8; sw * sh * 4];
            loop {
                let f = match r.read_next_frame() {
                    Ok(Some(f)) => f,
                    _ => break,
                };
                let (fx, fy) = (f.left as usize, f.top as usize);
                let (fw, fh) = (f.width as usize, f.height as usize);
                // dispose = Previous: после показа холст обязан вернуться к
                // тому, что было под заплаткой, — сохраняем этот кусок.
                let сохранённое = (f.dispose == gif::DisposalMethod::Previous)
                    .then(|| вырезать(&холст, sw, fx, fy, fw, fh));

                // Накладываем заплатку. Прозрачные пиксели (alpha 0) НЕ
                // копируем — под ними должен остаться прежний кадр.
                for y in 0..fh {
                    let dy = fy + y;
                    if dy >= sh { break; }
                    for x in 0..fw {
                        let dx = fx + x;
                        if dx >= sw { break; }
                        let s = (y * fw + x) * 4;
                        if s + 3 >= f.buffer.len() || f.buffer[s + 3] == 0 { continue; }
                        let d = (dy * sw + dx) * 4;
                        холст[d..d + 4].copy_from_slice(&f.buffer[s..s + 4]);
                    }
                }

                // Наружу отдаём снимок холста: BGRA (как ждёт wl_shm) и
                // непрозрачный — обои не должны просвечивать до чёрного фона.
                let mut кадр = холст.clone();
                for c in кадр.chunks_exact_mut(4) { c.swap(0, 2); c[3] = 255; }
                // delay в gif — сотые доли секунды; 0 трактуем как 100 мс
                // (так же поступают браузеры). Ничего сверх этого не
                // округляем: у гифа своя частота записана в каждом кадре, она
                // и есть исходная.
                let ms = if f.delay == 0 { 100 } else { f.delay as u64 * 10 };
                let шаг = std::time::Duration::from_millis(ms);
                if tx.send(Кадр::Буфером { w: sw as u32, h: sh as u32, px: кадр, шаг }).is_err() {
                    return; // главный цикл выбросил Anim
                }

                match f.dispose {
                    gif::DisposalMethod::Background => {
                        // Участок кадра гасим в прозрачность.
                        for y in 0..fh {
                            let dy = fy + y;
                            if dy >= sh { break; }
                            let от = (dy * sw + fx.min(sw)) * 4;
                            let до = (dy * sw + (fx + fw).min(sw)) * 4;
                            холст[от..до].fill(0);
                        }
                    }
                    gif::DisposalMethod::Previous => {
                        if let Some(кусок) = сохранённое {
                            вернуть(&mut холст, sw, fx, fy, fw, fh, &кусок);
                        }
                    }
                    _ => {}
                }
            }
        }
    });
    // У gif своего процесса нет — убивать в Drop нечего.
    // У gif своего процесса нет — убивать в Drop нечего, и слоты ему не нужны:
    // кадр он собирает у себя на холсте. Канал слотов заводим пустым, чтобы
    // поле было одно на оба вида живых обоев.
    let (выдать_слот, _) = std::sync::mpsc::channel::<Заём>();
    Some(Anim {
        rx,
        слоты: выдать_слот,
        // Слоты общей памяти gif не нужны (кадр он собирает на своём холсте),
        // поэтому размер нулевой — по нему одолжить_слоты и не берётся за дело.
        dims: (0, 0),
        next_at: std::time::Instant::now(),
        child: std::sync::Arc::new(std::sync::Mutex::new(None)),
        stop: std::sync::Arc::new(AtomicBool::new(false)),
    })
}

/// Копия прямоугольника холста (для gif-dispose = Previous).
fn вырезать(холст: &[u8], sw: usize, x: usize, y: usize, w: usize, h: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(w * h * 4);
    for row in 0..h {
        let dy = y + row;
        let от = (dy * sw + x) * 4;
        let до = от + w * 4;
        if до <= холст.len() {
            out.extend_from_slice(&холст[от..до]);
        } else {
            out.resize(out.len() + w * 4, 0);
        }
    }
    out
}

/// Вернуть на место кусок, снятый [`вырезать`].
fn вернуть(холст: &mut [u8], sw: usize, x: usize, y: usize, w: usize, h: usize, кусок: &[u8]) {
    for row in 0..h {
        let dy = y + row;
        let от = (dy * sw + x) * 4;
        let до = от + w * 4;
        let s = row * w * 4;
        if до <= холст.len() && s + w * 4 <= кусок.len() {
            холст[от..до].copy_from_slice(&кусок[s..s + w * 4]);
        }
    }
}

// ── Состояние ───────────────────────────────────────────────────────────────

struct Config {
    outputs: Vec<(WlOutput, u32, u32)>,
    /// Обои на КАЖДОМ выходе — по одному [`Фон`] на монитор (см. `setup_layers`).
    фоны: Vec<Фон>,
    ol_surface: Option<WlSurface>,
    ol_layer: Option<ZwlrLayerSurfaceV1>,
    compositor: Option<WlCompositor>,
    shm: Option<WlShm>,
    layer_shell: Option<ZwlrLayerShellV1>,
    pointer: Option<WlPointer>,
    /// Сенсорный экран — заводится, только когда seat объявил касания (см.
    /// Dispatch<WlSeat>): просить wl_touch у seat без них — ошибка протокола.
    touch: Option<WlTouch>,
    /// Палец, который сейчас лежит на меню (см. [`Касание`]).
    касание: Option<Касание>,
    qh: Option<QueueHandle<Config>>,
    signalfd: Option<i32>,
    wallpapers: Vec<String>,
    current: usize,
    img: Option<(u32, u32, Vec<u8>)>,
    thumbnails: Vec<(u32, u32, Vec<u8>)>,
    /// Какие из `thumbnails` уже настоящие, а не серая заглушка. Нужен, чтобы
    /// при смене списка (добавили, удалили обои) переносить готовые по пути,
    /// а не считать все заново.
    миниатюра_готова: Vec<bool>,
    /// Для какого списка обоев посчитаны thumbnails — чтобы не декодировать
    /// картинки заново на каждое открытие меню (см. load_thumbnails).
    thumbs_for: Vec<String>,
    /// Обои декодируются в ОТДЕЛЬНОМ потоке: 4K-PNG разбирается сотни
    /// миллисекунд, и синхронный вызов подвешивал весь цикл — меню замирало,
    /// а обои «применялись с задержкой». Здесь ждём результат.
    pending_img: Option<std::sync::mpsc::Receiver<Option<(u32, u32, Vec<u8>)>>>,
    /// Миниатюры тоже считаются в фоне: три 4K-PNG декодировались секундами, и
    /// всё это время меню просто не появлялось на экране.
    pending_thumbs: Option<std::sync::mpsc::Receiver<(usize, (u32, u32, Vec<u8>))>>,
    /// Живые обои: mp4/webm/mkv через ffmpeg и анимированный gif своим
    /// декодером. Кадры приходят из фонового потока по одному.
    ///
    /// Запасной путь для видео: работает везде, но платит процессором за
    /// декодирование, перевод в BGRA и перекачку кадров через трубу. Основной
    /// путь — `hw` ниже; сюда сваливаемся, когда видеокарта этот ролик не
    /// потянула. Одновременно взведён быть может только один из двух.
    anim: Option<Anim>,
    /// Живые обои, декодированные видеокартой прямо в видеопамять.
    ///
    /// Основной путь для видео. Кадр приезжает готовым dmabuf-буфером, и
    /// показать его — это прицепить `wl_buffer`: ни декодирования, ни
    /// перевода цвета, ни копирования на процессоре не остаётся вовсе.
    /// Замер 15.08.2026 на h264 2560×1440@60: 0.40 с CPU на 300 кадров против
    /// 15.7 с у пути через ffmpeg.
    hw: Option<hwvideo::HwВидео>,
    /// Готовые `wl_buffer` под поверхности VAAPI, по номеру поверхности.
    ///
    /// Пул декодера конечен и невелик (на этой машине — 5 поверхностей), а
    /// кадры идут по кругу, поэтому буферы заводятся один раз и живут до смены
    /// обоев. Счётчик — тот же, что у shm-слотов: сколько поверхностей ещё
    /// читают буфер (см. [`Занятость`]).
    hw_буферы: std::collections::HashMap<usize, (WlBuffer, Занятость)>,
    /// Порядок появления поверхностей — по нему выбирается жертва, когда
    /// буферов накопилось больше ПРЕДЕЛ_HW_БУФЕРОВ.
    hw_порядок: std::collections::VecDeque<usize>,
    /// Буферы, которые пора уничтожить, но композитор их ещё не отпустил.
    ///
    /// Выдернуть буфер с экрана нельзя — это рябь на обоях, — поэтому
    /// устаревшие ждут здесь своего `wl_buffer::release`.
    hw_мусор: Vec<(WlBuffer, Занятость)>,
    /// Кадры, которые композитор ещё не отпустил.
    ///
    /// Держатель не даёт декодеру забрать поверхность обратно в пул и записать
    /// поверх того, что прямо сейчас на экране. Роняем по `wl_buffer::release`.
    hw_на_экране: Vec<(Занятость, hwvideo::Держатель)>,
    /// Срок показа следующего аппаратного кадра.
    hw_срок: std::time::Instant,
    /// Путь ЖИВЫХ обоев, которые сейчас играют (видео или многокадровый gif).
    ///
    /// Нужен ровно для одного — поднять декодер обратно, если его поток умер
    /// (см. [`декодер_умер`]). У статичных обоев поле пустое.
    живые_путь: Option<String>,
    /// Когда пробовать поднять умерший декодер и какая это попытка по счёту.
    живые_рестарт: Option<(std::time::Instant, u32)>,
    /// Глобал linux-dmabuf. Нет его — аппаратный путь недоступен, и видео
    /// поедет через `anim`.
    dmabuf: Option<ZwpLinuxDmabufV1>,
    /// Пары «формат + модификатор», которые композитор объявил поддерживаемыми.
    ///
    /// Проверять обязательно: `create_immed` на неподдерживаемом сочетании —
    /// это протокольная ошибка, то есть мгновенная смерть клиента, а не
    /// аккуратный отказ. Не нашли своё сочетание — уходим на запасной путь.
    dmabuf_форматы: std::collections::HashSet<(u32, u64)>,
    /// Обои сейчас на экране видно (композитор отвечает на кадровые запросы).
    видно: bool,
    /// Кадр живых обоев, который декодер уже залил в общую память: номер слота
    /// и его размер. Пока он взведён, render_wallpaper НЕ заполняет буфер —
    /// там уже лежит готовый кадр (см. Кадр::ВСлоте).
    кадр_слота: Option<(usize, u32, u32)>,
    /// Слоты, отданные декодеру: в них он прямо сейчас пишет, трогать нельзя.
    слоты_у_декодера: Vec<bool>,
    /// Когда заказан кадровый callback, на который ещё не ответили. Молчание
    /// дольше [`ОЖИДАНИЕ_КАДРА`] значит «обои закрыты, можно спать».
    кадр_заказан: Option<std::time::Instant>,
    /// Композитор хоть раз ответил на кадровый запрос. Пока не ответил ни разу,
    /// засыпать НЕЛЬЗЯ: на композиторе, который layer-поверхностям кадровых
    /// callback'ов не шлёт вовсе, обои иначе замерли бы навсегда.
    callback_был: bool,
    /// Кадр уже в BGRA (как ждёт wl_shm) — своп не нужен. Так приходят кадры
    /// видео (ffmpeg отдаёт bgra) и gif (свопнуты один раз при декодировании).
    img_bgra: bool,
    /// Два постоянных буфера обоев: пишем по очереди в тот, что не показан.
    /// Раньше на КАЖДЫЙ кадр создавались memfd + mmap + пул + wl_buffer —
    /// именно это, вместе с Lanczos, и съедало треть ядра.
    bg_slots: Vec<ShmSlot>,
    bg_slot: usize,
    bg_dims: (u32, u32),
    /// Такая же постоянная пара под меню. Раньше на КАЖДУЮ перерисовку
    /// (а она шла на каждое движение мыши) заводились новые memfd + пул +
    /// wl_buffer, и никто их не уничтожал: `drop` у прокси wayland-client
    /// ничего не шлёт серверу. Утекало не у нас, а у КОМПОЗИТОРА — он держал
    /// по дескриптору и по 1.4 МБ на каждую, упирался в лимит 1024 fd и рвал
    /// соединение. Отсюда и «обои пропали, меню не открывается».
    ol_slots: Vec<ShmSlot>,
    ol_slot: usize,
    /// Кадр обоев не удалось отдать (оба буфера ещё у композитора) — повторить.
    bg_pending: bool,
    /// wp_viewporter, если композитор его предлагает. Нет — работаем как
    /// раньше, растягивая кадры на процессоре.
    viewporter: Option<WpViewporter>,
    /// Пользователь нажал «Поиск»: меню прячем, а строку ввода (rofi)
    /// запускаем из главного цикла — и только после того, как кадр со скрытым
    /// меню действительно ушёл композитору. См. ветку UiAction::Поиск.
    запросить_поиск: bool,
    /// То же для меню фильтров: его тоже показывает rofi, и по той же
    /// причине — своего шрифта у plx-wall нет.
    запросить_фильтр: bool,
    /// То же для карточки «+»: диалог выбора файла.
    запросить_файл: bool,
    /// Открытый прямо сейчас rofi/диалог: его ответ придёт сюда. Пока он
    /// открыт, новых не запускаем.
    выбор_меню: Option<std::sync::mpsc::Receiver<ОтветВыбора>>,
    /// Чем сужена сетевая выдача (см. [`online::Фильтры`]).
    фильтры: online::Фильтры,
    /// Галочка «cycle» (см. [`сообщить_цикл`]). Помнится между запусками.
    цикл: bool,
    /// Разделы moewalls для меню фильтров. Спрашиваются у сайта один раз за
    /// сеанс, при первом открытии меню: до него они не нужны, а сеть ждать
    /// незачем.
    разделы_живых: Vec<(String, String)>,
    /// Карточка под курсором. Перерисовываем меню только когда она сменилась —
    /// иначе одно движение мыши через меню давало сотню перерисовок.
    hover: Option<usize>,
    /// Что показать при старте. Запускается не сразу: живым обоям нужен размер
    /// экрана, а он известен только после первого wl_output::Mode.
    стартовые: Option<String>,
    overlay_visible: bool,
    /// Отдана ли меню клавиатура ПРЯМО СЕЙЧАС. Держим отдельно от
    /// `overlay_visible`, чтобы просить композитор только на переходе, а не
    /// каждый кадр анимации.
    ol_клавиатура: bool,
    cursor_x: f64,
    cursor_y: f64,
    hit_rects: Vec<HitRect>,
    dirty: bool,
    /// Идущий сейчас переход между обоями (см. [`Fade`]).
    fade: Option<Fade>,
    /// Статичные обои, уже растянутые под выход и переведённые в BGRA.
    ///
    /// Нужен из-за перехода: он перерисовывает кадр десятки раз, а Lanczos на
    /// 4K стоит сотни миллисекунд — без кэша «плавная» смена превратилась бы
    /// в слайд-шоу из трёх кадров. Сбрасывается вместе с `img`.
    scaled: Option<Vec<u8>>,
    /// Что показывает сетка: свои обои или выдачу из сети.
    вкладка: Вкладка,
    /// Найденное в сети и разобранные миниатюры к нему (индексы совпадают).
    находки: Vec<online::Находка>,
    сетевые_миниатюры: Vec<(u32, u32, Vec<u8>)>,
    /// Что ищем. Пусто — показываем то, что источник считает лучшим.
    запрос: String,
    /// Какая страница выдачи показана. Прокрутка до низа подгружает следующую.
    сетевая_страница: u32,
    /// Идёт запрос СПИСКА. Второй такой же не начинаем: сеть медленная, а
    /// щёлкать по вкладкам можно быстро.
    ///
    /// Скачивание самих обоев этим флагом больше НЕ управляется. Раньше
    /// управлялось, и получалось так: щёлкнул по вторым обоям, пока качаются
    /// первые, — второй щелчок молча проглатывался, а листать выдачу во время
    /// загрузки было нельзя вовсе. Теперь загрузки живут в `загрузки` и идут
    /// разом, каждая своим потоком.
    сетевая_работа: bool,
    /// Идущие загрузки обоев — по одной на щелчок.
    загрузки: Vec<Загрузка>,
    /// Карточка, чьи обои поставить, когда докачаются: последняя нажатая.
    поставить_карточку: Option<usize>,
    /// Готовые к укладке миниатюры — см. [`КэшКарточек`].
    кэш_карточек: КэшКарточек,
    /// Живая передняя карточка ленты (см. preview.rs): чья она и её поток.
    превью: Option<(КлючПревью, preview::Превью)>,
    /// Кандидат в живые и с какого мига лента стоит на нём (см.
    /// `preview::ЗАДЕРЖКА`).
    превью_ждёт: Option<(КлючПревью, std::time::Instant)>,
    /// Готовое «стекло» меню: фон, тень, кант и блик — всё, что не зависит ни
    /// от вкладки, ни от курсора, ни от кадра. Раньше эти четыре вызова
    /// (замер: 2.1 мс на кадр) повторялись шестьдесят раз в секунду, рисуя
    /// каждый раз ОДНО И ТО ЖЕ. Хранится вместе с размером, под который
    /// посчитано: сменился экран — пересчитаем.
    кэш_стекла: Option<(u32, u32, Vec<u8>)>,
    /// Буфер, в который рисуется меню. Живёт между кадрами — см. render_overlay.
    меню_пиксели: Vec<u8>,
    /// Последняя беда с сетью — рисуем полоской под вкладками. Текста в меню
    /// нет (шрифта у plx-wall тоже), поэтому объясняемся цветом.
    сетевая_ошибка: bool,
    /// Значок загрузки: какая точка кольца сейчас самая яркая и когда её
    /// последний раз двигали. Крутится, пока идёт хоть какая-то загрузка
    /// (см. идёт_загрузка).
    спиннер_фаза: u32,
    спиннер_тик: std::time::Instant,
    /// Нарисован ли значок в последнем отданном кадре. Нужен ровно затем,
    /// чтобы стереть его ОДИН раз, когда загрузка кончилась, а не гонять
    /// перерисовку меню вхолостую.
    спиннер_виден: bool,
    pending_online: Option<std::sync::mpsc::Receiver<ИзСети>>,
    /// Первый видимый ряд сетки обоев.
    scroll_row: u32,
    /// Накопитель колеса: одна «щёлка» приходит долями, шаг делаем по сумме.
    scroll_acc: f64,
    /// Пришёл ли первый configure для фоновой поверхности.
    ///
    /// wlr-layer-shell запрещает attach до ack первого configure — иначе
    /// композитор рвёт соединение с «must ack the initial configure before
    /// attaching buffer». Раньше рендер запускался прямо из wl_output.Mode,
    /// то есть ДО конфигурации, и plx-wall падал на старте.
    /// (У фоновых поверхностей этот флаг свой на каждую — см. `Фон::configured`.)
    ol_configured: bool,

    // ── Анимации меню ───────────────────────────────────────────────────────
    /// Насколько меню открыто: 0 — спрятано, 1 — на месте. Цель ставится по
    /// `overlay_visible` в главном цикле, поэтому все прежние места, где меню
    /// показывают и прячут, менять не пришлось — они как ставили флаг, так и
    /// ставят.
    открытие: ui::Плавно,
    /// Полоска под выбранной вкладкой: едет к новой, а не перескакивает.
    /// Хранится в пикселях по горизонтали.
    подчёркивание: ui::Плавно,
    /// Положение ленты в КАРТОЧКАХ, дробное. Цель — `scroll_row`, а это то,
    /// что нарисовано сейчас: лента доезжает до цели, а не прыгает.
    лента: ui::Плавно,
    /// Подсветки под курсором — по величине на элемент (см. [`ui::Наведения`]).
    подсветки: ui::Наведения,
    /// Когда последний раз двигали анимации. Шаг считается от настоящего
    /// времени: меню перерисовывается то по таймеру, то по движению мыши, и
    /// шаг «на кадр» шёл бы с разной скоростью.
    анимации_тик: std::time::Instant,
    /// Когда ушёл последний кадр МЕНЮ. По нему кадры ограничены сверху — см.
    /// [`период_меню`].
    кадр_меню_был: std::time::Instant,
}

/// Сколько времени обязано пройти между двумя кадрами меню.
///
/// **Зачем предел.** Меню рисуется процессором в общую память и отдаётся, как
/// только освободился слот. Композитор освобождает буфер сразу, как показал
/// кадр, — то есть просыпается plx-wall ровно столько раз, сколько кадров
/// показал композитор, а тот в свою очередь рисует потому, что plx-wall
/// прислал новый. Обратная связь: замер в харнессе показал **200 кадров меню в
/// секунду** (среднее 3.6 мс, худший 18 мс) — то есть 70% ядра на анимацию,
/// которой хватило бы шестидесяти кадров. На настольной машине это «просто
/// греется», на ноуте — те самые лаги: там кадр стоит втрое дороже, и цикл
/// съедает ядро целиком, а картинка всё равно не может обновиться чаще
/// монитора.
///
/// 16 мс — 60 кадров в секунду. Мельче монитора Ярика (он не медленнее 60 Гц),
/// а лента при 60 кадрах идёт ровно так же плавно.
///
/// **27.09.2026: предел — один кадр МОНИТОРА, а не жёсткие 16 мс.** Монитор
/// Ярика — 200 Гц, и лента в 60 кадров на нём шла заметно рывками рядом со
/// всем остальным рабочим столом («меню сильно лагает»). Те самые «200 кадров
/// в секунду» из замера выше и были частотой монитора. Теперь предел берётся
/// из `wl_output.mode` (самый быстрый выход), а кадр подешевел настолько, что
/// столько кадров помещается: карточки считаются в несколько потоков (см.
/// `ui::Холст::картинка_готовая_масштаб`). Потолок 4 мс — выше 250 Гц мониторы
/// нам не встречались, а цикл без предела снова стал бы «ядро на анимацию».
fn период_меню() -> std::time::Duration {
    std::time::Duration::from_micros(ПЕРИОД_МЕНЮ_МКС.load(ПорядокАтомика::Relaxed) as u64)
}

/// Период кадра меню в микросекундах; пишет его `wl_output.mode`.
static ПЕРИОД_МЕНЮ_МКС: AtomicU32 = AtomicU32::new(16_667);

// ── Главная функция ─────────────────────────────────────────────────────────

fn main() {
    // Служебный режим: пересчитать палитру по обоям и разойтись. Композитор
    // для этого не нужен, поэтому проверяется он отдельно от всего остального.
    if std::env::args().nth(1).as_deref() == Some("--palette") {
        std::process::exit(palette::режим_палитры(std::env::args().nth(2)));
    }

    // Служебный режим: проверить аппаратное декодирование на конкретном ролике
    // и показать, что именно отдаёт видеокарта. Композитор не нужен —
    // проверяется ровно связка libavcodec+VAAPI+dmabuf.
    if std::env::args().nth(1).as_deref() == Some("--hwtest") {
        std::process::exit(hwvideo::режим_проверки(std::env::args().nth(2)));
    }

    // Служебный режим: спросить обои у источника и показать, что нашлось.
    // Композитор не нужен — сеть проверяется отдельно от всего остального.
    if std::env::args().nth(1).as_deref() == Some("--online") {
        std::process::exit(режим_сети(
            std::env::args().nth(2),
            std::env::args().nth(3),
            std::env::args().skip(4).collect(),
        ));
    }

    let conn = Connection::connect_to_env().unwrap();
    let mut event_queue = conn.new_event_queue();
    let qh = event_queue.handle();
    let display = conn.display();
    let _registry = display.get_registry(&qh, ());

    // Блокируем сигналы и создаём signalfd
    let sfd = setup_signalfd();

    let mut config = Config {
        outputs: Vec::new(),
        фоны: Vec::new(),
        ol_surface: None,
        ol_layer: None,
        compositor: None,
        shm: None,
        layer_shell: None,
        pointer: None,
        touch: None,
        касание: None,
        qh: Some(qh.clone()),
        signalfd: Some(sfd),
        wallpapers: Vec::new(),
        current: 0,
        img: None,
        thumbnails: Vec::new(),
        миниатюра_готова: Vec::new(),
        thumbs_for: Vec::new(),
        pending_img: None,
        pending_thumbs: None,
        anim: None,
        видно: true,
        кадр_слота: None,
        слоты_у_декодера: Vec::new(),
        кадр_заказан: None,
        callback_был: false,
        img_bgra: false,
        bg_slots: Vec::new(),
        bg_slot: 0,
        bg_dims: (0, 0),
        ol_slots: Vec::new(),
        ol_slot: 0,
        bg_pending: false,
        viewporter: None,
        hw: None,
        hw_буферы: std::collections::HashMap::new(),
        hw_порядок: std::collections::VecDeque::new(),
        hw_мусор: Vec::new(),
        hw_на_экране: Vec::new(),
        hw_срок: std::time::Instant::now(),
        живые_путь: None,
        живые_рестарт: None,
        dmabuf: None,
        dmabuf_форматы: std::collections::HashSet::new(),
        запросить_поиск: false,
        запросить_фильтр: false,
        запросить_файл: false,
        выбор_меню: None,
        фильтры: online::Фильтры::default(),
        цикл: load_cycle(),
        разделы_живых: Vec::new(),
        hover: None,
        стартовые: None,
        overlay_visible: false,
        ol_клавиатура: false,
        cursor_x: -1.0,
        cursor_y: -1.0,
        hit_rects: Vec::new(),
        dirty: false,
        fade: None,
        scaled: None,
        вкладка: Вкладка::Мои,
        находки: Vec::new(),
        сетевые_миниатюры: Vec::new(),
        запрос: String::new(),
        сетевая_страница: 1,
        сетевая_работа: false,
        загрузки: Vec::new(),
        поставить_карточку: None,
        кэш_карточек: КэшКарточек::default(),
        превью: None,
        превью_ждёт: None,
        кэш_стекла: None,
        меню_пиксели: Vec::new(),
        сетевая_ошибка: false,
        спиннер_фаза: 0,
        спиннер_тик: std::time::Instant::now(),
        спиннер_виден: false,
        pending_online: None,
        scroll_row: 0,
        scroll_acc: 0.0,
        ol_configured: false,
        // 0.13 с — меню успевает «приехать», но не заставляет себя ждать.
        открытие: ui::Плавно::новое(0.0, 0.13),
        подчёркивание: ui::Плавно::новое(0.0, 0.10),
        // Лента едет чуть быстрее прочего: она крупная, и медленный проезд
        // на пол-экрана читается как задержка ответа, а не как плавность.
        лента: ui::Плавно::новое(0.0, 0.085),
        подсветки: ui::Наведения::default(),
        анимации_тик: std::time::Instant::now(),
        кадр_меню_был: std::time::Instant::now() - период_меню(),
    };

    load_config(&mut config);

    if let Some(path) = std::env::args().nth(1) {
        if !config.wallpapers.contains(&path) {
            config.wallpapers.push(path.clone());
            save_config(&config.wallpapers);
        }
        config.current = config.wallpapers.iter().position(|p| p == &path).unwrap_or(0);
        // Через ту же дверь, что и выбор в меню: иначе `plx-wall видео.mp4`
        // показывал бы один кадр вместо живых обоев.
        config.стартовые = Some(config.wallpapers[config.current].clone());
    } else if let Some(запомненные) = load_current()
        .filter(|p| config.wallpapers.contains(p))
    {
        // Восстанавливаем последние показанные обои: без этого при каждом
        // перезаходе сессия начиналась с первой строки списка.
        config.current = config.wallpapers.iter().position(|p| p == &запомненные).unwrap_or(0);
        config.стартовые = Some(запомненные);
    } else if let Some(first) = config.wallpapers.first() {
        config.стартовые = Some(first.clone());
    }

    // Первый раундтрип — получаем все глобалы
    event_queue.roundtrip(&mut config).unwrap();

    // Главный poll-цикл
    loop {
        // Сначала флашим и диспатчим то что есть.
        //
        // Ошибку dispatch_pending раньше глушили через `let _`, и это стоило
        // дорого: если очередь не разбирается (протокольная ошибка, мёртвое
        // соединение), она остаётся непустой, prepare_read НАВСЕГДА возвращает
        // None, цикл перестаёт спать на poll и крутится на 100% CPU. Хуже
        // того, signalfd читается только в ветке с poll — то есть USR1/USR2
        // в таком состоянии не доходят вообще: обои и меню «залипали» после
        // первого же открытия. Теперь выходим: обои перезапустит сторож
        // в launch_native.sh.
        // Ошибку flush тоже нельзя глушить: после смерти композитора запись в
        // сокет даёт EPIPE, и без выхода мы просто крутились бы дальше.
        if let Err(e) = event_queue.flush() {
            if !временная_ошибка(&e) {
                eprintln!("plx-wall: соединение с композитором оборвалось ({e}) — выходим");
                return;
            }
        }
        if let Err(e) = event_queue.dispatch_pending(&mut config) {
            eprintln!("plx-wall: очередь событий сломалась ({e}) — выходим");
            return;
        }

        // Пробуем приготовиться к чтению wayland
        match event_queue.prepare_read() {
            Some(guard) => {
                let wl_fd = event_queue.as_fd().as_raw_fd();
                let mut fds = [
                    libc::pollfd { fd: wl_fd, events: libc::POLLIN, revents: 0 },
                    libc::pollfd { fd: sfd, events: libc::POLLIN, revents: 0 },
                ];

                // Ждём события на любом из FD. Таймаут (а не -1) — страховка:
                // даже если мы прозевали пробуждение, цикл раз в секунду
                // очнётся сам и перечитает сигналы.
                // Пока обои декодируются в фоне, опрашиваем чаще, чтобы
                // применить их сразу по готовности, а не через секунду.
                let идёт_переход = config.fade.as_ref().map(|f| !f.ждём).unwrap_or(false);
                // Живые обои: спим ровно до срока СЛЕДУЮЩЕГО кадра. Раньше
                // здесь стояли фиксированные 15 мс — потолок в 66 к/с, которого
                // хватало ровно потому, что кадров и так было 15 в секунду.
                // Ролику на 60 к/с этого мало: кадр то успевал к сроку, то
                // опаздывал на целый период, и картинка дёргалась.
                //
                // Пол в 2 мс — на случай, когда срок уже прошёл, а кадра ещё
                // нет (декодер не успевает): канал не файловый дескриптор, о
                // готовности кадра poll не узнает, и остаётся опрашивать.
                // Спящим обоям частый опрос не нужен вовсе: ждём кадрового
                // callback'а из сокета, а он придёт по POLLIN.
                //
                // Срок берём у ТОГО пути, который сейчас работает: у обоев
                // через ffmpeg он свой (Anim::next_at), у аппаратных — свой
                // (hw_срок). Забыть про второй значит вернуть ровно ту дёрганую
                // картинку, о которой сказано выше: цикл засыпал на секунду и
                // просыпался только на кадровый callback, поэтому кадр то
                // успевал к сроку, то опаздывал на целый период.
                let срок_кадра = match (config.anim.as_ref(), config.hw.as_ref()) {
                    (Some(a), _) => Some(a.next_at),
                    // Пока играет переход, аппаратные кадры не забираются
                    // (см. показать_hw_кадр) — и будить цикл под них незачем.
                    (None, Some(_)) if config.fade.is_none() => Some(config.hw_срок),
                    _ => None,
                };
                let до_кадра = срок_кадра.filter(|_| config.видно).map(|срок| {
                    let ост = срок.saturating_duration_since(std::time::Instant::now());
                    (ост.as_micros().div_ceil(1000) as i32).clamp(2, 1000)
                });
                // bg_pending и переход — это не украшение: флаг значит, что
                // кадр обоев НЕ нарисован — оба буфера были у композитора (см.
                // render_wallpaper). Повторную попытку делает главный цикл, но
                // без частого опроса он засыпал на секунду, и смена обоев
                // «иногда» (когда именно в этот момент буфер был занят)
                // показывалась с задержкой до 1000 мс.
                let частые = [
                    до_кадра,
                    (идёт_переход || config.bg_pending).then_some(15),
                    // Значок загрузки крутится, пока идёт загрузка (см.
                    // ШАГ_СПИННЕРА).
                    идёт_загрузка(&config).then(|| ШАГ_СПИННЕРА.as_millis() as i32),
                    (config.pending_img.is_some() || config.pending_thumbs.is_some())
                        .then_some(30),
                    // Карточки в фоне: проснуться, как только какая-то готова.
                    (!config.кэш_карточек.в_работе.is_empty()).then_some(8),
                    // Ждём ответа rofi из его потока.
                    config.выбор_меню.is_some().then_some(30),
                    // Ждём срока, чтобы поднять умерший декодер: без этого
                    // спящие обои (видно = false, таймаут 1000 мс) узнавали бы
                    // о сроке с опозданием до секунды.
                    config.живые_рестарт.map(|(срок, _)| {
                        let ост = срок.saturating_duration_since(std::time::Instant::now());
                        (ост.as_micros().div_ceil(1000) as i32).clamp(2, 1000)
                    }),
                    // Анимации меню. Без своего срока плавность держалась бы
                    // только на движениях мыши: отпустил мышь — и выезд меню
                    // замирал на середине до следующего события.
                    идёт_анимация(&config)
                        .then(|| (период_меню().as_micros().div_ceil(1000) as i32).clamp(1, 16)),
                    // Живая карточка: проснуться к её следующему кадру, а пока
                    // она только ждёт своей очереди — к концу задержки.
                    config.превью.as_ref().map(|(_, п)| п.до_кадра_мс()),
                    config.превью_ждёт.as_ref().map(|(_, с)| {
                        let ост = preview::ЗАДЕРЖКА.saturating_sub(с.elapsed());
                        (ост.as_micros().div_ceil(1000) as i32).clamp(2, 1000)
                    }),
                    // Кадр меню отложен пределом (см. период_меню) — проснуться
                    // обязаны ровно к тому мигу, когда рисовать снова можно.
                    // Иначе кадр, отложенный без анимации (наведение мыши,
                    // пришедшая миниатюра), ждал бы до секунды.
                    config.dirty.then(|| {
                        let прошло = config.кадр_меню_был.elapsed();
                        (период_меню().saturating_sub(прошло).as_micros().div_ceil(1000) as i32)
                            .clamp(1, 16)
                    }),
                ];
                let таймаут = частые.into_iter().flatten().min().unwrap_or(1000);
                unsafe { libc::poll(fds.as_mut_ptr(), 2, таймаут); }

                // Wayland
                //
                // Обрыв соединения обязан УБИВАТЬ plx-wall, а не игнорироваться.
                // Раньше здесь стояло `guard.read().unwrap_or(0)`: когда
                // композитор закрывал соединение (например упёршись в лимит
                // дескрипторов), ошибка молча проглатывалась, мёртвый сокет
                // навсегда оставался в POLLHUP, poll возвращался мгновенно —
                // и plx-wall крутился на 100% ядра, живой, но без обоев и без
                // меню. Сторож в launch_native.sh перезапускает только
                // ЗАВЕРШИВШИЙСЯ процесс, поэтому обои не возвращались до конца
                // сессии. Замер 04.08.2026: 94% CPU, «Connection reset by peer»
                // в stderr, экран пустой.
                if fds[0].revents & (libc::POLLHUP | libc::POLLERR) != 0 {
                    eprintln!("plx-wall: композитор закрыл соединение — выходим");
                    return;
                }
                if fds[0].revents & libc::POLLIN != 0 {
                    if let Err(e) = guard.read() {
                        if !временная_ошибка(&e) {
                            eprintln!("plx-wall: чтение из сокета не удалось ({e}) — выходим");
                            return;
                        }
                    }
                    if let Err(e) = event_queue.dispatch_pending(&mut config) {
                        eprintln!("plx-wall: очередь событий сломалась ({e}) — выходим");
                        return;
                    }
                }

                // Сигналы
                if fds[1].revents & libc::POLLIN != 0 {
                    process_signalfd(&mut config);
                }
            }
            None => {
                // Есть неразобранные события — их разберёт dispatch_pending в
                // начале следующего прохода. Сигналы читаем и здесь: иначе в
                // этой ветке signalfd не опрашивается никем, и нажатия Win+W
                // теряются ровно до тех пор, пока не придёт событие Wayland.
                process_signalfd(&mut config);
            }
        }

        // Пост-обработка сигналов и dirty-флагов
        if SIG1.swap(false, Ordering::SeqCst) && !config.wallpapers.is_empty() {
            config.current = (config.current + 1) % config.wallpapers.len();
            let путь = config.wallpapers[config.current].clone();
            start_load_wallpaper(&mut config, путь);
        }
        if SIG2.swap(false, Ordering::SeqCst) {
            config.overlay_visible = !config.overlay_visible;
            if config.overlay_visible {
                load_thumbnails(&mut config);
                build_ui_layout(&mut config);
            }
            config.dirty = true;
        }
        // Меню подгоняем под экран, как только он стал известен (и на каждой
        // смене режима). Буферы при этом обязаны пересоздаться: они размером с
        // меню, а старые остались с прежним — на новый кадр их бы не хватило,
        // и меню нарисовалось бы обрезанным или не нарисовалось вовсе.
        let экран = config.outputs.first().map(|(_, w, h)| (*w, *h));
        if let Some((w, h)) = экран {
            if w > 0 && h > 0 && установить_размер_меню(w, h) {
                config.ol_slots.clear();
                config.ol_slot = 0;
                if let Some(l) = config.ol_layer.as_ref() {
                    l.set_size(ui_w(), ui_h());
                }
                if let Some(sf) = config.ol_surface.as_ref() {
                    sf.commit();
                }
                // Раскладка сетки считается от числа колонок, а оно только что
                // изменилось — пересобрать обязательно.
                build_ui_layout(&mut config);
                config.dirty = true;
            }
        }

        // Стартовые обои запускаем, как только стал известен размер экрана.
        if config.стартовые.is_some()
            && config.outputs.first().map(|(_, w, h)| *w > 0 && *h > 0).unwrap_or(false)
        {
            if let Some(путь) = config.стартовые.take() {
                start_load_wallpaper(&mut config, путь);
            }
        }

        // Видно ли обои. Композитор молчит на кадровый запрос дольше срока —
        // значит их целиком закрыли (полноэкранная игра, окна во весь экран), и
        // считать кадры незачем.
        if !config.callback_был {
            // Ни одного ответа за всю жизнь — этот композитор кадровых
            // callback'ов слоям не шлёт. Работаем по таймеру, как раньше.
        } else if let Some(заказан) = config.кадр_заказан {
            // Пока идёт смена обоев (ждём первый кадр или играет шторка), не
            // засыпаем: она короткая, а уснувшая посередине застревала бы
            // полуоткрытой до следующего ответа композитора.
            if config.видно && config.fade.is_none() && заказан.elapsed() >= ОЖИДАНИЕ_КАДРА {
                config.видно = false;
                // Кадры больше не забираем: очередь декодера ёмкостью 1
                // переполнится, ffmpeg упрётся в трубу и встанет сам.
                eprintln!("plx-wall: обои закрыты — засыпаем");
            }
        }

        // Умерший декодер поднимаем заново, когда подошёл срок (см. декодер_умер).
        // Проверка стоит ДО забора кадров: поднявшийся декодер должен успеть
        // отдать кадр этим же проходом цикла, а не следующим.
        if config.живые_рестарт.is_some_and(|(срок, _)| std::time::Instant::now() >= срок) {
            перезапустить_живые(&mut config);
        }

        // Живые обои: сначала отдаём декодеру всё, во что он может писать.
        одолжить_слоты(&mut config);

        // Живые обои: забираем очередной кадр, когда подошёл его срок.
        let видно = config.видно;
        if let Some(anim) = config.anim.as_mut().filter(|_| видно) {
            let сейчас = std::time::Instant::now();
            if сейчас >= anim.next_at {
                match anim.rx.try_recv() {
                    Ok(кадр) => {
                        let шаг = match &кадр {
                            Кадр::ВСлоте { шаг, .. } => *шаг,
                            Кадр::Буфером { шаг, .. } => *шаг,
                        };
                        // Срок следующего кадра отсчитываем от СРОКА текущего, а
                        // не от «сейчас»: иначе к каждому кадру прибавлялось бы
                        // опоздание главного цикла, и ролик на 60 к/с полз бы
                        // медленнее реального времени. Если отстали больше чем
                        // на кадр (тяжёлая перерисовка, машина занята) —
                        // догонять нечем, начинаем отсчёт заново.
                        anim.next_at = if сейчас.duration_since(anim.next_at) > шаг {
                            сейчас + шаг
                        } else {
                            anim.next_at + шаг
                        };
                        // Кадр приехал — декодер жив (см. декодер_умер).
                        config.живые_рестарт = None;
                        config.img_bgra = true; // и видео, и gif отдают BGRA
                        match кадр {
                            // Кадр уже в общей памяти — заполнять нечего,
                            // остаётся показать (см. render_wallpaper).
                            Кадр::ВСлоте { слот, .. } => {
                                let (dw, dh) = config.anim.as_ref().map(|a| a.dims).unwrap_or((0, 0));
                                if let Some(занят) = config.слоты_у_декодера.get_mut(слот) {
                                    *занят = false;
                                }
                                config.кадр_слота = Some((слот, dw, dh));
                            }
                            Кадр::Буфером { w, h, px, .. } => {
                                config.кадр_слота = None;
                                config.img = Some((w, h, px));
                            }
                        }
                        // Первый кадр новых живых обоев — с него и начинается
                        // переход.
                        if let Some(f) = config.fade.as_mut() { f.ждём = false; }
                        config.scaled = None;
                        render_wallpaper(&mut config);
                    }
                    // Декодер умер (ffmpeg не смог, файл битый) — поднимаем заново.
                    Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                        декодер_умер(&mut config, "ffmpeg")
                    }
                    Err(std::sync::mpsc::TryRecvError::Empty) => {}
                }
            }
        }

        // Живые обои на видеокарте: кадр уже лежит в видеопамяти готовым, и
        // весь показ — это прицепить wl_buffer.
        //
        // Пока играет плавный переход, кадры отсюда НЕ забираем: смешивать
        // dmabuf нечем, и на экране в это время неподвижный первый кадр ролика
        // обычным путём через общую память (см. установить_обои). Декодер всё
        // это время стоит на `send` и не тратит ничего.
        if config.видно && config.fade.is_none() && config.hw.is_some() {
            показать_hw_кадр(&mut config);
        }

        // Значок загрузки. Крутим его, пока идёт фоновая работа, и один раз
        // стираем, когда она кончилась; сама перерисовка — общая, через dirty
        // (меню открыто — рисуется в его ряду кнопок, закрыто — плашкой в
        // углу, см. hide_overlay).
        {
            let грузим = идёт_загрузка(&config);
            if грузим {
                if config.спиннер_тик.elapsed() >= ШАГ_СПИННЕРА {
                    config.спиннер_фаза = config.спиннер_фаза.wrapping_add(1);
                    config.спиннер_тик = std::time::Instant::now();
                    config.спиннер_виден = true;
                    config.dirty = true;
                }
            } else if config.спиннер_виден {
                config.спиннер_виден = false;
                config.dirty = true;
            }
        }

        // Переход между статичными обоями: кадры гоним сами. У живых обоев
        // этим занимается ветка выше — там кадр и так приходит десятки раз в
        // секунду, и смешивание делается заодно с ним.
        if config.anim.is_none() && config.fade.as_ref().map(|f| !f.ждём).unwrap_or(false) {
            render_wallpaper(&mut config);
        }

        // Ответ из сети: пришёл ли список.
        if let Some(rx) = config.pending_online.as_ref() {
            match rx.try_recv() {
                Ok(ответ) => {
                    config.pending_online = None;
                    config.сетевая_работа = false;
                    принять_из_сети(&mut config, ответ, None);
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    config.pending_online = None;
                    config.сетевая_работа = false;
                    config.сетевая_ошибка = true;
                    config.dirty = true;
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
            }
        }

        // …и докачался ли кто-нибудь из загрузок. Идут они разом, поэтому
        // забираем ВСЕ готовые за проход, а не первую попавшуюся.
        {
            let mut готовые = Vec::new();
            config.загрузки.retain(|з| match з.rx.try_recv() {
                Ok(ответ) => {
                    готовые.push((з.карточка, ответ));
                    false
                }
                // Поток кончился, не ответив, — считаем бедой и убираем.
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    готовые.push((з.карточка, ИзСети::Ошибка("загрузка оборвалась".into())));
                    false
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => true,
            });
            for (карточка, ответ) in готовые {
                принять_из_сети(&mut config, ответ, Some(карточка));
            }
        }

        // Живая передняя карточка: завести, сменить или забрать кадр.
        вести_превью(&mut config);

        // Готовы ли миниатюры? Приходят ПО ОДНОЙ, поэтому забираем всё, что
        // накопилось, — иначе на кадр вставала бы ровно одна карточка.
        if let Some(rx) = config.pending_thumbs.as_ref() {
            let mut пришло = false;
            let mut кончились = false;
            loop {
                match rx.try_recv() {
                    Ok((i, мини)) => {
                        if let Some(место) = config.thumbnails.get_mut(i) {
                            *место = мини;
                            if let Some(г) = config.миниатюра_готова.get_mut(i) {
                                *г = true;
                            }
                            config.кэш_карточек.забыть(false, i);
                            пришло = true;
                        }
                    }
                    Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                        кончились = true;
                        break;
                    }
                    Err(std::sync::mpsc::TryRecvError::Empty) => break,
                }
            }
            if кончились {
                config.pending_thumbs = None;
            }
            // Кэш забывает только пришедшие карточки (см. КэшКарточек::забыть):
            // общий сброс на каждую миниатюру пересчитывал видимые заново.
            if пришло {
                if config.overlay_visible {
                    config.dirty = true;
                }
            }
        }

        // Карточки, досчитанные фоном. Без своего приёма здесь они ждали бы
        // следующего кадра меню, а его без движения мыши может и не быть.
        if принять_карточки(&mut config) && config.overlay_visible {
            config.dirty = true;
        }

        // Готовы ли обои из фонового потока?
        if let Some(rx) = config.pending_img.as_ref() {
            match rx.try_recv() {
                Ok(img) => {
                    config.pending_img = None;
                    config.img_bgra = false; // из load_image приходит RGBA
                    config.img = img;
                    // Картинка сменилась — старый растянутый кадр недействителен,
                    // и с этого момента идут часы перехода.
                    config.scaled = None;
                    if let Some(f) = config.fade.as_mut() { f.ждём = false; }
                    render_wallpaper(&mut config);
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => config.pending_img = None,
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
            }
        }

        // Поверхности могли не создаться на первом wl_output::Mode: plx-wall
        // стартует из launch_native.sh сразу, как появился сокет, то есть
        // ПОСРЕДИ инициализации композитора, и Mode приходит раньше глобала
        // zwlr_layer_shell_v1. setup_layers тогда молча выходит, а второго
        // Mode уже не будет — обои и меню не появлялись до конца сессии.
        // Пробуем каждый проход: функция идемпотентна (заводит фон только тому
        // выходу, у которого его ещё нет) и сама выходит, пока чего-то нет.
        // Она же подхватывает монитор, включённый посреди сеанса.
        if config.фоны.len() < config.outputs.len() {
            setup_layers(&mut config);
        }
        // Кадр обоев, который не влез (оба буфера были заняты композитором).
        if config.bg_pending {
            render_wallpaper(&mut config);
        }
        // ── Анимации меню ────────────────────────────────────────────────────
        // Цель открытия ставится ЗДЕСЬ, по флагу, а не в десятке мест, где
        // меню показывают и прячут: тех мест восемь, и забыть одно из них
        // значило бы получить меню, застрявшее наполовину.
        {
            let dt = config.анимации_тик.elapsed().as_secs_f32().min(0.1);
            config.анимации_тик = std::time::Instant::now();
            config.открытие.к(if config.overlay_visible { 1.0 } else { 0.0 });
            // Клавиатура ходит за меню: открыли — просим Exclusive (Esc,
            // стрелки и поиск должны доходить целиком), закрыли — отдаём
            // обратно композитору. Просим только на ПЕРЕХОДЕ: set_* каждый
            // кадр анимации — это лишний трафик протокола на ровном месте.
            if config.ol_клавиатура != config.overlay_visible {
                if let Some(l) = config.ol_layer.as_ref() {
                    l.set_keyboard_interactivity(if config.overlay_visible {
                        zwlr_layer_surface_v1::KeyboardInteractivity::Exclusive
                    } else {
                        zwlr_layer_surface_v1::KeyboardInteractivity::None
                    });
                    if let Some(sf) = config.ol_surface.as_ref() { sf.commit(); }
                    config.ol_клавиатура = config.overlay_visible;
                }
            }
            config.лента.к(config.scroll_row as f32);
            let ехала_лента = config.лента.идёт();
            let двигалось = config.открытие.шаг(dt)
                | config.подчёркивание.шаг(dt)
                | config.лента.шаг(dt)
                | config.подсветки.шаг(dt);
            if двигалось {
                config.dirty = true;
            }
            // Карточки уехали — вместе с ними обязаны уехать и области
            // нажатия, иначе клик посреди листания попадал бы по карточке,
            // которой на этом месте уже нет.
            if ехала_лента {
                build_ui_layout(&mut config);
            }
        }

        // Кадр меню — не чаще, чем раз в период_меню(). Метку `dirty` при этом
        // НЕ снимаем: цикл проснётся по таймауту (он тоже 16 мс) и нарисует.
        if config.dirty && config.кадр_меню_был.elapsed() >= период_меню() {
            config.кадр_меню_был = std::time::Instant::now();
            // Пометку снимаем только если кадр действительно ушёл: иначе
            // (оба буфера ещё у композитора) меню осталось бы со старой
            // картинкой до следующего события.
            //
            // Рисуем и пока меню ЗАКРЫВАЕТСЯ: флаг уже снят, а картинка ещё
            // уезжает. Без этого закрытие было бы мгновенным — анимации,
            // которую видно, не осталось бы вовсе.
            let начало = замер::пора();
            let ушло = if config.overlay_visible || config.открытие.значение() > 0.002 {
                render_overlay(&mut config)
            } else {
                hide_overlay(&mut config)
            };
            замер::кадр_меню(начало);
            config.dirty = !ушло;
        }
        замер::отчёт();

        // ── Строка поиска, меню фильтров, выбор файла (rofi) ───────────────
        // Запускаем ТОЛЬКО когда меню целиком убрано: кадр со скрытым меню ушёл
        // (dirty снят) И анимация закрытия доиграла. Меню лежит на слое
        // Overlay, rofi тоже (свой слой у rofi всегда overlay), но поверх оказывается тот,
        // кто нарисовался позже, — а раньше проверялся только `dirty`, и он
        // снимается после КАЖДОГО кадра закрытия. rofi открывался под
        // полузакрытым меню, а главный цикл тут же вставал ждать его ответа —
        // меню так и висело поверх строки ввода: «менюшки появляются за
        // plx-wall».
        //
        // Сам rofi ждём в СВОЁМ потоке: пока человек набирает запрос, живые
        // обои должны идти, а события композитора — разбираться.
        let меню_убрано = !config.dirty && config.открытие.значение() <= 0.002;
        if меню_убрано && config.выбор_меню.is_none() {
            if config.запросить_поиск {
                config.запросить_поиск = false;
                let текущий = config.запрос.clone();
                config.выбор_меню = Some(в_потоке(move || ОтветВыбора::Поиск(спросить_запрос(&текущий))));
            } else if config.запросить_фильтр {
                config.запросить_фильтр = false;
                match config.вкладка.источник() {
                    Some(источник) => {
                        let фильтры = config.фильтры.clone();
                        let mut разделы = config.разделы_живых.clone();
                        let есть_запрос = !config.запрос.is_empty();
                        config.выбор_меню = Some(в_потоке(move || {
                            // Разделы moewalls спрашиваем один раз за сеанс и
                            // только здесь: до открытия меню они не нужны. Это
                            // сеть — тоже не в главном цикле.
                            if источник == online::Источник::Живые && разделы.is_empty() {
                                разделы = online::разделы_живых();
                            }
                            let пункты = online::меню_фильтров(источник, &фильтры, &разделы, есть_запрос);
                            let подписи: Vec<String> = пункты.iter().map(|(п, _)| п.clone()).collect();
                            let выбор = спросить_из_списка("Фильтр: ", &подписи);
                            ОтветВыбора::Фильтр { выбор, пункты, разделы }
                        }));
                    }
                    None => {
                        config.overlay_visible = true;
                        config.dirty = true;
                    }
                }
            } else if config.запросить_файл {
                config.запросить_файл = false;
                config.выбор_меню = Some(в_потоке(|| ОтветВыбора::Файл(pick_wallpaper_file())));
            }
        }

        let ответ = match config.выбор_меню.as_ref().map(|rx| rx.try_recv()) {
            Some(Ok(ответ)) => Some(ответ),
            // Поток умер, не ответив, — считаем, что передумали.
            Some(Err(std::sync::mpsc::TryRecvError::Disconnected)) => Some(ОтветВыбора::Поиск(None)),
            _ => None,
        };
        if let Some(ответ) = ответ {
            config.выбор_меню = None;
            // Меню возвращаем в любом случае — и когда выбрали, и когда
            // закрыли по Esc.
            config.overlay_visible = true;
            match ответ {
                ОтветВыбора::Поиск(Some(новый)) => {
                    config.запрос = новый;
                    // Искать по своим обоям нечего — они все на виду. Поэтому
                    // поиск всегда уводит в сеть: с «моих» переходим на картинки.
                    if config.вкладка == Вкладка::Мои {
                        config.вкладка = Вкладка::Картинки;
                    }
                    config.находки.clear();
                    config.сетевые_миниатюры.clear();
                    config.кэш_карточек.сбросить();
                    config.scroll_row = 0;
                    загрузить_страницу(&mut config, 1, false);
                }
                ОтветВыбора::Поиск(None) => {}
                ОтветВыбора::Фильтр { выбор, пункты, разделы } => {
                    config.разделы_живых = разделы;
                    if let Some((_, новые)) = выбор.and_then(|i| пункты.get(i)) {
                        // Выбрали уже действующее — сеть не перезапрашиваем.
                        if *новые != config.фильтры {
                            config.фильтры = новые.clone();
                            config.scroll_row = 0;
                            загрузить_страницу(&mut config, 1, false);
                        }
                    }
                }
                ОтветВыбора::Файл(выбран) => {
                    // Проверяем, что выбрали именно картинку: иначе в списке
                    // заводились серые плитки-пустышки (диалог позволяет выбрать
                    // что угодно, а декодер потом просто не справляется).
                    let выбран = выбран.filter(|p| is_image(std::path::Path::new(p)));
                    if let Some(path) = выбран {
                        if !config.wallpapers.contains(&path) {
                            config.wallpapers.push(path.clone());
                            save_config(&config.wallpapers);
                            config.current = config.wallpapers.len() - 1;
                            start_load_wallpaper(&mut config, path);
                            load_thumbnails(&mut config);
                        }
                    }
                }
            }
            build_ui_layout(&mut config);
            config.dirty = true;
        }
    }
}

/// Что вернул rofi (или графический диалог), ждавший в своём потоке.
enum ОтветВыбора {
    Поиск(Option<String>),
    Фильтр {
        выбор: Option<usize>,
        пункты: Vec<(String, online::Фильтры)>,
        /// Разделы moewalls — если поток их спрашивал, запоминаем на сеанс.
        разделы: Vec<(String, String)>,
    },
    Файл(Option<String>),
}

fn в_потоке(f: impl FnOnce() -> ОтветВыбора + Send + 'static) -> std::sync::mpsc::Receiver<ОтветВыбора> {
    let (tx, rx) = std::sync::mpsc::channel();
    std::thread::spawn(move || {
        let _ = tx.send(f());
    });
    rx
}

/// `plx-wall --online картинки|живые [запрос] [скачать] [фильтр=значение…]` —
/// проверить источник.
///
/// Без композитора: показывает, что нашлось на первой странице, а со словом
/// «скачать» ещё и тянет первую находку. Нужен для проверки — сеть отказывает
/// иначе, чем графика, и мешать эти два вида отказов в одном месте не стоит.
///
/// Фильтры задаются теми же словами, что стоят в меню:
/// `размер=любые`, `ориентация=любая`, `род=рисунки`, `раздел=аниме`,
/// `порядок=совпадение`. Иначе проверить их можно было бы только руками через
/// меню, то есть только в живом сеансе.
fn режим_сети(какие: Option<String>, запрос: Option<String>, хвост: Vec<String>) -> i32 {
    let источник = match какие.as_deref() {
        Some("картинки") | Some("images") => online::Источник::Картинки,
        Some("живые") | Some("live") => online::Источник::Живые,
        _ => {
            eprintln!("plx-wall --online картинки|живые [запрос] [скачать] [фильтр=значение…]");
            return 2;
        }
    };

    let запрос = запрос.unwrap_or_default();
    let действие = хвост.iter().find(|a| a.as_str() == "скачать").cloned();
    let mut фильтры = online::Фильтры::default();
    for правка in хвост
        .iter()
        .filter(|a| a.contains('=') && !a.starts_with("страница="))
    {
        let (ключ, значение) = правка.split_once('=').unwrap_or((правка, ""));
        let понято = match (ключ, значение) {
            ("размер", "крупные") => { фильтры.размер = online::Размер::Крупные; true }
            ("размер", "средние") => { фильтры.размер = online::Размер::Средние; true }
            ("размер", "любые") => { фильтры.размер = online::Размер::Любые; true }
            ("ориентация", "широкие") => { фильтры.ориентация = online::Ориентация::Широкие; true }
            ("ориентация", "любая") => { фильтры.ориентация = online::Ориентация::Любая; true }
            ("род", "любой") => { фильтры.род = online::Род::Любой; true }
            ("род", "рисунки") => { фильтры.род = online::Род::Рисунки; true }
            ("род", "фотографии") => { фильтры.род = online::Род::Фотографии; true }
            ("порядок", "свежие") => { фильтры.порядок = online::Порядок::Свежие; true }
            ("порядок", "совпадение") => { фильтры.порядок = online::Порядок::Совпадение; true }
            ("цвет", "любой") => { фильтры.цвет = None; true }
            ("цвет", имя) => match palette::Цвет::из_имени(имя) {
                Some(ц) => { фильтры.цвет = Some(ц); true }
                None => false,
            },
            // Источник картинок: без него новые провайдеры (в том числе
            // бесконечные — NASA и artic) проверялись бы только руками через
            // меню, то есть только в живом сеансе.
            ("провайдер", имя) => {
                match ИСТОЧНИКИ_КАРТИНОК
                    .iter()
                    .find(|(_, п)| п.eq_ignore_ascii_case(имя))
                {
                    Some((п, _)) => { фильтры.провайдер = *п; true }
                    None => false,
                }
            }
            // Источник живых обоев — тем же способом, что и прочие фильтры:
            // иначе новый сайт проверялся бы только вручную через меню, то
            // есть только в живом сеансе.
            ("живой", "авто") => { фильтры.живой = online::ЖивойИсточник::Авто; true }
            ("живой", "motionbgs") => { фильтры.живой = online::ЖивойИсточник::Motionbgs; true }
            ("живой", "lw4free") => {
                фильтры.живой = online::ЖивойИсточник::LiveWallpapers4Free;
                true
            }
            ("раздел", "все") => { фильтры.раздел = None; true }
            ("раздел", имя) => {
                // Номер раздела знает только сайт — спрашиваем его так же,
                // как это делает меню.
                match online::разделы_живых()
                    .into_iter()
                    .find(|(_, н)| н.eq_ignore_ascii_case(имя))
                {
                    Some(раздел) => { фильтры.раздел = Some(раздел); true }
                    None => false,
                }
            }
            _ => false,
        };
        if !понято {
            eprintln!("непонятный фильтр: {правка}");
            return 2;
        }
    }

    // Страница выдачи: у бесконечных источников (NASA, artic) их десятки
    // тысяч, и посмотреть только первую — значит не проверить листание вовсе.
    let страница: u32 = хвост
        .iter()
        .find_map(|a| a.strip_prefix("страница="))
        .and_then(|s| s.parse().ok())
        .unwrap_or(1);
    let находки = match online::список(источник, страница, 2560, 1080, &запрос, &фильтры) {
        Ok(н) => н,
        Err(e) => {
            eprintln!("не вышло: {e}");
            return 1;
        }
    };

    // Отбор по цвету идёт по миниатюрам, поэтому здесь их приходится скачать —
    // в живом меню они и так качаются для сетки.
    let (находки, было) = match фильтры.цвет {
        None => { let n = находки.len(); (находки, n) }
        Some(цвет) => {
            let было = находки.len();
            let мини: Vec<_> = находки
                .iter()
                .map(|н| match online::миниатюра(н) {
                    Some(байты) => разобрать_миниатюру(&байты),
                    None => пустая_миниатюра(),
                })
                .collect();
            for (н, (_, _, px)) in находки.iter().zip(&мини) {
                let имя: String = н.имя.chars().take(50).collect();
                match palette::приметы_цвета(px) {
                    Some((тон, цветность, светлота)) => println!(
                        "  {имя:<50} тон {тон:>5.0}°  цветность {цветность:.2}  светлота {светлота:.2}{}",
                        if palette::подходит_по_приметам(тон, цветность, светлота, цвет) { "  ✓" } else { "" },
                    ),
                    None => println!("  {имя:<50} миниатюра не скачалась"),
                }
            }
            let (н, _) = отобрать_по_цвету(находки, мини, Some(цвет));
            (н, было)
        }
    };

    println!("найдено: {}{}{}", находки.len(),
             if запрос.is_empty() { String::new() } else { format!(" по запросу «{запрос}»") },
             match фильтры.цвет {
                 Some(ц) => format!(" (по цвету «{}» из {было})", ц.имя()),
                 None => String::new(),
             });
    for н in находки.iter().take(5) {
        println!("  {} — {}", н.имя, н.миниатюра);
    }

    if действие.as_deref() == Some("скачать") {
        let Some(первая) = находки.first() else { return 1 };
        match online::скачать(первая, &каталог_загрузок()) {
            Ok(путь) => {
                let размер = std::fs::metadata(&путь).map(|m| m.len()).unwrap_or(0);
                println!("скачано: {} ({} байт)", путь.display(), размер);
            }
            Err(e) => {
                eprintln!("скачать не вышло: {e}");
                return 1;
            }
        }
    }
    0
}

/// Ошибка, после которой можно продолжать (сокет просто пуст или занят).
/// Всё остальное — обрыв связи с композитором, и жить дальше нам незачем.
fn временная_ошибка(e: &wayland_client::backend::WaylandError) -> bool {
    match e {
        wayland_client::backend::WaylandError::Io(io) => matches!(
            io.kind(),
            std::io::ErrorKind::WouldBlock | std::io::ErrorKind::Interrupted
        ),
        _ => false,
    }
}

// ── Signal FD ────────────────────────────────────────────────────────────────

fn setup_signalfd() -> i32 {
    let mut mask: libc::sigset_t = unsafe { std::mem::zeroed() };
    unsafe {
        libc::sigemptyset(&mut mask);
        // Блокируем USR1 и USR2 — они пойдут через signalfd
        libc::sigaddset(&mut mask, libc::SIGUSR1);
        libc::sigaddset(&mut mask, libc::SIGUSR2);
        libc::sigprocmask(libc::SIG_BLOCK, &mask, std::ptr::null_mut());
    }
    let fd = unsafe { libc::signalfd(-1, &mask, libc::SFD_CLOEXEC | libc::SFD_NONBLOCK) };
    if fd < 0 { panic!("signalfd failed"); }
    fd
}

fn process_signalfd(config: &mut Config) {
    let sfd = match config.signalfd { Some(fd) => fd, None => return };
    let mut buf: [u8; 128] = [0; 128]; // sizeof(signalfd_siginfo)
    loop {
        let n = unsafe { libc::read(sfd, buf.as_mut_ptr() as *mut libc::c_void, 128) };
        if n <= 0 { break; }
        if n >= 4 {
            // signalfd_siginfo: первые 4 байта — ssi_signo (i32)
            let signo = i32::from_ne_bytes([buf[0], buf[1], buf[2], buf[3]]);
            match signo {
                libc::SIGUSR1 => SIG1.store(true, Ordering::SeqCst),
                libc::SIGUSR2 => SIG2.store(true, Ordering::SeqCst),
                _ => {}
            }
        }
    }
}

static SIG1: AtomicBool = AtomicBool::new(false);
static SIG2: AtomicBool = AtomicBool::new(false);

// ── Wayland Dispatch ─────────────────────────────────────────────────────────

impl Dispatch<WlRegistry, ()> for Config {
    fn event(
        state: &mut Self,
        registry: &WlRegistry,
        event: <WlRegistry as Proxy>::Event,
        _: &(),
        _conn: &Connection,
        qh: &QueueHandle<Self>,
    ) {
        use wayland_client::protocol::wl_registry::Event;
        if let Event::Global { name, ref interface, version } = event {
            match interface.as_str() {
                "wl_compositor" => state.compositor = Some(registry.bind(name, version, qh, ())),
                "wl_shm" => state.shm = Some(registry.bind(name, version, qh, ())),
                // Необязателен: под композитором без него plx-wall просто
                // масштабирует кадры сам, как раньше (см. render_wallpaper).
                "wp_viewporter" => state.viewporter = Some(registry.bind(name, version, qh, ())),
                // Тоже необязателен: нет dmabuf — видео поедет через ffmpeg.
                //
                // Версию берём не выше 3 СОЗНАТЕЛЬНО. С третьей приходят
                // события `modifier` со списком поддерживаемых сочетаний
                // «формат+модификатор», а нам этот список нужен: создавать
                // буфер вслепую нельзя (см. dmabuf_форматы). Четвёртая версия
                // заменяет их на feedback с отдельным объектом — лишняя
                // сложность ради тех же сведений.
                "zwp_linux_dmabuf_v1" if version >= 3 => {
                    state.dmabuf = Some(registry.bind(name, version.min(3), qh, ()));
                }
                "zwlr_layer_shell_v1" => {
                    state.layer_shell = Some(registry.bind(name, version.min(4), qh, ()));
                }
                "wl_output" => {
                    let output: WlOutput = registry.bind(name, version, qh, ());
                    state.outputs.push((output, 0, 0));
                }
                "wl_seat" => {
                    let seat: WlSeat = registry.bind(name, version, qh, ());
                    state.pointer = Some(seat.get_pointer(qh, ()));
                }
                _ => {}
            }
        }
    }
}

impl Dispatch<WlOutput, ()> for Config {
    fn event(
        state: &mut Self,
        output: &WlOutput,
        event: wl_output::Event,
        _: &(),
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
    ) {
        if let wl_output::Event::Mode { flags: _, width, height, refresh } = event {
            // refresh — в мГц. Берём самый быстрый выход: меню на нём и
            // смотрится, а на медленном лишние кадры композитор просто
            // придержит отдачей буфера.
            if refresh > 0 {
                let мкс = (1_000_000_000u64 / refresh as u64).clamp(4_000, 16_667) as u32;
                ПЕРИОД_МЕНЮ_МКС.fetch_min(мкс, ПорядокАтомика::Relaxed);
            }
            for (ref o, w, h) in &mut state.outputs {
                if o.id() == output.id() { *w = width as u32; *h = height as u32; }
            }
            // Только создаём поверхности. Рисовать отсюда нельзя: первый
            // configure ещё не пришёл, а attach до его ack — протокольная
            // ошибка. Рендер запускает сам обработчик Configure.
            if state.фоны.len() < state.outputs.len() { setup_layers(state); }
            if state.фоны.iter().any(|ф| ф.configured) { render_wallpaper(state); }
        }
    }
}

impl Dispatch<ZwlrLayerShellV1, ()> for Config {
    fn event(_: &mut Self, _: &ZwlrLayerShellV1, _: zwlr_layer_shell_v1::Event, _: &(), _: &Connection, _: &QueueHandle<Self>) {}
}

impl Dispatch<ZwlrLayerSurfaceV1, ()> for Config {
    fn event(
        state: &mut Self,
        surface: &ZwlrLayerSurfaceV1,
        event: zwlr_layer_surface_v1::Event,
        _: &(),
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
    ) {
        match event {
            zwlr_layer_surface_v1::Event::Configure { serial, width, height } => {
                surface.ack_configure(serial);
                let id = surface.id();
                // Configure приходит на КОНКРЕТНУЮ поверхность — по ней и
                // находим её фон. Размер запоминаем свой у каждого монитора:
                // раньше он писался в outputs.first() без разбора, то есть
                // configure второго экрана затирал размер первого.
                let фон = state.фоны.iter_mut().find(|ф| ф.layer.id() == id);
                if let Some(фон) = фон {
                    // Размер обоев берём из configure, а не из wl_output.Mode:
                    // Mode отдаёт физические пиксели режима, а layer-shell —
                    // логический размер, который композитор реально отвёл. При
                    // scale != 1 это разные числа, и буфер разъезжался бы с экраном.
                    let mut changed = !фон.configured;
                    if width > 0 && height > 0 && фон.размер != (width, height) {
                        фон.размер = (width, height);
                        changed = true;
                    }
                    фон.configured = true;
                    // Первый ack — рисуем в любом случае: до него мы не имели
                    // права трогать буфер, значит фон ещё пуст.
                    if changed { render_wallpaper(state); }
                } else if state.ol_layer.as_ref().map(|l| l.id()) == Some(id) {
                    state.ol_configured = true;
                    if state.overlay_visible { render_overlay(state); }
                }
            }
            // Композитор снёс поверхность (выход отключили, шелл закрылся).
            // Держать на неё ссылку нельзя: следующий commit — протокольная
            // ошибка и дисконнект. Обнуляем, setup_layers создаст заново.
            zwlr_layer_surface_v1::Event::Closed => {
                let id = surface.id();
                if let Some(i) = state.фоны.iter().position(|ф| ф.layer.id() == id) {
                    // Уносим фон целиком: и layer, и поверхность, и viewport.
                    // Если выход просто отключили, его wl_output уйдёт следом и
                    // второй раз фон никто не заведёт; если поверхность снёс сам
                    // шелл — её пересоздаст setup_layers из главного цикла.
                    let фон = state.фоны.remove(i);
                    if let Some(vp) = фон.viewport.as_ref() { vp.destroy(); }
                    фон.layer.destroy();
                    фон.surface.destroy();
                } else if state.ol_layer.as_ref().map(|l| l.id()) == Some(id) {
                    state.ol_layer = None;
                    state.ol_surface = None;
                    state.ol_configured = false;
                    state.overlay_visible = false;
                }
            }
            _ => {}
        }
    }
}

impl Dispatch<WlShm, ()> for Config {
    fn event(_: &mut Self, _: &WlShm, _: wl_shm::Event, _: &(), _: &Connection, _: &QueueHandle<Self>) {}
}

impl Dispatch<WlCompositor, ()> for Config {
    fn event(_: &mut Self, _: &WlCompositor, _: <WlCompositor as Proxy>::Event, _: &(), _: &Connection, _: &QueueHandle<Self>) {}
}

impl Dispatch<WlSeat, ()> for Config {
    fn event(
        state: &mut Self,
        seat: &WlSeat,
        event: <WlSeat as Proxy>::Event,
        _: &(),
        _: &Connection,
        qh: &QueueHandle<Self>,
    ) {
        if let wl_seat::Event::Capabilities { capabilities: WEnum::Value(возможности) } = event {
            let есть = возможности.contains(wl_seat::Capability::Touch);
            if есть && state.touch.is_none() {
                state.touch = Some(seat.get_touch(qh, ()));
            } else if !есть {
                // Экран отключили (или parallax выключил `touch`) — касание,
                // оставшееся висеть, иначе так и считалось бы нажатым.
                if let Some(t) = state.touch.take() {
                    if t.version() >= 3 {
                        t.release();
                    }
                }
                state.касание = None;
            }
        }
    }
}

/// Палец на меню.
///
/// Меню — лента, и пальцем по ней ВОДЯТ: тап выбирает карточку (как клик),
/// мазок вбок листает ленту за пальцем, бросок докручивает ещё несколько
/// карточек, долгое нажатие — как правая кнопка (удалить из списка), так же,
/// как долгое нажатие в самом parallax (`touch_long_press`).
///
/// Палец ведём один: второй палец на ленте смысла не несёт, а мультитач здесь
/// означал бы спор двух пальцев за одну прокрутку.
struct Касание {
    id: i32,
    старт: (f64, f64),
    где: (f64, f64),
    когда: std::time::Instant,
    /// Сколько карточек лента уже пролистала за этим пальцем.
    шагов: i32,
    /// Мазок признан листанием — тапом он уже не станет.
    листает: bool,
    /// Прошлое положение по x и его время — по ним скорость броска.
    прошлое: (f64, std::time::Instant),
    скорость: f64,
}

/// Дальше этого (в пикселях меню) палец уехал — это уже мазок, а не тап.
const ТАП_ДОПУСК: f64 = 14.0;
/// Сколько держать палец, чтобы нажатие стало «правой кнопкой».
const ДОЛГОЕ_НАЖАТИЕ: std::time::Duration = std::time::Duration::from_millis(500);
/// Бросок: скорость (пикс/с), начиная с которой лента докручивается сама, и
/// сколько скорости приходится на одну лишнюю карточку.
const БРОСОК_ОТ: f64 = 900.0;
const БРОСОК_НА_КАРТОЧКУ: f64 = 1400.0;

/// На сколько пикселей пальца приходится одна карточка ленты — ровно шаг между
/// серединами соседних карточек, чтобы карточка шла ПОД пальцем.
fn шаг_пальца() -> f64 {
    ((карта_w() + GAP) as f32 * ГЛУБИНА_ШАГ).max(1.0) as f64
}

impl Dispatch<WlTouch, ()> for Config {
    fn event(
        state: &mut Self,
        _: &WlTouch,
        event: <WlTouch as Proxy>::Event,
        _: &(),
        _: &Connection,
        _: &QueueHandle<Self>,
    ) {
        match event {
            wl_touch::Event::Down { id, surface, x, y, .. } => {
                // Касания приходят на ту поверхность, куда легли; у фона
                // регион ввода есть, но нажимать там нечего.
                let на_меню = state.ol_surface.as_ref().map(|s| s.id()) == Some(surface.id());
                if на_меню {
                    палец_вниз(state, id, x, y);
                }
            }
            wl_touch::Event::Motion { id, x, y, .. } => палец_ведёт(state, id, x, y),
            wl_touch::Event::Up { id, .. } => палец_вверх(state, id, true),
            wl_touch::Event::Cancel => {
                // Касание забрал композитор (его жест) — ничего не нажимаем.
                if state.касание.take().is_some() {
                    state.cursor_x = -1.0;
                    state.cursor_y = -1.0;
                    state.dirty = true;
                }
            }
            _ => {}
        }
    }
}

/// Номер «пальца» для левой кнопки мыши. Настоящие касания нумерует
/// композитор с нуля, отрицательных у него не бывает.
const ПАЛЕЦ_МЫШИ: i32 = -1;

/// Палец (или левая кнопка) лёг на меню. Сам по себе ничего не нажимает: что
/// это было — тап или мазок по ленте, — станет ясно к отпусканию.
fn палец_вниз(state: &mut Config, id: i32, x: f64, y: f64) {
    if !state.overlay_visible || state.касание.is_some() {
        return;
    }
    let сейчас = std::time::Instant::now();
    state.касание = Some(Касание {
        id,
        старт: (x, y),
        где: (x, y),
        когда: сейчас,
        шагов: 0,
        листает: false,
        прошлое: (x, сейчас),
        скорость: 0.0,
    });
    // Подсветка идёт за пальцем так же, как за курсором: видно, что именно
    // сейчас нажмётся.
    state.cursor_x = x;
    state.cursor_y = y;
    state.dirty = true;
}

fn палец_ведёт(state: &mut Config, id: i32, x: f64, y: f64) {
    let Some(к) = state.касание.as_mut().filter(|к| к.id == id) else { return };
    к.где = (x, y);
    let сейчас = std::time::Instant::now();
    let dt = сейчас.duration_since(к.прошлое.1).as_secs_f64();
    if dt > 0.004 {
        // Сглаженная скорость: одно событие с дрожью не должно превращать
        // спокойный отпуск пальца в бросок.
        let мгновенная = (x - к.прошлое.0) / dt;
        к.скорость = к.скорость * 0.4 + мгновенная * 0.6;
        к.прошлое = (x, сейчас);
    }
    let (dx, dy) = (x - к.старт.0, y - к.старт.1);
    if !к.листает && dx.abs() > ТАП_ДОПУСК && dx.abs() > dy.abs() {
        к.листает = true;
    }
    if !к.листает {
        return;
    }
    // Палец влево — лента вперёд: карточка справа подъезжает под палец, как у
    // любой ленты на телефоне.
    let надо = (-dx / шаг_пальца()).round() as i32;
    let разница = надо - к.шагов;
    к.шагов = надо;
    if разница != 0 {
        прокрутить(state, разница);
    }
}

/// Палец поднят. `может_правую`: долгое нажатие считается правой кнопкой —
/// только у настоящего касания; мышь, зажатую надолго, parallax и так
/// превращает в правую сам (`touch_long_press`), а человек с мышью просто
/// задумался.
fn палец_вверх(state: &mut Config, id: i32, может_правую: bool) {
    let Some(к) = state.касание.take_if(|к| к.id == id) else { return };
    let (dx, dy) = (к.где.0 - к.старт.0, к.где.1 - к.старт.1);
    if к.листает {
        // Бросок: палец ушёл быстро — ленте ещё ехать. Если палец перед
        // отпуском остановился, скорость успела погаснуть, и лента встаёт там,
        // где её оставили.
        let свежая = к.прошлое.1.elapsed() < std::time::Duration::from_millis(80);
        if свежая && к.скорость.abs() > БРОСОК_ОТ {
            let ещё = (1 + ((к.скорость.abs() - БРОСОК_ОТ) / БРОСОК_НА_КАРТОЧКУ) as i32).min(6);
            прокрутить(state, if к.скорость < 0.0 { ещё } else { -ещё });
        }
    } else if dx.hypot(dy) <= ТАП_ДОПУСК {
        let правая = может_правую && к.когда.elapsed() >= ДОЛГОЕ_НАЖАТИЕ;
        let (cx, cy) = (к.старт.0.max(0.0) as u32, к.старт.1.max(0.0) as u32);
        нажатие_в_меню(state, cx, cy, правая);
    }
    if id != ПАЛЕЦ_МЫШИ {
        // Пальца больше нет — и подсветке не за чем идти. У мыши курсор
        // остаётся там, где был.
        state.cursor_x = -1.0;
        state.cursor_y = -1.0;
        state.hover = None;
    }
    state.dirty = true;
}

impl Dispatch<WlPointer, ()> for Config {
    fn event(
        state: &mut Self,
        _: &WlPointer,
        event: <WlPointer as Proxy>::Event,
        _: &(),
        conn: &Connection,
        _qh: &QueueHandle<Self>,
    ) {
        match event {
            wl_pointer::Event::Enter { .. } => {}
            wl_pointer::Event::Leave { .. } => {
                // Кнопку отпустили уже за меню — нажатием это не считаем.
                if state.касание.as_ref().is_some_and(|к| к.id == ПАЛЕЦ_МЫШИ) {
                    state.касание = None;
                }
                state.cursor_x = -1.0; state.cursor_y = -1.0;
                if state.hover.take().is_some() { state.dirty = true; }
            }
            wl_pointer::Event::Motion { surface_x, surface_y, .. } => {
                state.cursor_x = surface_x; state.cursor_y = surface_y;
                // Зажатая левая кнопка тянет ленту (см. ПАЛЕЦ_МЫШИ). Это же и
                // сенсор под parallax: касание слоя он отдаёт не wl_touch, а
                // курсором с зажатой левой кнопкой.
                палец_ведёт(state, ПАЛЕЦ_МЫШИ, surface_x, surface_y);
                // Перерисовываем ТОЛЬКО когда сменилась карточка под курсором:
                // в меню от положения мыши зависит одна подсветка, а событий
                // движения приходит до тысячи в секунду.
                let под_курсором = hover_cell(state);
                if под_курсором != state.hover {
                    state.hover = под_курсором;
                    state.dirty = true;
                }
            }
            // Колесо листает ленту обоев. Композитор шлёт величину в единицах
            // поверхности, одна «щёлка» — около 10..15; копим и шагаем
            // КАРТОЧКАМИ, иначе плавный тачпад давал бы полкарточки, а половин
            // лента не рисует (см. сетка).
            //
            // Обе оси — одна и та же прокрутка: лента едет вбок, и
            // горизонтальное колесо (или двупальцевый жест вбок на тачпаде)
            // обязано её листать; вертикальное оставлено потому, что обычная
            // мышь другого колеса не имеет.
            wl_pointer::Event::Axis { axis, value, .. } if state.overlay_visible => {
                let по_ленте = matches!(
                    axis,
                    WEnum::Value(wl_pointer::Axis::VerticalScroll)
                        | WEnum::Value(wl_pointer::Axis::HorizontalScroll)
                );
                if по_ленте {
                    const ЩЁЛЧОК: f64 = 10.0;
                    state.scroll_acc += value;
                    while state.scroll_acc >= ЩЁЛЧОК {
                        state.scroll_acc -= ЩЁЛЧОК;
                        прокрутить(state, 1);
                    }
                    while state.scroll_acc <= -ЩЁЛЧОК {
                        state.scroll_acc += ЩЁЛЧОК;
                        прокрутить(state, -1);
                    }
                }
            }
            wl_pointer::Event::Button { button, state: btn_state, .. }
                if btn_state == WEnum::Value(wl_pointer::ButtonState::Pressed)
                    && state.overlay_visible =>
            {
                // ПКМ по карточке — то же удаление, что и крестиком, но
                // попасть проще: целиться в кнопку 28×28 мышью не всегда
                // удобно, а промах по ней выбирает обои и закрывает меню.
                const BTN_LEFT: u32 = 0x110;
                const BTN_RIGHT: u32 = 0x111;
                // Меню слушает ровно две кнопки. Раньше условие было «любая
                // нажатая», и боковые кнопки мыши (0x113/0x114 — «вперёд» и
                // «назад», их легко задеть ладонью) молча выбирали обои и
                // закрывали меню.
                if button != BTN_LEFT && button != BTN_RIGHT { return; }
                let правая = button == BTN_RIGHT;
                // Курсор вне поверхности помечен как -1: `as u32` в Rust
                // насыщает отрицательное к нулю, так что без этой проверки
                // «мышь ушла» нажимало бы карточку в левом верхнем углу.
                if state.cursor_x < 0.0 || state.cursor_y < 0.0 { return; }
                if !правая {
                    // Левая нажимает на ОТПУСКАНИИ: между нажатием и
                    // отпусканием ею можно протянуть ленту, и тогда это
                    // листание, а не выбор карточки.
                    палец_вниз(state, ПАЛЕЦ_МЫШИ, state.cursor_x, state.cursor_y);
                    return;
                }
                let cx = state.cursor_x as u32;
                let cy = state.cursor_y as u32;
                нажатие_в_меню(state, cx, cy, правая);
            }
            wl_pointer::Event::Button { button: 0x110, state: btn_state, .. }
                if btn_state == WEnum::Value(wl_pointer::ButtonState::Released) =>
            {
                палец_вверх(state, ПАЛЕЦ_МЫШИ, false);
            }
            _ => {}
        }
    }
}

/// Нажатие в меню по точке (cx, cy) поверхности меню. Одна дорога и для мыши,
/// и для пальца (см. [`Dispatch<WlTouch>`]): разойдись они, касание выбирало
/// бы не то, что клик.
fn нажатие_в_меню(state: &mut Config, cx: u32, cy: u32, правая: bool) {
    // Действие вынимаем ДО обработки: тело меняет state (и сам
    // hit_rects через build_ui_layout), а держать на него ссылку
    // в это время нельзя.
    let hit = state.hit_rects.iter().find(|r| {
        cx >= r.x && cx < r.x + r.w && cy >= r.y && cy < r.y + r.h
    }).map(|r| r.action);
    // Для правой кнопки выбор карточки превращаем в удаление.
    let hit = match (правая, hit) {
        (true, Some(UiAction::SelectWallpaper(i))) => Some(UiAction::DeleteWallpaper(i)),
        (true, Some(UiAction::AddWallpaper)) => None,
        (_, h) => h,
    };
    match hit {
        Some(UiAction::Scroll(шаг)) => прокрутить(state, шаг),
        Some(UiAction::Вкладка(в)) => открыть_вкладку(state, в),
        Some(UiAction::Поиск) => {
            // Меню — слой Overlay, то есть ВЫШЕ слоя top, на
            // котором открывается rofi. Значит убрать меню надо
            // ДО запуска строки ввода, иначе она откроется под ним
            // и снаружи это выглядит как «поиск не появился».
            //
            // Раньше здесь стояло `hide_overlay(state)` без
            // проверки результата, а она возвращает false, когда
            // оба буфера ещё у композитора. Кадр не уходил, меню
            // оставалось на экране — и тем чаще, чем больше окон
            // на экране, потому что буферы отпускаются медленнее.
            //
            // Поэтому только ПРОСИМ поиск, а запускаем его из
            // главного цикла — там уже есть готовый механизм
            // «повторять, пока кадр не ушёл» (см. state.dirty), и
            // там же обрабатываются события композитора, без
            // которых буфер никогда не освободится. Делать
            // roundtrip прямо отсюда нельзя: мы внутри разбора
            // очереди событий.
            state.overlay_visible = false;
            state.запросить_поиск = true;
            state.dirty = true;
        }
        Some(UiAction::Фильтр) => {
            // Меню фильтров показывает тот же rofi — и по той же
            // причине убирается заранее (см. UiAction::Поиск).
            state.overlay_visible = false;
            state.запросить_фильтр = true;
            state.dirty = true;
        }
        Some(UiAction::Источник(i)) => сменить_источник(state, i),
        Some(UiAction::Цикл) => {
            state.цикл = !state.цикл;
            save_cycle(state.цикл);
            сообщить_цикл(state.цикл);
            state.dirty = true;
        }
        Some(UiAction::ВзятьИзСети(idx)) => взять_из_сети(state, idx),
        Some(UiAction::Далее) => {
            загрузить_страницу(state, state.сетевая_страница + 1, true)
        }
        Some(UiAction::SelectWallpaper(idx)) => {
            if idx < state.wallpapers.len() {
                state.current = idx;
                let путь = state.wallpapers[state.current].clone();
                start_load_wallpaper(state, путь);
                state.overlay_visible = false;
                state.dirty = true;
            }
        }
        Some(UiAction::DeleteWallpaper(idx)) => {
            if idx < state.wallpapers.len() {
                state.wallpapers.remove(idx);
                save_config(&state.wallpapers);
                // Список поехал — миниатюры пересчитываем, а
                // указатель на текущие обои поправляем, чтобы он
                // не показывал на чужую или несуществующую строку.
                // Готовые миниатюры переедут по пути (см.
                // load_thumbnails), а номера карточек сдвинулись —
                // кэш ужатых сбрасываем целиком.
                state.кэш_карточек.сбросить();
                if state.wallpapers.is_empty() {
                    state.current = 0;
                    state.img = None;
                    render_wallpaper(state);
                } else {
                    if state.current >= idx && state.current > 0 {
                        state.current -= 1;
                    }
                    state.current = state.current.min(state.wallpapers.len() - 1);
                    let путь = state.wallpapers[state.current].clone();
                    start_load_wallpaper(state, путь);
                }
                load_thumbnails(state);
                build_ui_layout(state);
                state.dirty = true;
            }
        }
        Some(UiAction::AddWallpaper) => {
            // Меню — слой Overlay, он рисуется ПОВЕРХ обычных окон, и
            // проводник (zenity) открывался ПОД ним. Убираем меню
            // заранее, а диалог запускает главный цикл — когда
            // закрытие доиграло (см. «Строка поиска, меню
            // фильтров, выбор файла»).
            state.overlay_visible = false;
            state.запросить_файл = true;
            state.dirty = true;
        }
        None => {}
    }
}

impl Dispatch<WlSurface, ()> for Config {
    fn event(_: &mut Self, _: &WlSurface, _: <WlSurface as Proxy>::Event, _: &(), _: &Connection, _: &QueueHandle<Self>) {}
}

/// Кадровый callback обоев: композитор ответил — значит обои на экране видно.
///
/// Ответ приходит только на тот запрос, что сделан в render_wallpaper. Пока
/// parallax держит обои закрытыми полноэкранным окном, ответа нет вовсе — по этому
/// молчанию главный цикл и засыпает (см. ОЖИДАНИЕ_КАДРА).
impl Dispatch<WlCallback, ()> for Config {
    fn event(
        state: &mut Self,
        _: &WlCallback,
        event: <WlCallback as Proxy>::Event,
        _: &(),
        _: &Connection,
        _: &QueueHandle<Self>,
    ) {
        if let wayland_client::protocol::wl_callback::Event::Done { .. } = event {
            state.кадр_заказан = None;
            state.callback_был = true;
            // Обои снова показались: главный цикл сам заберёт застрявший в
            // декодере кадр — срок его показа давно прошёл.
            state.видно = true;
        }
    }
}

impl Dispatch<WlShmPool, ()> for Config {
    fn event(_: &mut Self, _: &WlShmPool, _: wl_shm_pool::Event, _: &(), _: &Connection, _: &QueueHandle<Self>) {}
}

/// Буферы постоянных слотов: ждём `release`, чтобы знать, в какой можно писать.
impl Dispatch<WlBuffer, Занятость> for Config {
    fn event(
        _: &mut Self,
        _: &WlBuffer,
        event: <WlBuffer as Proxy>::Event,
        занят: &Занятость,
        _: &Connection,
        _: &QueueHandle<Self>,
    ) {
        if let wayland_client::protocol::wl_buffer::Event::Release = event {
            // Насыщенное вычитание, а не `fetch_sub`: лишний release (например,
            // от поверхности, которую композитор снёс вместе с выходом) не должен
            // прокрутить счётчик через ноль в usize::MAX — слот тогда навсегда
            // считался бы занятым и обои замерли бы.
            let _ = занят.fetch_update(Ordering::Relaxed, Ordering::Relaxed, |n| {
                Some(n.saturating_sub(1))
            });
        }
    }
}

impl Dispatch<WlBuffer, ()> for Config {
    fn event(_: &mut Self, _: &WlBuffer, _: <WlBuffer as Proxy>::Event, _: &(), _: &Connection, _: &QueueHandle<Self>) {}
}

impl Dispatch<WlRegion, ()> for Config {
    fn event(_: &mut Self, _: &WlRegion, _: <WlRegion as Proxy>::Event, _: &(), _: &Connection, _: &QueueHandle<Self>) {}
}

/// Глобал linux-dmabuf: копим объявленные композитором сочетания
/// «формат + модификатор».
///
/// Версия 3 шлёт их событиями `modifier` сразу после привязки. Устаревшее
/// `format` (версия 1) игнорируем: модификатора в нём нет, а без модификатора
/// буфер всё равно не создать — у видеокарты кадр разложен плиткой, и линейным
/// его считать нельзя.
impl Dispatch<ZwpLinuxDmabufV1, ()> for Config {
    fn event(
        state: &mut Self,
        _: &ZwpLinuxDmabufV1,
        event: <ZwpLinuxDmabufV1 as Proxy>::Event,
        _: &(),
        _: &Connection,
        _: &QueueHandle<Self>,
    ) {
        if let zwp_linux_dmabuf_v1::Event::Modifier { format, modifier_hi, modifier_lo } = event {
            let модификатор = ((modifier_hi as u64) << 32) | modifier_lo as u64;
            state.dmabuf_форматы.insert((format, модификатор));
        }
    }
}

/// Заготовка буфера. Событий ждать не приходится: буфер создаётся через
/// `create_immed`, то есть сразу и без ответа композитора.
impl Dispatch<ZwpLinuxBufferParamsV1, ()> for Config {
    fn event(
        _: &mut Self,
        _: &ZwpLinuxBufferParamsV1,
        _: <ZwpLinuxBufferParamsV1 as Proxy>::Event,
        _: &(),
        _: &Connection,
        _: &QueueHandle<Self>,
    ) {
    }
}

// У viewporter и самого viewport событий нет — только запросы от нас.
impl Dispatch<WpViewporter, ()> for Config {
    fn event(_: &mut Self, _: &WpViewporter, _: <WpViewporter as Proxy>::Event, _: &(), _: &Connection, _: &QueueHandle<Self>) {}
}
impl Dispatch<WpViewport, ()> for Config {
    fn event(_: &mut Self, _: &WpViewport, _: <WpViewport as Proxy>::Event, _: &(), _: &Connection, _: &QueueHandle<Self>) {}
}

// ── Layer setup ──────────────────────────────────────────────────────────────

fn setup_layers(state: &mut Config) {
    let Some(ref compositor) = state.compositor else { return };
    let Some(ref layer_shell) = state.layer_shell else { return };
    let Some(ref qh) = state.qh else { return };
    let Some((ref output, _, _)) = state.outputs.first() else { return };

    // ── Background — обои, СВОЯ поверхность на каждом выходе ─────────────────
    //
    // Зовётся заново при появлении каждого нового выхода, поэтому заводим фон
    // только тем, у кого его ещё нет: повторный вызов не должен плодить вторую
    // поверхность на том же мониторе.
    let выходы: Vec<WlOutput> = state.outputs.iter().map(|(o, _, _)| o.clone()).collect();
    for выход in выходы {
        if state.фоны.iter().any(|ф| ф.выход.id() == выход.id()) {
            continue;
        }
        let bg = compositor.create_surface(qh, ());
        let layer = layer_shell.get_layer_surface(
            &bg, Some(&выход), zwlr_layer_shell_v1::Layer::Background,
            "plx-wall".to_string(), qh, (),
        );
        // set_size(0,0) + якорь по всем краям = «во весь этот выход»; настоящий
        // размер придёт в configure, у каждого монитора свой.
        layer.set_size(0, 0);
        layer.set_anchor(zwlr_layer_surface_v1::Anchor::all());
        layer.set_exclusive_zone(-1);
        // Viewport заводим один раз на всю жизнь поверхности; прямоугольники
        // задаются на каждом кадре (см. `показать_на_фонах`).
        let viewport = state.viewporter.as_ref().map(|vp| vp.get_viewport(&bg, qh, ()));
        bg.commit();
        state.фоны.push(Фон {
            выход,
            surface: bg,
            layer,
            viewport,
            configured: false,
            размер: (0, 0),
        });
    }

    // Overlay заводим только один раз и только на первом выходе: меню выбора
    // обоев — это одно окно, показывать его копиями на каждом мониторе не надо.
    if state.ol_surface.is_some() {
        return;
    }

    // Overlay — UI выбора.
    //
    // Размер задаём ТОЛЬКО через set_size, без якорей: буфер у нас ровно
    // ui_w()×ui_h(), а якорь по всем четырём краям заставил бы композитор
    // растянуть поверхность на весь выход, и она разъехалась бы с буфером.
    // Без якорей layer-shell центрирует поверхность на выходе — что нам и надо.
    let ol = compositor.create_surface(qh, ());
    let ol_layer = layer_shell.get_layer_surface(
        &ol, Some(output), zwlr_layer_shell_v1::Layer::Overlay,
        "plx-wall-overlay".to_string(), qh, (),
    );
    ol_layer.set_size(ui_w(), ui_h());
    ol_layer.set_exclusive_zone(-1);
    // Клавиатуру просим ТОЛЬКО когда меню открыто (см. главный цикл).
    //
    // Раньше OnDemand стоял здесь, при создании поверхности, — «без клавиатуры
    // оверлей нечем закрыть с клавиш». Но поверхность заводится сразу при
    // старте plx-wall и живёт всегда: закрытое меню — это прозрачный кадр с
    // пустым регионом ввода, а не отсутствие слоя. Композитор честно отдавал
    // клавиатуру тому, кто её просит, и весь ввод уходил в невидимое меню.
    // На десктопе это маскировалось (первый клик по окну возвращает фокус), а
    // на свежем входе в сеанс кликать не по чему — выглядело как намертво
    // зависший сеанс при играющих обоях (31.08.2026).
    ol.commit();
    state.ol_surface = Some(ol);
    state.ol_layer = Some(ol_layer);
}

// ── Background rendering ─────────────────────────────────────────────────────

/// Прицепить готовый буфер ко ВСЕМ фоновым поверхностям и вернуть, скольким
/// из них он достался.
///
/// Возвращённое число — это [`Занятость`] буфера: композитор пришлёт по одному
/// `release` на каждую поверхность, и писать в буфер снова можно только после
/// последнего. Ноль значит «показать было некому» — звавший обязан считать, что
/// кадр не ушёл (буфер остаётся свободным).
///
/// Кадр у всех мониторов ОДИН, различаются только прямоугольники viewport:
/// `src` берёт из кадра центральный кусок под пропорцию этого экрана, `dst`
/// растягивает его на весь экран. Это тот же закон «заполнить», что раньше
/// исполнял `blit_scaled`, только считает его видеокарта.
///
/// **Без `wp_viewporter` показываем только на первом выходе.** Тогда буфер
/// заведён размером с экран и растянут на процессоре под ОДИН конкретный
/// монитор; отдать его второму, у которого размер другой, значит показать
/// разъехавшуюся с экраном картинку. Прежнее одноэкранное поведение — честный
/// откат для композиторов без viewporter (в parallax он есть).
fn показать_на_фонах(state: &mut Config, буфер: &WlBuffer, кw: u32, кh: u32) -> usize {
    if кw == 0 || кh == 0 {
        return 0;
    }
    let есть_viewport = state.фоны.iter().any(|ф| ф.viewport.is_some());
    let сейчас = std::time::Instant::now();
    let mut отдано = 0usize;

    for (i, фон) in state.фоны.iter().enumerate() {
        if !фон.configured {
            continue;
        }
        let (эw, эh) = фон.размер;
        if эw == 0 || эh == 0 {
            continue;
        }
        match фон.viewport.as_ref() {
            Some(vp) => {
                let k = (эw as f64 / кw as f64).max(эh as f64 / кh as f64);
                let вид_w = (эw as f64 / k).min(кw as f64).max(1.0);
                let вид_h = (эh as f64 / k).min(кh as f64).max(1.0);
                vp.set_source((кw as f64 - вид_w) / 2.0, (кh as f64 - вид_h) / 2.0, вид_w, вид_h);
                vp.set_destination(эw as i32, эh as i32);
            }
            // Без viewporter — только первый выход, см. доктекст.
            None if i == 0 && !есть_viewport => {}
            None => continue,
        }
        // Кадровый callback у КАЖДОЙ поверхности: по нему понимаем, видно ли
        // обои. Молчание всех сразу и есть «нас не видно» — главный цикл тогда
        // перестаёт забирать кадры, декодер встаёт, видеокарта отдыхает. Пока
        // отвечает хоть один монитор, обои продолжают идти на нём.
        if let Some(qh) = state.qh.as_ref() {
            фон.surface.frame(qh, ());
        }
        фон.surface.attach(Some(буфер), 0, 0);
        // Порча — в координатах БУФЕРА, а он размером с кадр, не с экран.
        фон.surface.damage_buffer(0, 0, кw as i32, кh as i32);
        фон.surface.commit();
        отдано += 1;
    }

    if отдано > 0 {
        state.кадр_заказан = Some(сейчас);
    }
    отдано
}

fn render_wallpaper(state: &mut Config) {
    // Пока не подтверждён первый configure, attach запрещён протоколом. Ждём
    // хотя бы одну готовую поверхность: остальные подтянутся своим configure и
    // получат кадр следующим же вызовом.
    let Some(первый) = state.фоны.iter().find(|ф| ф.configured && ф.размер.0 > 0) else {
        return;
    };
    // Размер ПЕРВОГО готового экрана. С viewporter он ни на что не влияет —
    // буфер равен кадру, а под каждый монитор кроит его свой viewport. Нужен
    // только прежнему пути без viewporter, где кадр растягивается на процессоре
    // и потому годится ровно для одного экрана.
    let (w, h) = первый.размер;
    if w == 0 || h == 0 { return; }

    // ── Размер буфера ───────────────────────────────────────────────────────
    // С wp_viewporter буфер равен размеру КАДРА, а не экрана: композитор сам
    // растянет его на видеокарте. Это и есть вся оптимизация. Живые обои
    // 1280×720 на экране 3840×2160 — это 3.7 МБ на кадр вместо 33 МБ, и ни
    // одного масштабирования на процессоре: мы просто копируем кадр как есть.
    //
    // Замер 09.08.2026 до правки: ffmpeg растягивал сам — 264% CPU; после
    // переноса растягивания в plx-wall (blit_scaled) — 21% у ffmpeg и 48% у
    // plx-wall. Теперь растягивать не должен никто из них.
    //
    // Без viewporter (другой композитор) всё как раньше — буфер размером с
    // экран, растягиваем сами.
    let по_viewport = state.фоны.iter().any(|ф| ф.viewport.is_some());
    // Кадр, залитый декодером прямо в общую память, задаёт размер сам: своего
    // `img` у него нет и быть не должно — весь смысл в том, что кадр нигде,
    // кроме слота, не лежит.
    let (bw, bh) = match (state.кадр_слота, по_viewport, state.img.as_ref()) {
        (Some((_, dw, dh)), _, _) if dw > 0 && dh > 0 => (dw, dh),
        (_, true, Some((iw, ih, _))) if *iw > 0 && *ih > 0 => (*iw, *ih),
        _ => (w, h),
    };
    let buf_size = (bw * bh * 4) as usize;

    // ── Два постоянных буфера вместо нового на каждый кадр ──────────────────
    // Пишем всегда в тот, что не показан сейчас. Раньше каждый кадр создавал
    // memfd, mmap, пул и wl_buffer — на живых обоях это десятки раз в секунду.
    if state.bg_dims != (bw, bh) || state.bg_slots.len() < 2 {
        state.bg_slots.clear();
        let (Some(shm), Some(qh)) = (state.shm.as_ref(), state.qh.as_ref()) else { return };
        let Some(slots) = make_slots(shm, qh, bw, bh) else { return };
        state.bg_slots = slots;
        state.bg_dims = (bw, bh);
        state.bg_slot = 0;
        // Кэш растянутой картинки считался под старый размер.
        state.scaled = None;
    }

    // Статичные обои готовим ОДИН раз: растягиваем под выход и переводим в
    // BGRA. Дальше и обычная перерисовка, и каждый кадр перехода — это просто
    // копирование готового буфера.
    //
    // Считаем в локальную переменную, а не прямо в state.scaled: пока живо
    // заимствование state.img, писать в state нельзя.
    // В режиме viewport кэш не нужен вовсе: буфер равен размеру картинки, и
    // «растягивание» сводится к копированию.
    let новый_кэш = if !по_viewport && state.anim.is_none() && state.scaled.is_none() {
        let bgra = state.img_bgra;
        state.img.as_ref().and_then(|(iw, ih, px)| {
            let mut кадр = if *iw == w && *ih == h && px.len() >= buf_size {
                px[..buf_size].to_vec()
            } else {
                resize(*iw, *ih, px, w, h)
            };
            if !bgra {
                for c in кадр.chunks_exact_mut(4) { c.swap(0, 2); }
            }
            (кадр.len() >= buf_size).then_some(кадр)
        })
    } else {
        None
    };
    if новый_кэш.is_some() {
        state.scaled = новый_кэш;
    }

    // Пишем только в тот буфер, который композитор уже отпустил. Раньше слоты
    // чередовались вслепую, и на живых обоях можно было попасть в буфер,
    // который прямо сейчас читают, — это видно как рваные прямоугольные куски
    // соседнего кадра.
    //
    // Свободного нет — не рисуем, но и не забываем: у живых обоев кадр можно
    // просто потерять, а вот единственный кадр статичной картинки потерять
    // нельзя, иначе обои так и не появятся. Флаг заставит главный цикл
    // повторить попытку.
    // Кадр от декодера уже лежит в своём слоте — его и показываем, ничего не
    // заполняя. Это и есть вся экономия: кадр приходит из ffmpeg сразу в ту
    // память, которую заберёт композитор.
    let готовый = state.кадр_слота.and_then(|(i, _, _)| (i < state.bg_slots.len()).then_some(i));
    let next = match готовый {
        Some(i) => i,
        None => match take_free_slot(&state.bg_slots, state.bg_slot) {
            Some(i) => i,
            None => {
                state.bg_pending = true;
                return;
            }
        },
    };
    state.bg_pending = false;
    state.bg_slot = next;
    let slot = &state.bg_slots[state.bg_slot];
    let dst = unsafe { std::slice::from_raw_parts_mut(slot.ptr, slot.len) };

    if готовый.is_some() {
        // Заполнять нечего. Дальше по коду — переход и viewport, они работают
        // поверх уже лежащего кадра.
    } else {
    match state.img {
        // Статичные обои идут через кэш: во время перехода кадр собирается
        // заново каждые ~16 мс, а Lanczos на 4K столько раз не потянуть.
        Some(_) if state.anim.is_none() && state.scaled.is_some() => {
            let кэш = state.scaled.as_ref().unwrap();
            if кэш.len() >= buf_size {
                dst.copy_from_slice(&кэш[..buf_size]);
            }
        }
        // Кадр уже нужного размера — просто копируем. Ни масштабирования, ни
        // свопа: самый дешёвый путь, ради него всё. С viewporter сюда попадает
        // ЛЮБОЙ кадр, потому что буфер под него и заведён.
        Some((iw, ih, ref px)) if iw == bw && ih == bh && px.len() >= buf_size => {
            dst.copy_from_slice(&px[..buf_size]);
            if !state.img_bgra {
                for c in dst.chunks_exact_mut(4) { c.swap(0, 2); }
            }
        }
        // Размер не совпал.
        //
        // Для АНИМАЦИИ масштабируем сами, прямо в разделяемую память: крейт
        // image на каждый кадр копировал исходник, заводил ещё один буфер на
        // весь экран и отдавал его нам третьей копией — 33 МБ туда-сюда по
        // десять раз в секунду. Свой блит по ближайшему соседу с заранее
        // посчитанной таблицей столбцов пишет ровно один раз и никаких
        // аллокаций не делает.
        Some((iw, ih, ref px)) if state.anim.is_some() && iw > 0 && ih > 0 => {
            blit_scaled(px, iw, ih, dst, bw, bh, state.img_bgra);
        }
        // Статичная картинка — путь прежний, качественный: она масштабируется
        // один раз при выборе, экономить тут нечего.
        Some((iw, ih, ref px)) => {
            let mut rgba = resize(iw, ih, px, bw, bh);
            if !state.img_bgra {
                for c in rgba.chunks_exact_mut(4) { c.swap(0, 2); }
            }
            if rgba.len() < buf_size { return; }
            dst.copy_from_slice(&rgba[..buf_size]);
        }
        None => dst.fill(35),
    }
    }

    // ── Плавный переход ─────────────────────────────────────────────────────
    // В dst уже лежит НОВЫЙ кадр; подмешиваем к нему снимок старого. Смешиваем
    // прямо на месте — лишний буфер на весь экран (это десятки мегабайт) тут
    // ни к чему.
    if let Some(fade) = state.fade.as_mut() {
        // Снимок сделан под ПРОШЛЫЕ обои, а у новых свой размер кадра (с
        // viewporter это обычное дело). Подгоняем один раз за переход, а не на
        // каждом кадре: дальше размеры уже совпадут.
        if !fade.ждём && fade.dims != (bw, bh) && fade.dims.0 > 0 && fade.dims.1 > 0 {
            let mut подогнан = vec![0u8; buf_size];
            blit_scaled(
                &fade.from, fade.dims.0, fade.dims.1,
                &mut подогнан, bw, bh,
                true, // в буферах уже BGRA, менять местами нечего
            );
            fade.from = подогнан;
            fade.dims = (bw, bh);
        }
        if fade.ждём {
            // Новые обои ещё не готовы — показываем старый кадр как есть.
        } else if fade.from.len() >= dst.len() {
            let начало = *fade.start.get_or_insert_with(std::time::Instant::now);
            let прошло = начало.elapsed().as_millis() as u64;
            if прошло >= FADE_MS {
                state.fade = None;
            } else {
                // Сглаживание по краям (smoothstep): линейное движение на глаз
                // начинается рывком и так же обрывается.
                let t = прошло as f32 / FADE_MS as f32;
                let t = t * t * (3.0 - 2.0 * t);
                шторка(dst, &fade.from, bw as usize, bh as usize, t);
            }
        } else {
            // Снимок не того размера (экран переключили посреди перехода) —
            // показываем новые обои сразу, без смешивания.
            state.fade = None;
        }
    }

    // ── Показать на всех мониторах ──────────────────────────────────────────
    // Кадр один, а прямоугольники viewport у каждого экрана свои — раскладку
    // и кадровый callback делает `показать_на_фонах`.
    //
    // Композитор не обязан отвечать на callback: parallax молчит, пока обои целиком
    // накрыты полноэкранным окном (см. Parallax::wallpaper_hidden). Молчание всех
    // поверхностей и есть «нас не видно»: главный цикл перестаёт забирать кадры,
    // очередь декодера (ёмкостью 1) переполняется, ffmpeg упирается в трубу и
    // встаёт. Запрос при этом не пропадает — он ждёт в поверхности и приедет
    // первым же кадром, когда обои снова покажутся.
    let буфер = state.bg_slots[state.bg_slot].buffer.clone();
    let отдано = показать_на_фонах(state, &буфер, bw, bh);
    // Показать было некому (все поверхности ещё без configure) — буфер остаётся
    // свободным, кадр повторится следующим вызовом.
    if отдано > 0 {
        state.bg_slots[state.bg_slot].занят.store(отдано, Ordering::Relaxed);
    }
}

/// Один кадр косой шторки: в `dst` уже НОВЫЕ обои, `from` — снимок старых того
/// же размера (BGRA). `t` — доля пути, 0…1.
///
/// Край шторки — наклонная прямая: в строке `y` он стоит на
/// `x = c + ШТОРКА_НАКЛОН · y/h` (в долях ширины), и `c` едет справа налево —
/// от «шторки ещё нет» до «закрыла всё». Правее края — новые обои, левее —
/// старые, в полосе шириной ШТОРКА_КРАЙ они смешиваются.
///
/// Считается ПОСТРОЧНО, а не попиксельно: у каждой строки край один, и
/// большую часть строки можно отдать одним `copy_from_slice` вместо
/// арифметики на каждый байт — на 4K это десятки мегабайт за кадр.
fn шторка(dst: &mut [u8], from: &[u8], w: usize, h: usize, t: f32) {
    if w == 0 || h == 0 || dst.len() < w * h * 4 || from.len() < w * h * 4 {
        return;
    }
    let край = ШТОРКА_КРАЙ;
    // c от (1 + край) — край целиком за правой границей даже в верхней строке —
    // до (−наклон − край) — целиком за левой в нижней.
    let c = (1.0 + край) - t * (1.0 + ШТОРКА_НАКЛОН + 2.0 * край);
    for y in 0..h {
        let строка = y * w * 4;
        let d = &mut dst[строка..строка + w * 4];
        let s = &from[строка..строка + w * 4];
        let ось = c + ШТОРКА_НАКЛОН * (y as f32 / h as f32);
        // Пиксели [0, левый) — старые целиком, [правый, w) — новые целиком.
        let левый = ((ось - край) * w as f32).floor().clamp(0.0, w as f32) as usize;
        let правый = ((ось + край) * w as f32).ceil().clamp(0.0, w as f32) as usize;
        d[..левый * 4].copy_from_slice(&s[..левый * 4]);
        let ширина = ((правый as f32 - левый as f32).max(1.0)) as f32;
        for x in левый..правый {
            // 0 — старые, 256 — новые; внутри полосы тоже smoothstep.
            let u = ((x - левый) as f32 + 0.5) / ширина;
            let u = u * u * (3.0 - 2.0 * u);
            let новый = (u * 256.0) as u32;
            let старый = 256 - новый;
            let i = x * 4;
            for k in 0..4 {
                d[i + k] = (((d[i + k] as u32) * новый + (s[i + k] as u32) * старый) >> 8) as u8;
            }
        }
    }
}

/// Завести `wl_buffer` поверх готовых dmabuf-дескрипторов.
///
/// `None` — композитор такое сочетание формата с модификатором не объявлял, и
/// создавать буфер НЕЛЬЗЯ: `create_immed` в этом случае отвечает не отказом, а
/// протокольной ошибкой, то есть мгновенно убивает клиента.
fn создать_dmabuf_буфер(
    state: &Config,
    описание: &hwvideo::ОписаниеПоверхности,
) -> Option<(WlBuffer, Занятость)> {
    let dmabuf = state.dmabuf.as_ref()?;
    let qh = state.qh.as_ref()?;

    if !state.dmabuf_форматы.contains(&(описание.fourcc, описание.модификатор)) {
        eprintln!(
            "plx-wall: композитор не объявил формат {:?} с модификатором {:#x}",
            std::str::from_utf8(&описание.fourcc.to_le_bytes()).unwrap_or("?").trim_end(),
            описание.модификатор,
        );
        return None;
    }

    let params = dmabuf.create_params(qh, ());
    let (hi, lo) = (
        (описание.модификатор >> 32) as u32,
        (описание.модификатор & 0xffff_ffff) as u32,
    );
    for (номер, плоскость) in описание.плоскости.iter().enumerate() {
        params.add(
            плоскость.fd.as_fd(),
            номер as u32,
            плоскость.сдвиг,
            плоскость.шаг,
            hi,
            lo,
        );
    }

    // create_immed, а не create: буфер нужен здесь и сейчас, а ждать ответа
    // композитора в главном цикле — это лишний круг диспетчеризации на каждую
    // новую поверхность. Сочетание формата с модификатором мы уже проверили
    // выше, так что протокольной ошибке взяться неоткуда.
    let занят: Занятость = std::sync::Arc::new(AtomicUsize::new(0));
    let буфер = params.create_immed(
        описание.ширина as i32,
        описание.высота as i32,
        описание.fourcc,
        zwp_linux_buffer_params_v1::Flags::empty(),
        qh,
        занят.clone(),
    );
    // Заготовка своё отработала: буфер от неё уже не зависит.
    params.destroy();

    Some((буфер, занят))
}

/// Сколько раз пробуем поднять умерший декодер, прежде чем сдаться.
const ПОПЫТОК_ПОДНЯТЬ: u32 = 5;

/// Поток декодера живых обоев кончился — записать это и назначить перезапуск.
///
/// **Почему это вообще функция, а не `state.hw = None`.** Именно так здесь и
/// было, в обеих ветках `Disconnected` (аппаратной и ffmpeg'овой), молча и
/// навсегда: канал закрылся — живые обои просто переставали существовать, на
/// экране оставался последний кадр, в логе не было ни строки. Снаружи это
/// выглядит как «обои иногда перестают быть анимированными», и починить это
/// «иногда» было нечем, потому что и жалоба, и причина оставались без следа.
///
/// Умереть поток может по-разному и не по нашей вине: битый кадр в середине
/// ролика, отвалившаяся поверхность VAAPI, драйвер, потерявший контекст после
/// долгой паузы. Все эти случаи лечатся одним и тем же — поднять декодер
/// заново с того же файла, чем ниже и занимается [`перезапустить_живые`].
///
/// Отсрочка растёт (1, 2, 4, 8, 16 с): если файл битый насовсем, мы не
/// перезапускаем ffmpeg по десять раз в секунду, а через [`ПОПЫТОК_ПОДНЯТЬ`]
/// попыток сдаёмся вовсе и говорим об этом прямо.
fn декодер_умер(state: &mut Config, откуда: &str) {
    state.hw = None;
    state.anim = None;
    if state.живые_путь.is_none() {
        return;
    }
    let попытка = state.живые_рестарт.map(|(_, n)| n).unwrap_or(0) + 1;
    if попытка > ПОПЫТОК_ПОДНЯТЬ {
        eprintln!(
            "plx-wall: декодер ({откуда}) умирает раз за разом — живые обои выключены, \
             на экране останется последний кадр",
        );
        state.живые_путь = None;
        state.живые_рестарт = None;
        return;
    }
    let отсрочка = std::time::Duration::from_secs(1u64 << (попытка - 1));
    eprintln!(
        "plx-wall: декодер ({откуда}) кончился — поднимаем заново через {:?} (попытка {попытка})",
        отсрочка,
    );
    state.живые_рестарт = Some((std::time::Instant::now() + отсрочка, попытка));
}

/// Сколько `wl_buffer` живых обоев держим на композиторе одновременно.
///
/// Пул поверхностей у декодера — единицы (`initial_pool_size = 8`), так что в
/// здоровом случае предел не срабатывает ни разу. Он про НЕздоровый.
///
/// Замер 24.08.2026 в живом сеансе: за 36 секунд показа живых обоев parallax набрал
/// **741 дескриптор dmabuf** (при мягком лимите процесса 1024) и 352 пары
/// буферов по 8 и 4.25 МиБ — то есть новый `wl_buffer` заводился на КАЖДЫЙ
/// кадр, а старый не уничтожался никогда: `hw_буферы` только росла. Кончалось
/// это дважды: у parallax падал `pactl` с «Too many open files», а у видеокарты
/// (8 ГБ, из них 2.4 держит dota2) кончалась память — `gbm_bo_create` начинал
/// возвращать EINVAL, ядро писало `Failed to allocate NVKMS memory for GEM
/// object`, и композитор переставал показывать кадры вовсе.
///
/// Причина найдена и вылечена по месту (флаш на обороте ролика, см.
/// hwvideo.rs), а предел остался страховкой: любой другой повод сменить номера
/// упрётся в него, а не в лимит дескрипторов композитора. Пул — 8 поверхностей,
/// так что 16 даёт запас ровно в одно поколение.
const ПРЕДЕЛ_HW_БУФЕРОВ: usize = 16;

/// Уничтожить устаревшие буферы, которые композитор наконец отпустил.
fn вынести_hw_мусор(state: &mut Config) {
    state.hw_мусор.retain(|(буфер, занят)| {
        if занят.load(Ordering::Relaxed) == 0 {
            буфер.destroy();
            false
        } else {
            true
        }
    });
}

/// Выбросить самые старые буферы живых обоев, если их накопилось больше предела.
///
/// Уничтожать можно только те, что композитор уже отпустил (`свободен`): буфер
/// на экране выдернуть — это рябь на обоях. Занятые уходят в конец очереди и
/// дождутся следующего раза.
///
/// Вычеркнуть номер надо И из общего с декодером списка `известные`, иначе
/// декодер решит, что главный цикл про поверхность знает, описание больше не
/// пришлёт — и кадры с этим номером молча перестанут показываться.
fn подрезать_hw_буферы(state: &mut Config) {
    let Some(hw) = state.hw.as_ref() else { return };
    let известные = hw.известные.clone();
    let mut попыток = state.hw_порядок.len();
    while state.hw_буферы.len() > ПРЕДЕЛ_HW_БУФЕРОВ && попыток > 0 {
        попыток -= 1;
        let Some(номер) = state.hw_порядок.pop_front() else { break };
        let свободен = match state.hw_буферы.get(&номер) {
            Some((_, занят)) => занят.load(Ordering::Relaxed) == 0,
            // Уже убрали другим путём — просто выкидываем из очереди.
            None => continue,
        };
        if !свободен {
            state.hw_порядок.push_back(номер);
            continue;
        }
        if let Some((буфер, _)) = state.hw_буферы.remove(&номер) {
            буфер.destroy();
        }
        if let Ok(mut с) = известные.lock() {
            с.remove(&номер);
        }
        // Один раз за жизнь процесса: сам факт срабатывания и означает, что
        // номера поверхностей текут (см. ПРЕДЕЛ_HW_БУФЕРОВ). Без этой строки
        // утечка снова стала бы видна только по чужим симптомам — замёрзшему
        // экрану и «Too many open files» в логе композитора.
        static РАЗ: std::sync::Once = std::sync::Once::new();
        РАЗ.call_once(|| {
            eprintln!("plx-wall: поверхности живых обоев не переиспользуются — \
                       держим не больше {} буферов", ПРЕДЕЛ_HW_БУФЕРОВ);
        });
    }
}

/// Поднять декодер живых обоев заново, тем же файлом.
///
/// Это НЕ смена обоев: ни палитры, ни плавного перехода, ни записи выбора в
/// конфиг здесь нет (всё это делает `start_load_wallpaper`, и повторять его на
/// каждой икоте драйвера значило бы пересчитывать палитру и мигать переходом
/// на ровном месте). Меняется ровно одно — вместо мёртвого потока появляется
/// живой, и кадры снова начинают приходить.
fn перезапустить_живые(state: &mut Config) {
    let Some(путь) = state.живые_путь.clone() else { return };
    let (w, h) = state.outputs.first().map(|(_, w, h)| (*w, *h)).unwrap_or((0, 0));
    if w == 0 || h == 0 {
        return;
    }
    // Буферы прошлых поверхностей уничтожаем явно: номера поверхностей у
    // нового декодера свои, и старые пары «буфер + флаг» никогда больше не
    // совпадут — без этого на композиторе оседал бы лишний пул на каждый
    // перезапуск (прокси wayland-client в Drop серверу не шлёт ничего).
    state.hw_на_экране.clear();
    for (буфер, _) in state.hw_буферы.values() {
        буфер.destroy();
    }
    state.hw_буферы.clear();
    state.hw_порядок.clear();
    for (буфер, _) in state.hw_мусор.drain(..) {
        буфер.destroy();
    }
    state.кадр_слота = None;

    if is_video(&путь) && state.dmabuf.is_some() {
        if let Some(hw) = hwvideo::запустить(&путь, hwvideo::УЗЕЛ_ПО_УМОЛЧАНИЮ) {
            state.hw = Some(hw);
            state.hw_срок = std::time::Instant::now();
            return;
        }
    }
    if is_video(&путь) || путь.to_lowercase().ends_with(".gif") {
        state.anim = start_anim(&путь, w, h);
    }
}

/// Показать очередной кадр аппаратных живых обоев.
///
/// Здесь нет ни единого касания пикселей: кадр приехал готовым буфером в
/// видеопамяти, и вся работа — прицепить его к поверхности.
fn показать_hw_кадр(state: &mut Config) {
    // Кадры, которые композитор снял с показа, отпускаем: пока держатель жив,
    // декодер не может забрать поверхность обратно в пул.
    state.hw_на_экране.retain(|(занят, _)| занят.load(Ordering::Relaxed) != 0);

    // Пока не подтверждён первый configure, attach запрещён протоколом. Ждём
    // хотя бы одну готовую поверхность — остальные подхватятся своим configure.
    if !state.фоны.iter().any(|ф| ф.configured) {
        return;
    }
    let сейчас = std::time::Instant::now();
    if сейчас < state.hw_срок {
        return;
    }

    // Забираем кадр. Первый кадр забран ещё при запуске декодера — там по нему
    // проверялось, что видеокарта вообще потянула этот кодек (см. hwvideo.rs),
    // и показать его надо прежде всего остального.
    let первый = state.hw.as_mut().and_then(|hw| hw.первый.take());
    let кадр = match первый {
        Some(кадр) => кадр,
        None => match state.hw.as_ref().map(|hw| hw.rx.try_recv()) {
            Some(Ok(кадр)) => кадр,
            Some(Err(std::sync::mpsc::TryRecvError::Empty)) => return,
            // Поток декодера кончился (битый файл, карта отказала на середине).
            // Не «живых обоев больше нет», а «поднимаем заново» — см. декодер_умер.
            Some(Err(std::sync::mpsc::TryRecvError::Disconnected)) => {
                декодер_умер(state, "видеокарта");
                return;
            }
            None => return,
        },
    };

    // Кадр приехал — значит декодер жив, и счётчик неудачных подъёмов можно
    // обнулить. Иначе пять икот драйвера за неделю сложились бы в «сдаёмся».
    state.живые_рестарт = None;

    // Срок следующего кадра отсчитываем от срока текущего, а не от «сейчас»:
    // иначе к каждому кадру прибавлялось бы опоздание главного цикла, и ролик
    // на 60 к/с полз бы медленнее реального времени. Отстали больше чем на
    // кадр — догонять нечем, начинаем отсчёт заново.
    state.hw_срок = if сейчас.duration_since(state.hw_срок) > кадр.шаг {
        сейчас + кадр.шаг
    } else {
        state.hw_срок + кадр.шаг
    };

    // Поверхность, которую видим впервые, — заводим под неё буфер. Дальше она
    // будет узнаваться по номеру, и протокольной работы не останется вовсе.
    if let Some(описание) = кадр.описание.as_ref() {
        match создать_dmabuf_буфер(state, описание) {
            Some(пара) => {
                // Описание на УЖЕ известный номер значит одно: пул поверхностей
                // пересобрался (оборот ролика — см. флаш в hwvideo.rs), и номер
                // достался другой поверхности. Прежний буфер показывает чужую
                // память, и жить ему ровно до release от композитора.
                if let Some(старый) = state.hw_буферы.insert(описание.surface_id, пара) {
                    state.hw_мусор.push(старый);
                } else {
                    state.hw_порядок.push_back(описание.surface_id);
                }
                вынести_hw_мусор(state);
                подрезать_hw_буферы(state);
            }
            None => {
                // Композитор такого не примет — уходим на путь через ffmpeg.
                eprintln!("plx-wall: dmabuf не принят композитором, откат на ffmpeg");
                state.hw = None;
                state.hw_на_экране.clear();
                let (w, h) = state.outputs.first().map(|(_, w, h)| (*w, *h)).unwrap_or((0, 0));
                let путь = state.wallpapers.get(state.current).cloned();
                if let (Some(путь), true) = (путь, w > 0 && h > 0) {
                    state.anim = start_anim(&путь, w, h);
                }
                return;
            }
        }
    }

    let Some((буфер, занят)) = state.hw_буферы.get(&кадр.surface_id) else { return };
    let (буфер, занят) = (буфер.clone(), занят.clone());

    // Размер кадра; раскладку по мониторам (тот же закон «заполнить») делает
    // `показать_на_фонах` — у каждого экрана свой viewport.
    let (кw, кh) = match state.hw.as_ref().map(|hw| hw.размер) {
        Some((кw, кh)) if кw > 0 && кh > 0 => (кw, кh),
        _ => return,
    };

    let отдано = показать_на_фонах(state, &буфер, кw, кh);
    if отдано == 0 {
        // Показать некому — кадр не ушёл, держатель не нужен: пусть декодер
        // забирает поверхность обратно в пул.
        return;
    }
    занят.store(отдано, Ordering::Relaxed);

    // Держим поверхность занятой, пока композитор не отпустит буфер со ВСЕХ
    // мониторов (счётчик дойдёт до нуля).
    state.hw_на_экране.push((занят, кадр.держатель));
}

/// Отдать декодеру видео свободные слоты общей памяти.
///
/// Он пишет кадр прямо в них (см. [`залить_кадр`]), поэтому слот можно
/// одалживать, только когда его отпустили ВСЕ мониторы (счётчик [`Занятость`]
/// дошёл до нуля) и когда он не показан прямо сейчас. Пока обои закрыты
/// полноэкранным окном, не одалживаем вовсе — декодер встаёт на `recv`, ffmpeg
/// упирается в трубу и засыпает.
///
/// Слоты заводятся здесь же, по размеру кадра из [`Anim::dims`]: декодеру они
/// нужны ДО первого кадра, а render_wallpaper узнаёт размер только из готового.
fn одолжить_слоты(state: &mut Config) {
    let Some((dw, dh)) = state.anim.as_ref().map(|a| a.dims) else { return };
    if dw == 0 || dh == 0 || !state.видно
        || !state.фоны.iter().any(|ф| ф.viewport.is_some())
    {
        // Без viewporter кадр надо ещё растянуть под экран, то есть через
        // буфер — тогда работает прежний путь с копированием.
        return;
    }
    if state.bg_dims != (dw, dh) || state.bg_slots.len() < 2 {
        let (Some(shm), Some(qh)) = (state.shm.as_ref(), state.qh.as_ref()) else { return };
        let Some(slots) = make_slots(shm, qh, dw, dh) else { return };
        state.bg_slots = slots;
        state.bg_dims = (dw, dh);
        state.bg_slot = 0;
        state.кадр_слота = None;
        state.scaled = None;
        state.слоты_у_декодера = vec![false; state.bg_slots.len()];
    }
    if state.слоты_у_декодера.len() != state.bg_slots.len() {
        state.слоты_у_декодера = vec![false; state.bg_slots.len()];
    }

    let показан = state.bg_slot;
    let есть_кадр = state.кадр_слота.map(|(i, _, _)| i);
    for i in 0..state.bg_slots.len() {
        if state.слоты_у_декодера[i] || Some(i) == есть_кадр {
            continue;
        }
        // Показанный слот держит композитор — он же убавит счётчик при release.
        if i == показан && state.bg_slots[i].занят.load(Ordering::Relaxed) != 0 {
            continue;
        }
        if state.bg_slots[i].занят.load(Ordering::Relaxed) != 0 {
            continue;
        }
        let Ok(fd) = state.bg_slots[i].fd.try_clone() else { continue };
        let Some(anim) = state.anim.as_ref() else { return };
        if anim.слоты.send(Заём { индекс: i, fd }).is_ok() {
            state.слоты_у_декодера[i] = true;
        }
    }
}

/// Снять то, что сейчас на экране, — с этого кадра пойдёт переход к новым
/// обоям.
///
/// Берём содержимое ПОКАЗАННОГО буфера, а не исходную картинку: во-первых, он
/// уже растянут под выход и переведён в BGRA (смешивать можно байт в байт),
/// во-вторых, у живых обоев исходного кадра как файла попросту не существует.
fn начать_переход(state: &mut Config) {
    let (w, h) = match state.outputs.first() {
        Some((_, w, h)) => (*w, *h),
        None => return,
    };
    // Первый запуск: буферов ещё нет, показывать переход не от чего.
    //
    // Раньше здесь стояла ещё и проверка bg_dims == (w, h). С viewporter она
    // отключала бы переход НАВСЕГДА: буфер теперь равен размеру кадра, а не
    // экрана, и совпадать с ним не обязан. Снимок берём какой есть и запоминаем
    // его размер — подгонит его render_wallpaper, один раз за переход.
    if w == 0 || h == 0 || state.bg_slots.is_empty() {
        state.fade = None;
        return;
    }
    let Some(slot) = state.bg_slots.get(state.bg_slot) else { return };
    let текущий = unsafe { std::slice::from_raw_parts(slot.ptr, slot.len) }.to_vec();
    state.fade = Some(Fade {
        from: текущий,
        dims: state.bg_dims,
        start: None,
        ждём: true,
    });
}

// ── Overlay rendering ────────────────────────────────────────────────────────

/// Готовит (один раз) постоянную пару буферов под меню и возвращает индекс
/// свободного. None — буферов нет или композитор ещё не отпустил ни один.
fn overlay_slot(state: &mut Config) -> Option<usize> {
    if state.ol_slots.len() < 2 {
        let (shm, qh) = (state.shm.as_ref()?, state.qh.as_ref()?);
        state.ol_slots = make_slots(shm, qh, ui_w(), ui_h())?;
        state.ol_slot = 0;
    }
    let next = take_free_slot(&state.ol_slots, state.ol_slot)?;
    state.ol_slot = next;
    Some(next)
}

/// Спрятать меню, НЕ размапливая поверхность.
///
/// Раньше здесь стоял `attach(None)` — по протоколу это размап, и после него
/// layer-поверхность возвращается в исходное состояние: следующий буфер
/// прикреплять нельзя, пока не придёт НОВЫЙ configure, а его никто не
/// запрашивал. Итог: меню открывалось ровно один раз, а на втором-третьем
/// круге вместе с ним пропадали и обои. Теперь рисуем полностью прозрачный
/// буфер того же размера и снимаем регион ввода, чтобы невидимое меню не
/// съедало клики по окнам под ним.
fn hide_overlay(state: &mut Config) -> bool {
    // До первого ack прикреплять буфер запрещено протоколом — за это
    // композитор убивает клиента («must ack the initial configure before
    // attaching buffer»), и plx-wall уходит в цикл перезапусков.
    //
    // Проверка стояла только в render_overlay, а сюда ведёт вторая дорога:
    // значок загрузки при ЗАКРЫТОМ меню (см. плашка_загрузки ниже). Пока
    // фоновая работа при старте была только у статичных обоев, поймать это
    // было почти нечем — картинка успевала загрузиться позже первого
    // configure. С живыми обоями окно стало шире: у них в фоне считается кадр
    // для плавного перехода, и спиннер зажигается в первые же миллисекунды,
    // ещё до ответа композитора.
    if !state.ol_configured { return false; }
    let Some(idx) = overlay_slot(state) else { return false };
    let Some(compositor) = state.compositor.clone() else { return false };
    let Some(qh) = state.qh.clone() else { return false };
    let Some(surface) = state.ol_surface.clone() else { return false };

    // Пустой регион ввода: клики проходят насквозь.
    let region = compositor.create_region(&qh, ());
    surface.set_input_region(Some(&region));
    region.destroy();

    // Меню спрятано, но загрузка идти может — тогда в пустом кадре остаётся
    // один значок. Иначе после Win+W на тяжёлых обоях (4K-PNG декодируется
    // сотни миллисекунд) экран просто ничего не отвечал: непонятно, поймало
    // нажатие или нет.
    let значок = state.спиннер_виден.then(|| плашка_загрузки(state.спиннер_фаза));

    let slot = &state.ol_slots[idx];
    match &значок {
        Some(pixels) => unsafe {
            let буфер = std::slice::from_raw_parts_mut(slot.ptr, slot.len);
            let сколько = pixels.len().min(буфер.len());
            буфер[..сколько].copy_from_slice(&pixels[..сколько]);
            буфер[сколько..].fill(0);
        },
        None => unsafe { std::slice::from_raw_parts_mut(slot.ptr, slot.len).fill(0) },
    }
    // Меню живёт ровно на одной поверхности — держатель у буфера один.
    slot.занят.store(1, Ordering::Relaxed);
    surface.attach(Some(&slot.buffer), 0, 0);
    surface.damage_buffer(0, 0, ui_w() as i32, ui_h() as i32);
    surface.commit();
    true
}

/// Рисует меню. `false` — не вышло (нет поверхности или оба буфера ещё у
/// композитора); тогда главный цикл оставляет пометку и повторит.
fn render_overlay(state: &mut Config) -> bool {
    if !state.ol_configured { return false; }
    if state.ol_surface.is_none() || state.shm.is_none()
        || state.qh.is_none() || state.compositor.is_none()
    {
        return false;
    }

    let buf_size = (ui_w() * ui_h() * 4) as usize;
    // Буфер ОДИН на всю жизнь программы. Раньше здесь стояло `vec![0u8;
    // buf_size]` — свежие 4.3 МБ на каждый кадр меню: ядро отдаёт их
    // страницами по требованию, и первый доступ к каждой из тысячи страниц
    // это отдельная ошибка страницы. Ровно отсюда и брались редкие кадры по
    // 18–24 мс среди трёхмиллисекундных.
    let mut pixels = std::mem::take(&mut state.меню_пиксели);
    if pixels.len() != buf_size {
        pixels = vec![0u8; buf_size];
    }

    // Подсветки: цель ставится тому, что под курсором, всё прочее гаснет.
    // Считаем ДО отрисовки, чтобы кадр и подсветка не расходились на кадр.
    обновить_подсветки(state);
    // И готовые миниатюры — тоже до, чтобы в самом кадре не осталось ничего
    // тяжелее укладки строк.
    let т_кэш = замер::пора();
    подготовить_кэш_карточек(state);
    замер::фаза("кэш карточек", т_кэш);

    // Насколько меню на месте. `мягко` убирает рывок на старте: сама
    // экспонента трогается резко, и меню будто выстреливало.
    let t = ui::мягко(state.открытие.значение());
    let mut холст = ui::Холст::новый(&mut pixels, ui_w(), ui_h());
    холст.сдвиг_y = ((1.0 - t) * ВЫЕЗД).round() as i32;
    // Общая альфа НЕ ставится холсту, и это правка про лаги на открытии.
    // Пока она стояла, всё меню рисовалось смешиванием: снимок стекла не
    // годился (0.4 мс превращались в 3.9), а непрозрачные карточки теряли
    // укладку строкой (2.7 → 4.4 мс). Итог — самый заметный кадр в жизни меню,
    // тот, что играет выезд, был и самым дорогим: 25 кадров по 10 мс на
    // настольной машине.
    //
    // Теперь холст всегда рисует в полную силу, а гасит кадр отдача
    // (`отдать_меню`) — она и так проходит по каждому пикселю, переставляя
    // каналы, и умножение на альфу ей почти ничего не стоит.
    let альфа_кадра = t;

    // ── Стекло ───────────────────────────────────────────────────────────────
    // Тень кладётся ПЕРВОЙ и снаружи формы: она отделяет меню от обоев там,
    // где яркость совпала, — без неё полупрозрачная полоса на светлых обоях
    // просто теряется.
    let верх = ui::Цвет::из_argb(ФОН_ВЕРХ);
    let низ = ui::Цвет::из_argb(ФОН_НИЗ);
    // Фон идёт ПЕРВЫМ и заменой: буфер только что обнулён, смешивать не с чем,
    // а это миллион пикселей на кадр. Тень кладётся следом — она рисуется
    // строго СНАРУЖИ формы и фон не задевает, так что порядок ей безразличен.
    let т_стекло = замер::пора();
    // Готовое стекло кладём одним копированием. Быстрый путь работает, только
    // когда меню стоит на месте и видно целиком: при выезде у холста свой
    // сдвиг и своя общая альфа, и снимок под них не подходит — тогда рисуем
    // как раньше. Выезд длится доли секунды, а «стоит на месте» — всё
    // остальное время, включая листание ленты и разгорание карточек.
    let стекло_готово = state
        .кэш_стекла
        .as_ref()
        .map(|(w, h, _)| *w == ui_w() && *h == ui_h())
        .unwrap_or(false);
    if стекло_готово {
        let (_, _, снимок) = state.кэш_стекла.as_ref().unwrap();
        let сдвиг = холст.сдвиг_y;
        if сдвиг == 0 {
            let сколько = снимок.len().min(холст.пиксели.len());
            холст.пиксели[..сколько].copy_from_slice(&снимок[..сколько]);
        } else {
            // Выезд: тот же снимок, только строками ниже. Верхние строки,
            // которым источника нет, обнуляем — там меню ещё не приехало.
            let ширина = ui_w() as usize * 4;
            let всего = ui_h() as usize;
            for строка in 0..всего {
                let из = строка as i32 - сдвиг;
                let d = строка * ширина;
                if из < 0 || из as usize >= всего {
                    холст.пиксели[d..d + ширина].fill(0);
                } else {
                    let s = из as usize * ширина;
                    холст.пиксели[d..d + ширина].copy_from_slice(&снимок[s..s + ширина]);
                }
            }
        }
    } else {
        // Буфер переиспользуется между кадрами, поэтому обнулить его теперь
        // обязаны сами: в прошлом кадре в нём осталось меню целиком, а этот
        // путь (выезд меню) закрашивает не всю площадь — за скруглением и под
        // тенью проступил бы прошлый кадр.
        холст.пиксели.fill(0);
        холст.замена = true;
        холст.скругл_с(0, 0, ui_w(), ui_h(), CORNER, |доля| верх.между(низ, доля));
        холст.замена = false;
        холст.тень(0, 4, ui_w(), ui_h().saturating_sub(4), CORNER, 18, ui::Цвет::из_argb(ТЕНЬ));
    }
    if !стекло_готово {
        холст.кант(0, 0, ui_w(), ui_h(), CORNER, 1.0, ui::Цвет::из_argb(КАНТ));
        // Блик по верхней кромке — от него стекло читается выпуклым.
        холст.скругл(CORNER as i32, 0, ui_w().saturating_sub(CORNER * 2), 1, 0,
                     ui::Цвет::из_argb(БЛИК));
        // Снимок делаем ровно в этот миг: в буфере лежит стекло и ничего
        // кроме него. Только с чистого кадра — при выезде в нём и сдвиг, и
        // приглушённая альфа, и такой снимок был бы негоден.
        if холст.сдвиг_y == 0 {
            state.кэш_стекла = Some((ui_w(), ui_h(), холст.пиксели.to_vec()));
        }
    }
    замер::фаза(if стекло_готово { "стекло-копия" } else { "стекло-заново" }, т_стекло);

    // ── Вкладки ──────────────────────────────────────────────────────────────
    // Полоска под выбранной вкладкой ЕДЕТ к новой, а не перескакивает: цель
    // ставится здесь, а движение считает главный цикл.
    let места = tab_rects();
    let выбранная = ВКЛАДКИ.iter().position(|в| *в == state.вкладка).unwrap_or(0);
    state.подчёркивание.к(места[выбранная].0 as f32);
    for (i, (tx, ty)) in места.iter().enumerate() {
        let выбрана = i == выбранная;
        let подсветка = state.подсветки.значение(ui::Что::Вкладка(i));
        кнопка_полосы(&mut холст, *tx, *ty, ARROW, выбрана, подсветка);
        let цвет = цвет_значка(выбрана, подсветка);
        draw_tab_icon(&mut холст, ВКЛАДКИ[i], *tx, *ty, цвет);
    }
    {
        // Одна полоска на все вкладки — та самая, что едет.
        let x = state.подчёркивание.значение().round() as i32;
        холст.скругл(x, (места[0].1 + ARROW + 3) as i32, ARROW, 2, 1,
                     ui::Цвет::из_argb(SEL_COLOR));
    }

    // Кнопка поиска. Когда запрос задан, она подсвечена — иначе непонятно,
    // почему в сетке не «лучшее», а что-то другое.
    {
        let (sx, sy) = search_rect();
        let ищем = !state.запрос.is_empty();
        let подсветка = state.подсветки.значение(ui::Что::Поиск);
        кнопка_полосы(&mut холст, sx, sy, ARROW, ищем, подсветка);
        draw_search_icon(&mut холст, sx, sy, цвет_значка(ищем, подсветка));
        if ищем {
            холст.скругл(sx as i32, (sy + ARROW + 3) as i32, ARROW, 2, 1,
                         ui::Цвет::из_argb(SEL_COLOR));
        }
    }

    // Кнопка фильтров — только на сетевых вкладках: свои обои сужать нечем.
    if state.вкладка != Вкладка::Мои {
        let (fx, fy) = filter_rect();
        let сужено = state.фильтры.заданы();
        let подсветка = state.подсветки.значение(ui::Что::Фильтр);
        кнопка_полосы(&mut холст, fx, fy, ARROW, сужено, подсветка);
        draw_filter_icon(&mut холст, fx, fy, цвет_значка(сужено, подсветка));
        if сужено {
            холст.скругл(fx as i32, (fy + ARROW + 3) as i32, ARROW, 2, 1,
                         ui::Цвет::из_argb(SEL_COLOR));
        }
    }

    // ── Ряд источников ───────────────────────────────────────────────────────
    if источники_видны(state.вкладка) {
        let подписи = подписи_источников(state.вкладка);
        for (i, (x, y, ш)) in источник_rects(state.вкладка).into_iter().enumerate() {
            let выбран = источник_выбран(state, i);
            let подсветка = state.подсветки.значение(ui::Что::Источник(i));
            let фон = ui::Цвет::из_argb(if выбран { HOVER_COLOR } else { PLUS_COLOR })
                .между(ui::Цвет::из_argb(HOVER_COLOR), подсветка);
            холст.скругл(x as i32, y as i32, ш, ARROW, ARROW / 2, фон);
            if выбран {
                холст.кант(x as i32, y as i32, ш, ARROW, ARROW / 2, 1.2,
                           ui::Цвет::из_argb(SEL_COLOR));
            }
            холст.текст_по_центру(
                x as i32, y as i32, ш, ARROW,
                подписи[i], КЕГЛЬ,
                if выбран { ui::Начертание::Полужирное } else { ui::Начертание::Обычное },
                цвет_значка(выбран, подсветка),
            );
        }
    }

    // Галочка «cycle» — бесконечные обои.
    {
        let (x, y, ш) = цикл_rect();
        let вкл = state.цикл;
        let подсветка = state.подсветки.значение(ui::Что::Цикл);
        let фон = ui::Цвет::из_argb(if вкл { HOVER_COLOR } else { PLUS_COLOR })
            .между(ui::Цвет::из_argb(HOVER_COLOR), подсветка);
        холст.скругл(x as i32, y as i32, ш, ARROW, ARROW / 2, фон);
        if вкл {
            холст.кант(x as i32, y as i32, ш, ARROW, ARROW / 2, 1.2,
                       ui::Цвет::из_argb(SEL_COLOR));
        }
        let цвет = цвет_значка(вкл, подсветка);
        let кx = (x + ПОЛЕ_ИСТОЧНИКА) as i32;
        let кy = (y + (ARROW - КВАДРАТ_ЦИКЛА) / 2) as i32;
        холст.кант(кx, кy, КВАДРАТ_ЦИКЛА, КВАДРАТ_ЦИКЛА, 3, 1.4, цвет);
        if вкл {
            холст.скругл(кx + 3, кy + 3, КВАДРАТ_ЦИКЛА - 6, КВАДРАТ_ЦИКЛА - 6, 2,
                         ui::Цвет::из_argb(SEL_COLOR));
        }
        let тx = x + ПОЛЕ_ИСТОЧНИКА + КВАДРАТ_ЦИКЛА + 7;
        холст.текст_по_центру(
            тx as i32, y as i32, ш - (тx - x) - ПОЛЕ_ИСТОЧНИКА, ARROW,
            ПОДПИСЬ_ЦИКЛА, КЕГЛЬ,
            if вкл { ui::Начертание::Полужирное } else { ui::Начертание::Обычное },
            цвет,
        );
    }

    // Значок загрузки — в ряду кнопок. Заводится и гаснет главным циклом
    // (см. спиннер_виден), здесь только рисуем.
    if state.спиннер_виден {
        let (sx, sy) = спиннер_место(state.вкладка);
        нарисовать_спиннер(&mut холст, sx, sy, ARROW, state.спиннер_фаза);
    }

    // Полоска состояния сети: серая — идёт запрос, красная — не вышло.
    if state.вкладка != Вкладка::Мои && (state.сетевая_работа || state.сетевая_ошибка) {
        let (x, y) = tab_rects()[0];
        let ширина = ui_w() - 2 * x;
        let цвет = if state.сетевая_ошибка { 0xFFBF5A5A } else { 0x80FFFFFF };
        холст.скругл(x as i32, (y + ARROW + 8) as i32, ширина, 2, 1,
                     ui::Цвет::из_argb(цвет));
    }

    // ── Карточки ─────────────────────────────────────────────────────────────
    let т_карточки = замер::пора();
    let сетевая = state.вкладка != Вкладка::Мои;
    let n = state.wallpapers.len();

    // Лента режется своим прямоугольником: при листании крайние карточки
    // наполовину за ним, и без обрезки они лезли бы на стрелки и за кромку
    // меню. Обрезку снимаем сразу после карточек — прокрутке и кнопкам она
    // не нужна.
    холст.обрезка = Some(лента_rect());
    // От дальних к ближним: передняя карточка обязана накрыть соседей, которые
    // под неё подныривают.
    let ячейки = ячейки_по_глубине(state);
    for карточка in ячейки {
        let Карточка { idx, x, y, даль, .. } = карточка;
        // Размер у каждой карточки свой (см. `Карточка`), и всё, что рисуется
        // поверх неё, обязано считаться от НЕГО, а не от полного размера
        // карточки: иначе кант, крестик и пелена уехали бы с места.
        let (кw, кh) = (карточка.w, карточка.h);
        let скругление = ((CORNER as f32 * масштаб_дали(даль)).round() as u32).max(4);
        let подсветка = state.подсветки.значение(ui::Что::Карта(idx));
        let свои = !сетевая && idx < n;
        let плюс = !сетевая && idx >= n;
        // Последняя карточка сетевой выдачи — «далее»: она не находка, а
        // просьба принести следующую страницу.
        let далее = сетевая && idx >= state.находки.len();
        // Качается ли эта карточка прямо сейчас — рисуем поверх неё пелену со
        // значком, чтобы было видно, по чему уже щёлкнули (загрузок может
        // идти несколько разом).
        let качается = сетевая && state.загрузки.iter().any(|з| з.карточка == idx);

        // Карточка чуть приподнимается под курсором. Двигать её целиком
        // нельзя — уехала бы мимо своей области нажатия; поэтому «подъём»
        // делает не сдвиг, а тень под ней и более светлый фон.
        //
        // Своя тень есть и у ПЕРЕДНЕЙ карточки, без всякого курсора: она и
        // отделяет её от тех, что подныривают под неё сзади. Гаснет с далью,
        // поэтому во время листания одна тень перетекает в другую.
        let передняя = (1.0 - даль).clamp(0.0, 1.0);
        let сила_тени = передняя.max(подсветка);
        if сила_тени > 0.01 {
            холст.тень(x, y + 3, кw, кh, скругление,
                       (14.0 * сила_тени) as u32,
                       ui::Цвет::из_argb(ТЕНЬ).с_прозрачностью(0.75 * сила_тени));
        }
        let основа = ui::Цвет::из_argb(if плюс || далее { PLUS_COLOR } else { CARD_COLOR });
        let фон = основа.между(ui::Цвет::из_argb(HOVER_COLOR), подсветка);
        // Подложку кладём ТОЛЬКО если сквозь неё что-то будет видно. Под
        // непрозрачной миниатюрой во всю карточку она невидима до последнего
        // пикселя — а стоила (замер) больше миллисекунды на кадр, столько же,
        // сколько все миниатюры вместе после кэша. Подсветка при этом не
        // теряется: её показывают кант и тень под карточкой.
        let подложка_видна = !state
            .кэш_карточек
            .готова_непрозрачной(сетевая, idx, свои || сетевая);
        if подложка_видна {
            холст.скругл(x, y, кw, кh, скругление, фон);
        }

        let миниатюра = if далее {
            None
        } else if сетевая {
            state.сетевые_миниатюры.get(idx)
        } else if свои {
            state.thumbnails.get(idx)
        } else {
            None
        };
        // Сначала — готовая миниатюра из кэша (быстрый путь, см. КэшКарточек).
        // Общий путь остаётся на случай, когда её ещё не посчитали: кадр не
        // должен ждать пересчёта, лучше нарисовать медленно, чем не нарисовать.
        let mut пелена_уже = false;
        let готовая = if далее {
            None
        } else if сетевая {
            state.кэш_карточек.сетевые.get(idx).and_then(|м| м.as_ref())
        } else if свои {
            state.кэш_карточек.свои.get(idx).and_then(|м| м.as_ref())
        } else {
            None
        };
        // Живая карточка кладёт вместо миниатюры свой нынешний кадр — тем же
        // путём, что и готовую, только со своим размером источника.
        let живой = state.превью.as_ref()
            .filter(|(ключ, _)| ключ.вкладка == state.вкладка && ключ.idx == idx)
            .and_then(|(_, п)| п.кадр.as_ref().map(|к| (к, п.размер)));
        let mut в_кэш: Option<Ужатая> = None;
        if let Some((кадр, (пw, пh))) = живой {
            // Ужатая из кэша тут не годится: картинка меняется каждый кадр.
            let пелена = пелена_глубины(даль);
            холст.картинка_готовая_масштаб(
                x, y, кw, кh, скругление, кадр, пw, пh, true, пелена,
            );
            пелена_уже = true;
        } else if let Some((готовая, непрозрачная)) = готовая {
            // Готовая карточка посчитана РАЗ и в полный размер, а на экран
            // ложится ужатой по своей дали. Ужимает её ближайшая точка (см.
            // `картинка_готовая_масштаб`): пересчитывать усреднением на каждом
            // кадре листания — это те самые миллисекунды, из-за которых лента
            // и лагала, а разницы на масштабе 0.6…1.0 не видно.
            let (пw, пh) = state.кэш_карточек.размер;
            let пелена = if *непрозрачная { пелена_глубины(даль) } else { 0.0 };
            // Лента стоит — размер карточки от кадра к кадру тот же, и ужимать
            // её заново незачем: кадры в это время идут от наведения, подсветки
            // и спиннеров, а картинка под ними прежняя. Берём ужатую из кэша и
            // кладём строками. Во время листания размер меняется каждый кадр,
            // кэш там только мешал бы — считаем напрямую.
            let ключ = Ужатая::ключ(сетевая, idx, кw, кh, пелена);
            let стоит = !state.лента.идёт() && (кw, кh) != (пw, пh) && *непрозрачная;
            if let Some(готово) = стоит.then(|| state.кэш_карточек.ужатая(&ключ)).flatten() {
                холст.картинка_готовая(x, y, кw, кh, скругление, &готово.пиксели, true);
            } else if стоит {
                let mut пиксели = vec![0u8; (кw * кh * 4) as usize];
                ui::Холст::новый(&mut пиксели, кw, кh).картинка_готовая_масштаб(
                    0, 0, кw, кh, 0, готовая, пw, пh, true, пелена,
                );
                холст.картинка_готовая(x, y, кw, кh, скругление, &пиксели, true);
                в_кэш = Some(Ужатая { ключ, пиксели });
            } else {
                холст.картинка_готовая_масштаб(
                    x, y, кw, кh, скругление, готовая, пw, пh, *непрозрачная, пелена,
                );
            }
            пелена_уже = *непрозрачная;
        } else if let Some(thumb) = миниатюра {
            // Готовая ещё считается в фоне (см. `подготовить_кэш_карточек`) —
            // кладём сырую миниатюру той же билинейной выборкой, что и
            // ужатые карточки. Прежний `draw_thumbnail` усреднял по площади
            // с замыканием на точку и в кадре листания стоил миллисекунды.
            let непрозрачная = миниатюра_непрозрачна(thumb);
            let пелена = if непрозрачная { пелена_глубины(даль) } else { 0.0 };
            холст.картинка_готовая_масштаб(
                x, y, кw, кh, скругление, &thumb.2, thumb.0, thumb.1, непрозрачная, пелена,
            );
            пелена_уже = непрозрачная;
        }
        if let Some(новая) = в_кэш {
            state.кэш_карточек.положить_ужатую(новая);
        }
        if плюс {
            // Плюс рисуется по МЕНЬШЕЙ стороне: он квадратный, а карточка нет,
            // и по ширине его перекладины разъехались бы за края.
            draw_plus(&mut холст, x + (кw - кh) as i32 / 2, y, кh,
                      ui::Цвет::из_argb(ТЕКСТ_ТИХО)
                          .между(ui::Цвет::из_argb(ТЕКСТ_ЯРКО), подсветка));
        }
        if далее {
            // Стрелка вправо — то же движение, что и листание ленты, только
            // это уже «принести ещё». Пока страница едет, вместо стрелки
            // крутится значок загрузки: иначе щелчок выглядел бы как ничего.
            let сторона = кh / 3;
            let цвет = ui::Цвет::из_argb(ТЕКСТ_ТИХО)
                .между(ui::Цвет::из_argb(ТЕКСТ_ЯРКО), подсветка);
            // Карточка при листании уезжает за левый край — её x отрицателен,
            // а рисовалки значков берут u32. Ушедшую целиком просто не рисуем:
            // от неё и так видна только полоска под обрезкой ленты.
            let знак_x = x + (кw as i32 - сторона as i32) / 2;
            let знак_y = (y + ((кh - сторона) / 2) as i32).max(0) as u32;
            if знак_x >= 0 {
                if state.сетевая_работа {
                    нарисовать_спиннер(&mut холст, знак_x as u32, знак_y, сторона, state.спиннер_фаза);
                } else {
                    draw_arrow_h(&mut холст, знак_x as u32, знак_y, сторона, true, цвет);
                }
            }
        }
        if качается {
            // Пелена приглушает саму картинку, значок поверх неё виден и на
            // светлых обоях.
            холст.скругл(x, y, кw, кh, скругление,
                         ui::Цвет::из_argb(ТЕНЬ).с_прозрачностью(0.45));
            let сторона = кh / 3;
            let знак_x = x + (кw as i32 - сторона as i32) / 2;
            let знак_y = (y + ((кh - сторона) / 2) as i32).max(0) as u32;
            if знак_x >= 0 {
                нарисовать_спиннер(&mut холст, знак_x as u32, знак_y,
                                   сторона, state.спиннер_фаза);
            }
        }

        // Нынешние обои обведены кантом во всю карточку, а не помечены точкой
        // в углу: на карточке 568×320 точка теряется, а кант виден с другого
        // конца ленты.
        // Пелена глубины — ПОСЛЕ картинки и ДО канта: дальняя карточка уходит
        // в тень, а кант нынешних обоев обязан остаться виден с любой глубины.
        // У непрозрачной готовой карточки пелена уже легла вместе с картинкой
        // (см. `пелена_глубины`) — второй проход по её точкам не нужен.
        if даль > 0.01 && !пелена_уже {
            let сила = (ГЛУБИНА_ТЕНЬ * даль).min(0.55);
            холст.скругл(x, y, кw, кh, скругление,
                         ui::Цвет::из_argb(ТЕНЬ).с_прозрачностью(сила));
        }

        if свои && idx == state.current {
            нарисовать_кант(&mut холст, x, y, кw, кh, ui::Цвет::из_argb(SEL_COLOR));
        } else if подсветка > 0.01 {
            нарисовать_кант(&mut холст, x, y, кw, кh,
                            ui::Цвет::из_argb(SEL_COLOR).с_прозрачностью(подсветка));
        }

        // Крестик удаления — только у своих обоев и только под курсором,
        // чтобы лента не пестрела крестиками. Проявляется вместе с подсветкой.
        if свои && подсветка > 0.01 {
            let dx = x + (кw - DEL_SIZE - 8) as i32;
            let dy = y + 8;
            let крестик = state.подсветки.значение(ui::Что::Крестик(idx));
            холст.скругл(dx, dy, DEL_SIZE, DEL_SIZE, DEL_SIZE / 2,
                         ui::Цвет::из_argb(DEL_BG)
                             .между(ui::Цвет::из_argb(0xE6C0392B), крестик)
                             .с_прозрачностью(подсветка));
            let было = холст.общая_альфа;
            холст.общая_альфа = было * подсветка;
            draw_cross(&mut холст, dx, dy, DEL_SIZE);
            холст.общая_альфа = было;
        }
    }
    холст.обрезка = None;
    замер::фаза("карточки", т_карточки);

    нарисовать_прокрутку(
        &mut холст,
        state.лента.значение(),
        &|что| state.подсветки.значение(что),
        предел_прокрутки(state),
        карточек(state),
    );

    // RGBA → BGRA сливается с отдачей: раньше это были ДВА прохода по всему
    // буферу меню (на 2560×420 — 4.3 МБ каждый), а он и так упирается в память.
    let т_отдача = замер::пора();
    let ушло = отдать_меню(state, &pixels, buf_size, альфа_кадра);
    замер::фаза("отдача", т_отдача);
    // Буфер возвращаем на место — на следующем кадре он будет тем же самым
    // (см. `меню_пиксели`).
    state.меню_пиксели = pixels;
    ушло
}

/// Фон кнопки в верхней полосе: выбранная светлее, наведённая — плавно между.
fn кнопка_полосы(холст: &mut ui::Холст, x: u32, y: u32, сторона: u32, выбрана: bool, подсветка: f32) {
    let основа = ui::Цвет::из_argb(if выбрана { HOVER_COLOR } else { CARD_COLOR });
    let фон = основа.между(ui::Цвет::из_argb(HOVER_COLOR), подсветка);
    холст.скругл(x as i32, y as i32, сторона, сторона, УГОЛ_КНОПКИ, фон);
    if выбрана {
        холст.кант(x as i32, y as i32, сторона, сторона, УГОЛ_КНОПКИ, 1.0,
                   ui::Цвет::из_argb(КАНТ));
    }
}

/// Цвет значка или подписи: у выбранного яркий, у прочего приглушённый, под
/// курсором — плавно между ними.
fn цвет_значка(выбран: bool, подсветка: f32) -> ui::Цвет {
    let тихо = ui::Цвет::из_argb(ТЕКСТ_ТИХО);
    let ярко = ui::Цвет::из_argb(ТЕКСТ_ЯРКО);
    if выбран { ярко } else { тихо.между(ярко, подсветка) }
}

/// Расставить цели подсветок по тому, где сейчас курсор.
///
/// Одним местом на всё меню: раньше наведение спрашивалось прямо в отрисовке
/// (`is_hover`) и было мгновенным — плавным его не сделать, не собрав все
/// элементы в одном списке.
fn обновить_подсветки(state: &mut Config) {
    let под_курсором = что_под_курсором(state);
    state.подсветки.погасить_кроме(под_курсором);
    if let Some(что) = под_курсором {
        state.подсветки.к(что, 1.0);
        // Карточка под крестиком светится вместе с ним: иначе, наведясь на
        // крестик, человек терял из виду, какую именно карточку удаляет.
        if let ui::Что::Крестик(i) = что {
            state.подсветки.к(ui::Что::Карта(i), 1.0);
        }
    }
}

/// Что именно сейчас под курсором. Порядок проверок тот же, что у попаданий
/// в [`build_ui_layout`]: сначала мелкое поверх, потом крупное под ним.
fn что_под_курсором(state: &Config) -> Option<ui::Что> {
    if !state.overlay_visible {
        return None;
    }
    let (cx, cy) = (state.cursor_x, state.cursor_y);
    if cx < 0.0 || cy < 0.0 {
        return None;
    }
    let (cx, cy) = (cx as u32, cy as u32);
    let внутри = |x: u32, y: u32, w: u32, h: u32| cx >= x && cx < x + w && cy >= y && cy < y + h;

    for (i, (tx, ty)) in tab_rects().iter().enumerate() {
        if внутри(*tx, *ty, ARROW, ARROW) {
            return Some(ui::Что::Вкладка(i));
        }
    }
    let (sx, sy) = search_rect();
    if внутри(sx, sy, ARROW, ARROW) {
        return Some(ui::Что::Поиск);
    }
    if state.вкладка != Вкладка::Мои {
        let (fx, fy) = filter_rect();
        if внутри(fx, fy, ARROW, ARROW) {
            return Some(ui::Что::Фильтр);
        }
    }
    if источники_видны(state.вкладка) {
        for (i, (x, y, ш)) in источник_rects(state.вкладка).into_iter().enumerate() {
            if внутри(x, y, ш, ARROW) {
                return Some(ui::Что::Источник(i));
            }
        }
    }
    {
        let (x, y, ш) = цикл_rect();
        if внутри(x, y, ш, ARROW) {
            return Some(ui::Что::Цикл);
        }
    }
    if предел_прокрутки(state) > 0 {
        let [(лx, лy), (пx, пy)] = arrow_rects();
        if внутри(лx, лy, ARROW, ARROW) {
            return Some(ui::Что::Стрелка(false));
        }
        if внутри(пx, пy, ARROW, ARROW) {
            return Some(ui::Что::Стрелка(true));
        }
    }
    // Карточки — по той же дробной позиции, по какой они нарисованы, и только
    // внутри прямоугольника ленты: половину уехавшей карточки видно не
    // полностью, и «наводиться» на её невидимую часть нельзя.

    let свои = state.вкладка == Вкладка::Мои;
    let n = state.wallpapers.len();
    let (лx, лy, лш, лв) = лента_rect();
    if (cx as i32) < лx || (cx as i32) >= лx + лш as i32
        || (cy as i32) < лy || (cy as i32) >= лy + лв as i32
    {
        return None;
    }
    let внутри_зн = |x: i32, y: i32, w: u32, h: u32| {
        (cx as i32) >= x && (cx as i32) < x + w as i32
            && (cy as i32) >= y && (cy as i32) < y + h as i32
    };
    // От ближних к дальним — тот же порядок, что и у областей нажатия: под
    // курсором подсвечивается то, по чему щелчок и попадёт.
    for к in ячейки_по_месту(state) {
        if свои
            && к.idx < n
            && внутри_зн(к.x + (к.w - DEL_SIZE - 8) as i32, к.y + 8, DEL_SIZE, DEL_SIZE)
        {
            return Some(ui::Что::Крестик(к.idx));
        }
        if внутри_зн(к.x, к.y, к.w, к.h) {
            return Some(ui::Что::Карта(к.idx));
        }
    }
    None
}

/// Полоса прокрутки и стрелки. Рисуются одинаково на всех вкладках, поэтому
/// живут отдельно: раньше эта арифметика была вписана прямо в render_overlay,
/// и сетевой сетке пришлось бы её дублировать.
fn нарисовать_прокрутку(
    холст: &mut ui::Холст,
    // Дробная позиция ленты — та же, по которой нарисованы карточки. Целое
    // значение показывало бы бегунок скачками, пока лента едет плавно.
    scroll: f32,
    // Подсветка отдельным замыканием, а не через `&Config`: так эту же
    // отрисовку зовёт снимок ленты из тестов, у которого никакого Config нет.
    подсветка: &dyn Fn(ui::Что) -> f32,
    макс: u32,
    всего_карточек: usize,
) {
    // Стрелки рисуем ВСЕГДА, даже когда листать некуда: у ленты они стоят по
    // краям карточек и держат её форму. Погашенная стрелка честно показывает,
    // что дальше ничего нет, — исчезнувшая просто оставляет дыру.
    let [(лев_x, лев_y), (прав_x, прав_y)] = arrow_rects();
    for (ax, ay, вправо, доступна) in [
        (лев_x, лев_y, false, scroll > 0.01),
        (прав_x, прав_y, true, scroll < макс as f32 - 0.01),
    ] {
        let п = подсветка(ui::Что::Стрелка(вправо));
        let фон = ui::Цвет::из_argb(CARD_COLOR).между(ui::Цвет::из_argb(HOVER_COLOR), п);
        холст.скругл(ax as i32, ay as i32, ARROW, ARROW, ARROW / 2, фон);
        // Недоступная стрелка гасится не другим цветом, а прозрачностью: так
        // она заведомо тише всего, что рядом, при любой яркости обоев.
        let цвет = ui::Цвет::из_argb(ТЕКСТ_ЯРКО)
            .с_прозрачностью(if доступна { 1.0 } else { 0.32 });
        draw_arrow_h(холст, ax, ay, ARROW, вправо, цвет);
    }

    if макс == 0 { return; }

    // Полоса прокрутки — ПОД лентой и во всю её ширину: лента листается вбок,
    // и вертикальная полоса у правого поля показывала бы движение поперёк
    // того, которое видно.
    let ширина_ленты = видно_карт() * карта_w() + (видно_карт() - 1) * GAP;
    let track_x = лента_x() as i32;
    let track_y = (лента_y() + карта_h() + GAP + 6) as i32;
    холст.скругл(track_x, track_y, ширина_ленты, SB_W, SB_W / 2,
                 ui::Цвет::из_argb(SB_COLOR));

    // Бегунок: доля видимой части от всей ленты.
    let всего = рядов(всего_карточек).max(1);
    let ширина = (ширина_ленты * видно_карт() / всего).max(32).min(ширина_ленты);
    let свободно = ширина_ленты - ширина;
    let смещение = (свободно as f32 * scroll / макс as f32).round().max(0.0) as u32;
    холст.скругл(track_x + смещение as i32, track_y, ширина, SB_W, SB_W / 2,
                 ui::Цвет::из_argb(SB_THUMB_COLOR));
}

/// Треугольник стрелки, смотрящий влево или вправо. Та же арифметика, что у
/// `draw_arrow`, только оси переставлены: у ленты листают вбок.
fn draw_arrow_h(холст: &mut ui::Холст, x: u32, y: u32, size: u32, вправо: bool, цвет: ui::Цвет) {
    let половина = size / 2;
    for col in 0..половина {
        let высота = (половина - col) * 2;
        if высота == 0 { continue; }
        let cx = if вправо { x + size / 4 + col } else { x + size - size / 4 - col };
        let cy = y + size / 2 - высота / 2;
        холст.скругл(cx as i32, cy as i32, 1, высота, 0, цвет);
    }
}

/// Отдать готовый кадр меню композитору. `false` — оба буфера ещё заняты,
/// главный цикл повторит.
fn отдать_меню(state: &mut Config, pixels: &[u8], buf_size: usize, альфа: f32) -> bool {
    let Some(idx) = overlay_slot(state) else { return false };
    let Some(compositor) = state.compositor.clone() else { return false };
    let Some(qh) = state.qh.clone() else { return false };
    let Some(surface) = state.ol_surface.clone() else { return false };

    let slot = &state.ol_slots[idx];
    // Копирование и перестановка каналов ОДНИМ проходом: холст рисует в RGBA,
    // композитору нужен BGRA, и раньше буфер обходили дважды — сперва меняли
    // байты на месте, потом копировали в слот. На 4.3 МБ это лишний проход по
    // памяти на каждый кадр меню.
    let слот = unsafe { std::slice::from_raw_parts_mut(slot.ptr, slot.len) };
    //
    // Проход разбит на куски по 64 КБ и идёт в несколько потоков (27.09.2026):
    // точки независимы, а на 2432×444 это 4.3 МБ на кадр — при кадре монитора
    // в 5 мс один поток тратил на одну перестановку треть бюджета. Точка
    // берётся словом: R и B меняются местами сдвигами, G и A остаются.
    use rayon::prelude::*;
    const КУСОК: usize = 64 * 1024;
    let k = (альфа.clamp(0.0, 1.0) * 255.0) as u32;
    let целиком = альфа >= 0.999;
    слот[..buf_size]
        .par_chunks_mut(КУСОК)
        .zip(pixels[..buf_size].par_chunks(КУСОК))
        .for_each(|(куда, откуда)| {
            for (к, из) in куда.chunks_exact_mut(4).zip(откуда.chunks_exact(4)) {
                let т = u32::from_le_bytes([из[0], из[1], из[2], из[3]]);
                let bgra = (т & 0xFF00_FF00) | ((т >> 16) & 0xFF) | ((т & 0xFF) << 16);
                let bgra = if целиком {
                    bgra
                } else {
                    // Гашение всего кадра — здесь, а не в холсте (см.
                    // `альфа_кадра`). Цвет ПРЕДумножен, поэтому множатся все
                    // четыре канала, включая альфу.
                    let rb = ((bgra & 0x00FF_00FF) * k >> 8) & 0x00FF_00FF;
                    let ga = (((bgra >> 8) & 0x00FF_00FF) * k >> 8) & 0x00FF_00FF;
                    rb | (ga << 8)
                };
                к.copy_from_slice(&bgra.to_le_bytes());
            }
        });
    // Регион ввода — на всю площадь, пока меню открыто. Пока оно ЗАКРЫВАЕТСЯ
    // (флаг уже снят, картинка ещё уезжает), регион пустой: иначе те две
    // десятых секунды, что доигрывается анимация, клики уходили бы в
    // невидимое меню вместо окна под ним.
    let region = compositor.create_region(&qh, ());
    if state.overlay_visible {
        region.add(0, 0, ui_w() as i32, ui_h() as i32);
    }
    surface.set_input_region(Some(&region));
    region.destroy();
    // Меню живёт ровно на одной поверхности — держатель у буфера один.
    slot.занят.store(1, Ordering::Relaxed);
    surface.attach(Some(&slot.buffer), 0, 0);
    surface.damage_buffer(0, 0, ui_w() as i32, ui_h() as i32);
    surface.commit();
    true
}

// ── UI helpers ───────────────────────────────────────────────────────────────

/// Какая карточка под курсором (индекс из ui_cells; len() — это «+»).
fn hover_cell(state: &Config) -> Option<usize> {
    if state.cursor_x < 0.0 || state.cursor_y < 0.0 { return None; }
    let cx = state.cursor_x as u32;
    let cy = state.cursor_y as u32;
    let (кw, кh) = (карта_w(), карта_h());
    сетка(карточек(state), state.scroll_row).into_iter()
        .find(|&(_, x, y)| cx >= x && cx < x + кw && cy >= y && cy < y + кh)
        .map(|(idx, _, _)| idx)
}

/// Спросить, что искать.
///
/// Своего поля ввода у plx-wall нет и быть не может: шрифта в нём тоже нет, всё
/// меню рисуется прямоугольниками. Поэтому текст спрашиваем у rofi — он же
/// лаунчер приложений. Пустой список (`-l 0`) превращает его в поле свободного
/// ввода: Enter печатает то, что набрали. Слой у rofi всегда overlay, то есть
/// поверх меню plx-wall, — отдельно просить не надо.
///
/// `None` — передумали (Esc): прежний запрос остаётся. `Some("")` — стёрли
/// строку и нажали Enter: это значит «показывай снова лучшее».
fn спросить_запрос(текущий: &str) -> Option<String> {
    let bin = which("rofi")?;
    let out = std::process::Command::new(bin)
        .args([
            "-dmenu",
            "-p", "Поиск обоев",
            "-l", "0",
            "-theme-str", "window { width: 480px; }",
            // Начинаем с прежнего запроса — его чаще правят, чем набирают
            // заново.
            "-filter", текущий,
        ])
        .stdin(std::process::Stdio::null())
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    Some(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

/// Показать список и вернуть НОМЕР выбранной строки.
///
/// Тот же rofi, что и для поиска, только теперь в обычном своём качестве —
/// выбором из списка. Номер, а не текст: подписи содержат галочку действующего
/// значения и совпадать между собой могут как угодно, а состояние фильтров
/// вызывающий держит рядом со списком (см. [`online::меню_фильтров`]).
/// `-format i` отдаёт номер сразу; набранное мимо списка приходит как -1.
fn спросить_из_списка(подпись: &str, строки: &[String]) -> Option<usize> {
    let bin = which("rofi")?;
    let mut дитя = std::process::Command::new(bin)
        .args(["-dmenu", "-p", подпись.trim_end_matches([' ', ':']), "-format", "i", "-no-custom",
               "-theme-str", "window { width: 440px; }"])
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .spawn()
        .ok()?;
    {
        use std::io::Write;
        let mut вход = дитя.stdin.take()?;
        // Ошибку записи глотаем намеренно: rofi мог закрыться сразу (Esc), и
        // тогда труба рвётся — это не беда, а обычный отказ от выбора.
        let _ = вход.write_all(строки.join("\n").as_bytes());
    }
    let out = дитя.wait_with_output().ok()?;
    if !out.status.success() {
        return None;
    }
    String::from_utf8_lossy(&out.stdout).trim().parse::<usize>().ok().filter(|&i| i < строки.len())
}

/// Каталог, куда складываются скачанные обои.
fn каталог_загрузок() -> std::path::PathBuf {
    std::path::PathBuf::from(format!("{}/.config/plx-wall/downloaded", home()))
}

/// Переключить вкладку сетки.
fn открыть_вкладку(state: &mut Config, вкладка: Вкладка) {
    if state.вкладка == вкладка { return; }
    state.вкладка = вкладка;
    state.scroll_row = 0;
    // Лента встаёт в начало СРАЗУ: у новой вкладки свои карточки, и проезд
    // «оттуда, где стояла прошлая» был бы движением сквозь чужой список.
    state.лента.сразу(0.0);
    state.hover = None;
    state.сетевая_ошибка = false;

    // Выдачу для вкладки грузим один раз за сеанс: повторный заход не должен
    // снова ждать сеть. Обновить — вернуться на «свои» и открыть заново.
    if вкладка != Вкладка::Мои && state.находки.is_empty() && !state.сетевая_работа {
        загрузить_страницу(state, 1, false);
    }

    build_ui_layout(state);
    state.dirty = true;
}

/// Сменить источник обоев (кнопка в ряду [`ИСТОЧНИКИ`]).
///
/// Выдача перезапрашивается СРАЗУ и с первой страницы: старый список к новому
/// источнику отношения не имеет, а оставить его на экране значило бы показать
/// картинки одного сайта под подписью другого.
fn сменить_источник(state: &mut Config, i: usize) {
    let сменилось = match state.вкладка {
        Вкладка::Живые => {
            let Some((новый, _)) = ИСТОЧНИКИ_ЖИВЫХ.get(i).copied() else { return };
            let было = std::mem::replace(&mut state.фильтры.живой, новый);
            было != новый
        }
        Вкладка::Мои => return,
        Вкладка::Картинки => {
            let Some((новый, _)) = ИСТОЧНИКИ_КАРТИНОК.get(i).copied() else { return };
            let было = std::mem::replace(&mut state.фильтры.провайдер, новый);
            было != новый
        }
    };
    if !сменилось {
        return;
    }
    state.scroll_row = 0;
    state.лента.сразу(0.0);
    state.hover = None;
    state.сетевая_ошибка = false;
    state.находки.clear();
    state.сетевые_миниатюры.clear();
    state.кэш_карточек.сбросить();
    загрузить_страницу(state, 1, false);
    build_ui_layout(state);
    state.dirty = true;
}

/// Запросить страницу выдачи в фоновом потоке.
///
/// `дополнить` — приклеить к уже показанному (так работает подгрузка при
/// прокрутке вниз), иначе список заменяется целиком.
fn загрузить_страницу(state: &mut Config, страница: u32, дополнить: bool) {
    let Some(источник) = state.вкладка.источник() else { return };
    if state.сетевая_работа { return; }

    let (w, h) = state.outputs.first().map(|(_, w, h)| (*w, *h)).unwrap_or((1920, 1080));
    let (tx, rx) = std::sync::mpsc::channel();
    state.pending_online = Some(rx);
    state.сетевая_работа = true;
    state.сетевая_ошибка = false;
    state.сетевая_страница = страница;
    if !дополнить {
        state.находки.clear();
        state.кэш_карточек.сбросить();
        state.сетевые_миниатюры.clear();
    state.кэш_карточек.сбросить();
    }
    state.dirty = true;

    let запрос = state.запрос.clone();
    let фильтры = state.фильтры.clone();
    std::thread::spawn(move || {
        let ответ = match online::список(источник, страница, w, h, &запрос, &фильтры) {
            Err(e) => ИзСети::Ошибка(e),
            Ok(находки) => {
                // Миниатюры качаем и разбираем здесь же: главный цикл получит
                // всё готовым и ни разу не остановится ни на сети, ни на
                // декодировании.
                let мини = миниатюры_разом(&находки);
                let (находки, мини) = отобрать_по_цвету(находки, мини, фильтры.цвет);
                ИзСети::Список(находки, мини)
            }
        };
        let _ = tx.send(ответ);
    });
}

/// Оставить только те находки, чья миниатюра подходит под выбранный цвет.
///
/// Отбор именно здесь, а не в [`online`]: ни Openverse, ни moewalls цвета не
/// знают, зато миниатюры к этому месту уже скачаны и разобраны — считать по ним
/// цвет ничего не стоит, а второй раз ходить в сеть не нужно.
///
/// Страница после отбора становится короче — это нормально: докрутив сетку до
/// низа, plx-wall подтянет следующую (см. `прокрутить`), и так до тех пор, пока
/// подходящих не наберётся на экран.
fn отобрать_по_цвету(
    находки: Vec<online::Находка>,
    мини: Vec<(u32, u32, Vec<u8>)>,
    цвет: Option<palette::Цвет>,
) -> (Vec<online::Находка>, Vec<(u32, u32, Vec<u8>)>) {
    let Some(цвет) = цвет else { return (находки, мини) };
    находки
        .into_iter()
        .zip(мини)
        .filter(|(_, (_, _, px))| palette::подходит_по_цвету(px, цвет))
        .unzip()
}

/// Разобрать ответ сети. `карточка` — та, чья загрузка кончилась (у списка её
/// нет).
///
/// Скачанное ВСЕГДА попадает в «Мои»: за этим человек и щёлкал. А вот на экран
/// встают только те обои, по которым щёлкнули последними (см.
/// `поставить_карточку`) — иначе три загрузки, кончившись вразнобой, трижды
/// сменили бы обои, и последнее слово осталось бы за тем, у кого файл мельче.
fn принять_из_сети(config: &mut Config, ответ: ИзСети, карточка: Option<usize>) {
    match ответ {
        ИзСети::Список(находки, мини) => {
            // Страница ДОПИСЫВАЕТСЯ: готовые карточки остаются на своих местах,
            // и сбрасывать их кэш незачем (первую страницу вызывающий и так
            // начинает с чистого, см. загрузить_страницу).
            config.находки.extend(находки);
            config.сетевые_миниатюры.extend(мини);
        }
        ИзСети::Скачано(путь) => {
            let путь = путь.to_string_lossy().to_string();
            if !config.wallpapers.contains(&путь) {
                config.wallpapers.push(путь.clone());
                save_config(&config.wallpapers);
                // Новые обои дописаны в конец: старые карточки на своих
                // местах, а миниатюра считается только у новой (см.
                // load_thumbnails) — кэш ужатых трогать незачем.
            }
            let ставим = карточка.is_none() || карточка == config.поставить_карточку;
            if ставим {
                config.поставить_карточку = None;
                config.current =
                    config.wallpapers.iter().position(|p| p == &путь).unwrap_or(0);
                start_load_wallpaper(config, путь);
                // Возвращаемся к своим обоям: новые уже там, и видно, что они
                // встали.
                config.вкладка = Вкладка::Мои;
                config.scroll_row = 0;
            }
            load_thumbnails(config);
        }
        ИзСети::Ошибка(e) => {
            eprintln!("plx-wall: сеть — {e}");
            config.сетевая_ошибка = true;
        }
    }
    build_ui_layout(config);
    config.dirty = true;
}

/// Скачать выбранные в сети обои и сразу их поставить.
fn взять_из_сети(state: &mut Config, idx: usize) {
    let Some(находка) = state.находки.get(idx).cloned() else { return };
    // Второй щелчок по ТОЙ ЖЕ карточке — не вторая загрузка: файл один, и
    // качать его дважды значит только зря занять канал.
    if state.загрузки.iter().any(|з| з.карточка == idx) {
        return;
    }

    let (tx, rx) = std::sync::mpsc::channel();
    state.загрузки.push(Загрузка { rx, карточка: idx });
    // Какие обои ПОСТАВИТЬ, когда докачаются: последние, по которым щёлкнули.
    // Остальные просто лягут в «Мои» — иначе несколько загрузок, кончившись,
    // дрались бы за экран, и обои менялись бы сами по себе.
    state.поставить_карточку = Some(idx);
    state.сетевая_ошибка = false;
    state.dirty = true;

    std::thread::spawn(move || {
        let ответ = match online::скачать(&находка, &каталог_загрузок()) {
            Ok(путь) => ИзСети::Скачано(путь),
            Err(e) => ИзСети::Ошибка(e),
        };
        let _ = tx.send(ответ);
    });
}

/// Привести миниатюру к размеру карточки — тем же усреднением, что делала
/// отрисовка, но ОДИН раз, а не каждый кадр.
fn под_карточку(thumb: &(u32, u32, Vec<u8>), dw: u32, dh: u32) -> (Vec<u8>, bool) {
    let (tw, th, data) = thumb;
    let (tw, th) = (*tw, *th);
    if tw == 0 || th == 0 || dw == 0 || dh == 0 {
        return (vec![0u8; (dw as usize) * (dh as usize) * 4], false);
    }
    // Ланцош, а не усреднение по площади. Прежнее усреднение вырождалось в
    // ближайшую точку ровно на том отношении, которое здесь и бывает: миниатюра
    // 640×360, карточка 604×340 — на каждую точку назначения приходится одна
    // точка исходника, а каждая семнадцатая строка и каждый семнадцатый столбец
    // просто выбрасываются. Считается это ОДИН раз на размер карточки (см.
    // `подготовить_кэш_карточек`), так что дорогой фильтр здесь по карману —
    // а платит за него уже не кадр.
    let out = resize(tw, th, data, dw, dh);
    // Признак считаем ЗДЕСЬ, один раз на карточку: в кадре тот же ответ стоил
    // бы прохода по всем её точкам.
    let непрозрачная = out.iter().skip(3).step_by(4).all(|a| *a == 255);
    (out, непрозрачная)
}

/// Досчитать кэш для карточек, которые сейчас видны.
///
/// Считаем только видимые: страница выдачи это два десятка находок, а в ленте
/// их разом три-четыре — готовить остальные значило бы тратить и время, и
/// память на то, чего никто не увидит.
fn подготовить_кэш_карточек(state: &mut Config) {
    let размер = (карта_w(), карта_h());
    if state.кэш_карточек.размер != размер {
        state.кэш_карточек.размер = размер;
        state.кэш_карточек.сбросить();
    }
    принять_карточки(state);
    let сетевая = state.вкладка != Вкладка::Мои;
    let сколько = if сетевая { state.находки.len() } else { state.wallpapers.len() };
    // Видимые — первыми, следом соседи на ширину ленты в обе стороны: пока
    // лента едет к цели, они уже готовы. Сама цель листания (scroll_row) тоже
    // в окне — карточки, к которым едем, важнее тех, мимо которых.
    let видно = видно_карт() as i64;
    let сейчас = state.лента.значение().floor() as i64;
    let цель = state.scroll_row as i64;
    let mut ячейки: Vec<usize> = ячейки_сейчас(state).into_iter().map(|к| к.idx).collect();
    for idx in (сейчас.min(цель) - видно)..(сейчас.max(цель) + 2 * видно) {
        if idx >= 0 {
            ячейки.push(idx as usize);
        }
    }
    ячейки.retain(|idx| *idx < сколько);

    let кк = &mut state.кэш_карточек;
    let кэш = if сетевая { &mut кк.сетевые } else { &mut кк.свои };
    let источник: &Vec<(u32, u32, Vec<u8>)> =
        if сетевая { &state.сетевые_миниатюры } else { &state.thumbnails };
    // Длина кэша идёт за длиной списка. Растёт она ДОПИСЫВАНИЕМ (следующая
    // страница выдачи, скачанные обои) — уже готовые карточки при этом свои
    // места не меняют, и выбрасывать их незачем. Удаление сдвигает номера, но
    // его вызывающий и так сопровождает полным сбросом.
    if кэш.len() > источник.len() {
        кэш.truncate(источник.len());
    }
    кэш.resize_with(источник.len(), || None);
    // Далеко уехавшие карточки отпускаем: каждая — 0.8 МБ, и пролистанный
    // до конца список в три сотни обоев держал бы их все. Окно шире
    // заказываемого, чтобы ленту, качнувшуюся туда-обратно, не пересчитывать.
    let (дальше_от, дальше_до) = (сейчас.min(цель) - 3 * видно, сейчас.max(цель) + 4 * видно);
    for (idx, место) in кэш.iter_mut().enumerate() {
        if место.is_some() && ((idx as i64) < дальше_от || (idx as i64) > дальше_до) {
            *место = None;
        }
    }
    let tx = кк.канал.get_or_insert_with(std::sync::mpsc::channel).0.clone();
    for idx in ячейки {
        let Some(thumb) = источник.get(idx) else { continue };
        if кэш.get(idx).map(|м| м.is_some()).unwrap_or(true) {
            continue;
        }
        if кк.в_работе.contains_key(&(сетевая, idx)) {
            continue;
        }
        let задание = кк.след_задание;
        кк.след_задание += 1;
        кк.в_работе.insert((сетевая, idx), задание);
        // Копия миниатюры (0.9 МБ) дешевле, чем делить её между потоками:
        // список миниатюр живёт в главном цикле и меняется на ходу.
        let thumb = thumb.clone();
        let tx = tx.clone();
        пул_карточек().spawn(move || {
            let готовая = под_карточку(&thumb, размер.0, размер.1);
            let _ = tx.send(ГотоваяКарточка { сетевая, idx, задание, размер, готовая });
        });
    }
}

/// Свой пул для фонового ужатия карточек. Не общий rayon: в общем пуле по
/// строкам режется сам кадр меню (`картинка_готовая_масштаб`), и Ланцош,
/// вставший перед ним в очередь, задерживал бы ровно тот кадр, ради которого
/// его увели из кадра. Три потока — на ноуте их четыре на всё.
fn пул_карточек() -> &'static rayon::ThreadPool {
    static ПУЛ: std::sync::OnceLock<rayon::ThreadPool> = std::sync::OnceLock::new();
    ПУЛ.get_or_init(|| {
        rayon::ThreadPoolBuilder::new()
            .num_threads(3)
            .thread_name(|i| format!("plx-wall-card-{i}"))
            .start_handler(|_| понизить_приоритет_потока())
            .build()
            .expect("пул карточек")
    })
}

/// Понизить приоритет ТЕКУЩЕГО потока. В Linux setpriority с номером потока
/// действует на один поток, а не на весь процесс — главный цикл не задевается.
fn понизить_приоритет_потока() {
    unsafe {
        let tid = libc::syscall(libc::SYS_gettid) as libc::id_t;
        libc::setpriority(libc::PRIO_PROCESS, tid, 10);
    }
}

/// Забрать карточки, досчитанные фоном (см. [`ГотоваяКарточка`]).
///
/// `true` — пришло хоть что-то, кадр меню стоит перерисовать.
fn принять_карточки(state: &mut Config) -> bool {
    let кк = &mut state.кэш_карточек;
    let Some((_, rx)) = кк.канал.as_ref() else { return false };
    let mut пришло = false;
    while let Ok(г) = rx.try_recv() {
        // Задание отменено (миниатюра сменилась, кэш сброшен) или карточка
        // стала другого размера — результат негоден.
        if кк.в_работе.get(&(г.сетевая, г.idx)) != Some(&г.задание) || г.размер != кк.размер {
            continue;
        }
        кк.в_работе.remove(&(г.сетевая, г.idx));
        let ряд = if г.сетевая { &mut кк.сетевые } else { &mut кк.свои };
        if let Some(место) = ряд.get_mut(г.idx) {
            *место = Some(г.готовая);
            пришло = true;
        }
    }
    пришло
}

/// Непрозрачна ли миниатюра — по выборке точек, а не по каждой: решение нужно
/// в каждом кадре, пока готовой карточки нет, и проход по 230 тысячам точек
/// ради него был бы дороже самого рисования.
fn миниатюра_непрозрачна(thumb: &(u32, u32, Vec<u8>)) -> bool {
    thumb.2.iter().skip(3).step_by(4 * 61).all(|a| *a == 255)
}

/// Сколько миниатюр качать одновременно.
///
/// Потоки здесь почти всё время СПЯТ на сети, поэтому число взято не по ядрам:
/// на слабой машине восемь ждущих потоков стоят столько же, сколько один.
/// Больше брать незачем — страница выдачи это 20–24 карточки, и на восьми
/// потоках она приходит за три захода; а хосты вроде commons.wikimedia на
/// два десятка одновременных запросов отвечают уже хуже, чем на восемь.
const МИНИАТЮР_РАЗОМ: usize = 8;

/// Скачать и разобрать миниатюры всей страницы — параллельно.
///
/// Раньше здесь был обычный `map`: двадцать четыре картинки качались ОДНА ЗА
/// ДРУГОЙ, и страница выдачи собиралась суммой всех задержек сети. Это и
/// выглядело как «лента грузится вечно»: сама сеть быстрая, но её ждали по
/// очереди.
///
/// Порядок возврата — исходный, а не «кто успел»: карточки обязаны совпадать
/// с находками по индексу.
fn миниатюры_разом(находки: &[online::Находка]) -> Vec<(u32, u32, Vec<u8>)> {
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Mutex;

    let готово: Vec<Mutex<Option<(u32, u32, Vec<u8>)>>> =
        (0..находки.len()).map(|_| Mutex::new(None)).collect();
    let след = AtomicUsize::new(0);
    let потоков = МИНИАТЮР_РАЗОМ.min(находки.len().max(1));

    // Область видимости даёт потокам занимать `находки` по ссылке — без неё
    // пришлось бы клонировать всю страницу на каждый поток.
    std::thread::scope(|s| {
        for _ in 0..потоков {
            s.spawn(|| loop {
                let i = след.fetch_add(1, Ordering::Relaxed);
                let Some(н) = находки.get(i) else { break };
                let мини = match online::миниатюра(н) {
                    Some(байты) => разобрать_миниатюру(&байты),
                    None => пустая_миниатюра(),
                };
                *готово[i].lock().unwrap() = Some(мини);
            });
        }
    });

    готово
        .into_iter()
        .map(|м| м.into_inner().unwrap().unwrap_or_else(пустая_миниатюра))
        .collect()
}

fn пустая_миниатюра() -> (u32, u32, Vec<u8>) {
    (МИНИ_W, МИНИ_H, vec![60u8; (МИНИ_W * МИНИ_H * 4) as usize])
}

/// Разобрать скачанную миниатюру в карточку сетки.
fn разобрать_миниатюру(байты: &[u8]) -> (u32, u32, Vec<u8>) {
    match image::load_from_memory(байты) {
        Ok(img) => {
            let (w, h) = img.dimensions();
            (МИНИ_W, МИНИ_H, resize(w, h, &img.to_rgba8().into_raw(), МИНИ_W, МИНИ_H))
        }
        // Битая или неизвестного формата — показываем серую заглушку, но
        // карточку оставляем: сами обои могут быть в порядке.
        Err(_) => пустая_миниатюра(),
    }
}

/// Пролистать сетку на `шаг` рядов, не вылезая за края списка.
fn прокрутить(state: &mut Config, шаг: i32) {
    let макс = предел_прокрутки(state) as i32;
    let новый = (state.scroll_row as i32 + шаг).clamp(0, макс) as u32;

    // Здесь когда-то стояла автоподгрузка: докрутил до конца — плюс страница.
    // Убрана нарочно. Она уходила в сеть от простого листания, то есть от
    // движения, которым человек ничего не просил, и лента дёргалась под рукой
    // ровно в тот момент, когда он к ней прицеливался. Следующую страницу
    // теперь берёт КАРТОЧКА «ДАЛЕЕ» в конце ленты (UiAction::Далее).
    if новый == state.scroll_row { return; }
    state.scroll_row = новый;
    // Хит-боксы привязаны к рядам — после сдвига их надо пересобрать, иначе
    // клик уходил бы по карточке, которая уже уехала.
    build_ui_layout(state);
    state.hover = hover_cell(state);
    state.dirty = true;
}

fn is_hover(state: &Config, x: u32, y: u32, w: u32, h: u32) -> bool {
    if state.cursor_x < 0.0 || state.cursor_y < 0.0 { return false; }
    let cx = state.cursor_x as u32;
    let cy = state.cursor_y as u32;
    cx >= x && cx < x + w && cy >= y && cy < y + h
}

/// Единственный источник правды о сетке карточек: и рисование, и хит-боксы
/// ходят сюда. Раньше эта арифметика была продублирована в render_overlay и
/// build_ui_layout — правка в одном месте разъезжалась с другим, и картинка
/// нажималась мимо.
///
/// Возвращает (индекс, x, y); индекс == wallpapers.len() — это карточка «+».
///
/// `scroll` — номер первого видимого ряда. Прокрутка идёт ЦЕЛЫМИ рядами, а не
/// пикселями: карточка тогда либо видна целиком, либо не рисуется вовсе, и не
/// нужно ни обрезать миниатюры по краю окна, ни держать хит-боксы с
/// отрицательной координатой (а они у нас в u32).
fn ui_cells(n: usize, scroll: u32) -> Vec<(usize, u32, u32)> {
    // n+1 карточек: сами обои плюс «+» в конце.
    сетка(n + 1, scroll)
}

/// Карточка ленты в её нынешнем месте: где стоит, какого размера и насколько
/// далеко от «переднего» места.
///
/// Раньше здесь была тройка `(индекс, x, y)`: все карточки были одного размера
/// и стояли в ряд. Лента с глубиной от такой тройки не строится — размер у
/// каждой карточки свой и меняется на каждом кадре листания.
#[derive(Clone, Copy, Debug)]
struct Карточка {
    idx: usize,
    /// Левый верхний угол. `x` бывает отрицательным — карточка уезжает за край.
    x: i32,
    y: i32,
    w: u32,
    h: u32,
    /// Насколько карточка в глубине: 0 — она спереди, 1 — соседняя, дальше
    /// больше. Дробное: лента едет плавно, и «спереди» переходит от одной
    /// карточки к другой постепенно.
    даль: f32,
}

/// Насколько карточка ужимается за каждый шаг вглубь.
const ГЛУБИНА_МАСШТАБ: f32 = 0.17;
/// Дальше этого не ужимаем: карточка обязана оставаться картинкой, а не
/// полоской у края.
const ГЛУБИНА_МИН: f32 = 0.60;
/// Шаг между серединами карточек — доля от полного (карточка + зазор). Меньше
/// единицы НАМЕРЕННО: соседи подныривают ПОД переднюю, и лента читается
/// стопкой, уходящей вдаль, а не полосой плиток.
const ГЛУБИНА_ШАГ: f32 = 0.86;
/// Насколько дальняя карточка притемняется за каждый шаг вглубь.
const ГЛУБИНА_ТЕНЬ: f32 = 0.24;

/// Доля, на которую пелена глубины гасит карточку на дали `даль`.
///
/// Ровно то, что давал прежний отдельный проход: чёрная `ТЕНЬ` (альфа 0x66)
/// с прозрачностью `min(ГЛУБИНА_ТЕНЬ·даль, 0.55)` поверх непрозрачной
/// картинки — это умножение цвета на (1 − доля).
fn пелена_глубины(даль: f32) -> f32 {
    if даль <= 0.01 {
        return 0.0;
    }
    let сила = (ГЛУБИНА_ТЕНЬ * даль).min(0.55);
    сила * ((ТЕНЬ >> 24) & 0xFF) as f32 / 255.0
}

/// Масштаб карточки по её дали.
fn масштаб_дали(даль: f32) -> f32 {
    (1.0 - ГЛУБИНА_МАСШТАБ * даль).max(ГЛУБИНА_МИН)
}

/// Та же лента, но по ТОЧНОМУ числу карточек. У сетевой выдачи карточки «+»
/// нет — добавлять в неё нечего.
///
/// `scroll` — номер карточки, стоящей в ленте ПЕРВОЙ слева. Раньше это был
/// номер ряда сетки; смысл поля `scroll_row` поменялся вместе с раскладкой, а
/// имя осталось прежним, чтобы не переименовывать его по всему файлу.
/// Ячейки ленты при ДРОБНОЙ позиции прокрутки: `(индекс, x, y)`, и `x` может
/// быть отрицательным — карточка наполовину уехала за левый край.
///
/// Ради этого и заведено: пока `scroll_row` был целым, лента перескакивала на
/// карточку рывком. Теперь целое остаётся ЦЕЛЬЮ, а рисуется и ловится клик по
/// дробной позиции, которая к ней едет (см. `Config::лента`).
///
/// Карточек берём на одну больше с каждой стороны: та, что уезжает, и та, что
/// приезжает, обязаны быть нарисованы, иначе на краях ленты возникали бы
/// провалы. Всё лишнее срезает обрезка холста.
fn сетка_дробно(всего: usize, поз: f32) -> Vec<Карточка> {
    let (кw, кh) = (карта_w(), карта_h());
    let видно = видно_карт();
    // Переднее место — середина ленты. При чётном числе видимых карточек оно
    // приходится на щель между ними, и «спереди» оказываются сразу две; это не
    // беда, а честная середина: доводить ленту до полукарточки нечем.
    let середина = (видно as f32 - 1.0) / 2.0;
    let центр_x = лента_x() as f32 + (видно * кw + (видно - 1) * GAP) as f32 / 2.0;
    let центр_y = лента_y() as f32 + кh as f32 / 2.0;
    let шаг = (кw + GAP) as f32 * ГЛУБИНА_ШАГ;
    let целая = поз.floor() as i64;
    let первая = (целая - 1).max(0);
    let последняя = (целая + видно as i64 + 1).min(всего as i64);
    let mut cells = Vec::new();
    for idx in первая..последняя {
        let смещение = idx as f32 - поз - середина;
        let даль = смещение.abs();
        let k = масштаб_дали(даль);
        let w = ((кw as f32 * k).round() as u32).max(1);
        let h = ((кh as f32 * k).round() as u32).max(1);
        let cx = центр_x + смещение * шаг;
        cells.push(Карточка {
            idx: idx as usize,
            x: (cx - w as f32 / 2.0).round() as i32,
            y: (центр_y - h as f32 / 2.0).round() as i32,
            w,
            h,
            даль,
        });
    }
    cells
}

/// Прямоугольник, в котором живёт лента: за него карточки не выпускаем.
fn лента_rect() -> (i32, i32, u32, u32) {
    let n = видно_карт();
    let ширина = n * карта_w() + (n - 1) * GAP;
    (лента_x() as i32, лента_y() as i32, ширина, карта_h())
}

/// Ячейки ленты в её нынешнем (анимированном) положении — по ним и рисуем, и
/// ловим клики. Одна функция на оба дела: разойдись они, клик во время
/// листания уходил бы по карточке, которой на этом месте уже нет.
fn ячейки_сейчас(state: &Config) -> Vec<Карточка> {
    let всего = карточек(state);
    сетка_дробно(всего, state.лента.значение())
}

/// Те же карточки, отсортированные ОТ ДАЛЬНИХ К БЛИЖНИМ — порядок отрисовки.
/// Передняя кладётся последней и накрывает соседей, которые под неё подныривают
/// (см. `ГЛУБИНА_ШАГ`).
fn ячейки_по_глубине(state: &Config) -> Vec<Карточка> {
    let mut к = ячейки_сейчас(state);
    к.sort_by(|a, b| b.даль.partial_cmp(&a.даль).unwrap_or(std::cmp::Ordering::Equal));
    к
}

/// Чья карточка живая: вкладка, номер в ленте и ЧТО за обои (путь или адрес
/// страницы). Одного номера мало: удалили обои или пришла другая выдача — под
/// тем же номером уже другая карточка, и старый ролик играл бы на чужой.
#[derive(Clone, PartialEq, Debug)]
struct КлючПревью {
    вкладка: Вкладка,
    idx: usize,
    что: String,
}

/// Передняя карточка ленты — та, что «выбрана лентой», — если лента стоит.
///
/// При чётном числе видимых карточек спереди стоят две, обе на дали 0.5 (см.
/// `сетка_дробно`); тогда живой становится левая.
fn передняя_карточка(state: &Config) -> Option<usize> {
    if state.лента.идёт() {
        return None;
    }
    ячейки_сейчас(state)
        .into_iter()
        .filter(|к| к.даль < 0.55)
        .min_by(|a, b| a.даль.partial_cmp(&b.даль).unwrap_or(std::cmp::Ordering::Equal))
        .map(|к| к.idx)
}

/// Какую карточку сейчас оживлять и откуда брать ей ролик. `None` — никакую:
/// меню закрыто, лента едет или спереди не ролик (картинка, «+», «далее»).
fn кандидат_превью(state: &Config) -> Option<(КлючПревью, preview::Источник)> {
    if !state.overlay_visible {
        return None;
    }
    let idx = передняя_карточка(state)?;
    let вкладка = state.вкладка;
    match вкладка {
        Вкладка::Мои => {
            let путь = state.wallpapers.get(idx)?;
            let живые = is_video(путь) || путь.to_lowercase().ends_with(".gif");
            живые.then(|| (
                КлючПревью { вкладка, idx, что: путь.clone() },
                preview::Источник::Файл(путь.clone()),
            ))
        }
        Вкладка::Живые => {
            let находка = state.находки.get(idx)?;
            Some((
                КлючПревью { вкладка, idx, что: находка.цель.clone() },
                preview::Источник::Сеть(находка.clone()),
            ))
        }
        // Картинкам оживать нечем.
        Вкладка::Картинки => None,
    }
}

/// Живая передняя карточка: завести, погасить или забрать очередной кадр.
///
/// Зовётся на каждом проходе главного цикла. Заводится не сразу, а когда лента
/// простояла на карточке `preview::ЗАДЕРЖКА`: пролистанные на ходу карточки
/// не должны запускать по ffmpeg (и по загрузке) каждая.
fn вести_превью(state: &mut Config) {
    let кандидат = кандидат_превью(state);
    let ключ = кандидат.as_ref().map(|(к, _)| к);
    // Живая карточка перестала быть передней (лента поехала, вкладка сменилась,
    // меню закрылось) — гасим, и на её место возвращается миниатюра.
    if state.превью.as_ref().is_some_and(|(к, _)| Some(к) != ключ) {
        state.превью = None;
        state.dirty = true;
    }
    let Some((ключ, источник)) = кандидат else {
        state.превью_ждёт = None;
        return;
    };
    if let Some((_, превью)) = state.превью.as_mut() {
        if превью.шаг() {
            state.dirty = true;
        }
        return;
    }
    match &state.превью_ждёт {
        Some((ждёт, с)) if *ждёт == ключ => {
            if с.elapsed() >= preview::ЗАДЕРЖКА {
                let превью = preview::Превью::завести(источник, (карта_w(), карта_h()));
                state.превью = Some((ключ, превью));
                state.превью_ждёт = None;
            }
        }
        _ => state.превью_ждёт = Some((ключ, std::time::Instant::now())),
    }
}

fn сетка(всего: usize, scroll: u32) -> Vec<(usize, u32, u32)> {
    let x0 = лента_x();
    let y = лента_y();
    let шаг = карта_w() + GAP;
    let видно = видно_карт();
    let mut cells = Vec::new();
    for idx in (scroll as usize)..всего {
        let место = idx as u32 - scroll;
        if место >= видно {
            break;
        }
        cells.push((idx, x0 + место * шаг, y));
    }
    cells
}

/// Всего карточек, считая карточку «+».
fn всего_рядов(n: usize) -> u32 {
    рядов(n + 1)
}

/// Сколько карточек в ленте всего. Функция осталась от сетки и теперь просто
/// пересчитывает число в тот же тип — но зовут её из четырёх мест, и убирать
/// её значило бы менять их все ради ясности в одном.
fn рядов(всего: usize) -> u32 {
    всего as u32
}

/// На сколько карточек ленту можно пролистать вправо.
fn макс_прокрутка(n: usize) -> u32 {
    всего_рядов(n).saturating_sub(видно_карт())
}

/// Прямоугольники кнопок-вкладок: свои обои, картинки, живые.
///
/// Подписей нет — в plx-wall нет шрифта, поэтому вкладки различаются значками
/// (сетка, гора-фотография, треугольник «плей»), а выбранная подсвечена.
fn tab_rects() -> [(u32, u32); 3] {
    let mx = лента_x();
    [(mx, 16), (mx + ARROW + 8, 16), (mx + 2 * (ARROW + 8), 16)]
}

/// Кнопка поиска — сразу за вкладками.
fn search_rect() -> (u32, u32) {
    (лента_x() + 3 * (ARROW + 8) + 6, 16)
}

/// Кнопка фильтров — следом за поиском. Живёт только на сетевых вкладках: у
/// своих обоев сужать нечего.
fn filter_rect() -> (u32, u32) {
    let (sx, sy) = search_rect();
    (sx + ARROW + 8, sy)
}

/// Подпись галочки «cycle».
const ПОДПИСЬ_ЦИКЛА: &str = "cycle";
/// Сторона квадратика галочки.
const КВАДРАТ_ЦИКЛА: u32 = 14;

/// Галочка «cycle» — у правого края верхней полосы, на всех вкладках:
/// (x, y, ширина), высота — `ARROW`.
fn цикл_rect() -> (u32, u32, u32) {
    let ш = ПОЛЕ_ИСТОЧНИКА * 2 + КВАДРАТ_ЦИКЛА + 7
        + ui::ширина_текста(ПОДПИСЬ_ЦИКЛА, КЕГЛЬ, ui::Начертание::Полужирное);
    (ui_w().saturating_sub(ш + 16), 16, ш)
}

/// Где рисовать значок загрузки: за последней кнопкой ряда.
fn спиннер_место(вкладка: Вкладка) -> (u32, u32) {
    // Там, где стоит ряд источников, за фильтром места больше нет — значок
    // уезжает к правому краю полосы, левее галочки «cycle». Раньше он вставал
    // бы ровно под первой кнопкой-источником.
    if источники_видны(вкладка) {
        let (_, y) = filter_rect();
        return (цикл_rect().0.saturating_sub(ARROW + 8), y);
    }
    let (x, y) = if вкладка == Вкладка::Мои { search_rect() } else { filter_rect() };
    (x + ARROW + 10, y)
}

const ВКЛАДКИ: [Вкладка; 3] = [Вкладка::Мои, Вкладка::Картинки, Вкладка::Живые];

// ── Выбор источника (API) ───────────────────────────────────────────────────
//
// Провайдер выбирался только через меню фильтров, а его показывает rofi —
// то есть чтобы сменить источник, меню приходилось ЗАКРЫТЬ, пройти два уровня
// чужого списка и открыть заново. При этом провайдер — не «фильтр» в одном
// ряду с ориентацией и порядком: это ответ на вопрос «откуда вообще брать
// обои», и от него зависит, работает ли поиск и какого размера будут файлы.
// Поэтому он вынесен в само меню, отдельным рядом кнопок с подписями.
//
// Подписи стали возможны только теперь: до появления `ui.rs` шрифта в plx-wall
// не было, и шесть источников нечем было отличить друг от друга — значками
// такое не покажешь.
const ИСТОЧНИКИ_КАРТИНОК: [(online::Провайдер, &str); 8] = [
    (online::Провайдер::Авто, "Авто"),
    (online::Провайдер::Wallhaven, "wallhaven"),
    (online::Провайдер::Openverse, "openverse"),
    (online::Провайдер::Викимедиа, "commons"),
    (online::Провайдер::Picsum, "picsum"),
    (online::Провайдер::Bing, "bing"),
    // Бесконечные — те, у кого выдача не кончается (см. online::бесконечный).
    (online::Провайдер::Космос, "NASA"),
    (online::Провайдер::Искусство, "искусство"),
];

/// Живых обоев источников два (см. [`online::ЖивойИсточник`]) — и это ровно
/// та причина, по которой ряд сначала показывался только на картинках: пока
/// сайт был один, выбирать было не из чего.
const ИСТОЧНИКИ_ЖИВЫХ: [(online::ЖивойИсточник, &str); 3] = [
    (online::ЖивойИсточник::Авто, "Авто"),
    (online::ЖивойИсточник::Motionbgs, "motionbgs"),
    (online::ЖивойИсточник::LiveWallpapers4Free, "lw4free"),
];

/// Отступ от подписи до края кнопки-источника.
const ПОЛЕ_ИСТОЧНИКА: u32 = 11;

/// Показывать ли ряд источников. На своих обоях его нет: они лежат на диске,
/// и «откуда брать» к ним не относится.
fn источники_видны(вкладка: Вкладка) -> bool {
    вкладка != Вкладка::Мои
}

/// Подписи источников для вкладки.
fn подписи_источников(вкладка: Вкладка) -> &'static [&'static str] {
    match вкладка {
        Вкладка::Живые => &["Авто", "motionbgs", "lw4free"],
        _ => &["Авто", "wallhaven", "openverse", "commons", "picsum", "bing"],
    }
}

/// Прямоугольники кнопок-источников: (x, y, ширина). Ширина у каждой своя —
/// по подписи, иначе «Авто» и «wallhaven» занимали бы поровну и ряд выглядел
/// бы разреженным.
///
/// Ряд не влезает — обрезаем с конца, а не сжимаем: обрезанная подпись хуже,
/// чем отсутствующая кнопка, которую всё равно можно достать через фильтры.
fn источник_rects(вкладка: Вкладка) -> Vec<(u32, u32, u32)> {
    let (fx, fy) = filter_rect();
    let mut x = fx + ARROW + 14;
    let предел = спиннер_место(вкладка).0;
    let mut из = Vec::new();
    for подпись in подписи_источников(вкладка) {
        let ш = ui::ширина_текста(подпись, КЕГЛЬ, ui::Начертание::Полужирное)
            + ПОЛЕ_ИСТОЧНИКА * 2;
        if x + ш > предел {
            break;
        }
        из.push((x, fy, ш));
        x += ш + 6;
    }
    из
}

/// Выбран ли сейчас источник с этим номером на этой вкладке.
fn источник_выбран(state: &Config, i: usize) -> bool {
    match state.вкладка {
        Вкладка::Живые => ИСТОЧНИКИ_ЖИВЫХ.get(i).map(|(п, _)| *п) == Some(state.фильтры.живой),
        _ => ИСТОЧНИКИ_КАРТИНОК.get(i).map(|(п, _)| *п) == Some(state.фильтры.провайдер),
    }
}

/// Прямоугольники стрелок прокрутки: (влево, вправо).
///
/// В ленте они стоят по её КРАЯМ и по вертикали посередине карточек — то есть
/// там, куда рука тянется листать. В сетке те же две стрелки были «вверх» и
/// «вниз» у правого поля.
fn arrow_rects() -> [(u32, u32); 2] {
    let y = лента_y() + карта_h() / 2 - ARROW / 2;
    let слева = (лента_x().saturating_sub(ARROW + 10)).max(6);
    let справа = (лента_x() + видно_карт() * карта_w() + (видно_карт() - 1) * GAP + 10)
        .min(ui_w().saturating_sub(ARROW + 6));
    [(слева, y), (справа, y)]
}

/// Крестик кнопки удаления: две диагонали внутри круга.
fn draw_cross(холст: &mut ui::Холст, x: i32, y: i32, size: u32) {
    let pad = size / 3;
    let n = size.saturating_sub(2 * pad);
    let цвет = ui::Цвет::из_argb(DEL_FG);
    for i in 0..n {
        let px = x + (pad + i) as i32;
        холст.скругл(px, y + (pad + i) as i32, 2, 2, 0, цвет);
        холст.скругл(px, y + (size - pad - i - 1) as i32, 2, 2, 0, цвет);
    }
}

/// Значок фильтров — воронка: три полосы, каждая короче предыдущей, и ножка.
///
/// Форма выбрана «на отличие»: рядом уже стоят решётка, гора, треугольник и
/// лупа, а подписей в меню нет и быть не может — шрифта у plx-wall нет.
fn draw_filter_icon(холст: &mut ui::Холст, x: u32, y: u32, цвет: ui::Цвет) {
    let верх = (y + ARROW / 2 - 6) as i32;
    let центр = (x + ARROW / 2) as i32;
    // Полосы: 14, 9 и 4 пикселя шириной, по одной через строку.
    for (i, ширина) in [14u32, 9, 4].into_iter().enumerate() {
        холст.скругл(центр - ширина as i32 / 2, верх + i as i32 * 4, ширина, 2, 1, цвет);
    }
    // Ножка вниз от самой узкой полосы — иначе воронка похожа на «список».
    холст.скругл(центр - 1, верх + 10, 2, 4, 0, цвет);
}

/// Значок поиска — лупа: кольцо и ручка.
fn draw_search_icon(холст: &mut ui::Холст, x: u32, y: u32, цвет: ui::Цвет) {
    let cx = (x + ARROW / 2 - 2) as i32;
    let cy = (y + ARROW / 2 - 2) as i32;
    let r = 7u32;
    // Кольцо — это кант круга: у скругления в половину стороны получается
    // ровно окружность, и рисуется она со сглаживанием, а не точками по
    // тригонометрии, как раньше.
    холст.кант(cx - r as i32, cy - r as i32, r * 2, r * 2, r, 1.8, цвет);
    // Ручка — по диагонали вниз-вправо от кольца.
    for i in 0..6i32 {
        холст.скругл(cx + 5 + i, cy + 5 + i, 2, 2, 0, цвет);
    }
}

/// Значок вкладки. Текста в меню нет, поэтому вкладки различаются рисунком:
/// решётка — свои обои, гора в рамке — картинки из сети, треугольник — живые.
fn draw_tab_icon(холст: &mut ui::Холст, вкладка: Вкладка, x: u32, y: u32, цвет: ui::Цвет) {
    let s = ARROW;
    let (x, y) = (x as i32, y as i32);
    match вкладка {
        Вкладка::Мои => {
            // Четыре квадратика — «моя коллекция».
            let d = s / 2 - 3;
            for (dx, dy) in [(0i32, 0i32), (1, 0), (0, 1), (1, 1)] {
                холст.скругл(
                    x + 6 + dx * (d as i32 + 2),
                    y + 6 + dy * (d as i32 + 2),
                    d, d, 2, цвет,
                );
            }
        }
        Вкладка::Картинки => {
            // Рамка с «горой» внутри — привычный значок изображения.
            //
            // Гора РАСШИРЯЕТСЯ КНИЗУ. Прежний цикл давал обратное — самый
            // широкий ряд оказывался наверху, — и значок читался как конверт
            // с откинутым клапаном, а не как картинка.
            холст.кант(x + 5, y + 7, s - 10, s - 12, 3, 1.6, цвет);
            let рядов = 6i32;
            let база = y + s as i32 - 9;
            for r in 0..рядов {
                let ширина = ((рядов - r) as u32 * 2).min(s - 16);
                холст.скругл(x + s as i32 / 2 - (рядов - r), база - r, ширина, 1, 0, цвет);
            }
            // Солнце в углу — оно окончательно отличает «картинку» от рамки.
            холст.скругл(x + s as i32 - 11, y + 10, 3, 3, 1, цвет);
        }
        Вкладка::Живые => {
            // Треугольник «плей» — движущиеся обои.
            let высота = s - 12;
            for ряд in 0..высота {
                // Ширина сходится к острию: до середины растёт, дальше падает.
                let от_края = if ряд < высота / 2 { ряд } else { высота - 1 - ряд };
                let ширина = (от_края * (s - 14) * 2 / высота.max(1)).max(1);
                холст.скругл(x + 8, y + 6 + ряд as i32, ширина, 1, 0, цвет);
            }
        }
    }
}

/// Движется ли сейчас хоть одна анимация меню — по этому ответу главный цикл
/// решает, будить ли себя под следующий кадр.
fn идёт_анимация(state: &Config) -> bool {
    state.открытие.идёт()
        || state.открытие.значение() != state.открытие.цель()
        || state.подчёркивание.идёт()
        // ЛЕНТА. Её здесь не было, и это стоило самой заметной дёрганости:
        // пока карточки едут вбок, никакой другой причины проснуться у цикла
        // нет — мышь стоит, сеть молчит, — и он засыпал на секунду. Листание
        // от этого шло рывками по одному кадру, хотя сама анимация считалась
        // правильно.
        || state.лента.идёт()
        || state.подсветки.шевелится()
}

/// Сколько карточек в сетке сейчас: свои обои плюс «+», либо находки из сети
/// плюс карточка «далее».
fn карточек(state: &Config) -> usize {
    match state.вкладка {
        Вкладка::Мои => state.wallpapers.len() + 1,
        _ => карточек_в_сети(state.находки.len()),
    }
}

/// Сколько карточек в сетевой ленте при `находок` находках.
///
/// Отдельной функцией — ради проверки: правило маленькое, но ошибиться в нём
/// значит либо потерять кнопку «далее», либо показать её на пустой выдаче,
/// где она выглядит единственной находкой и ведёт в никуда.
fn карточек_в_сети(находок: usize) -> usize {
    if находок == 0 {
        // Следующей страницы у пустоты не бывает.
        0
    } else {
        находок + 1
    }
}

fn предел_прокрутки(state: &Config) -> u32 {
    рядов(карточек(state)).saturating_sub(видно_карт())
}

fn build_ui_layout(state: &mut Config) {
    state.hit_rects.clear();
    let n = state.wallpapers.len();
    // Список мог укоротиться (удалили обои) — не оставляем прокрутку за краем,
    // иначе меню открывалось бы на пустом месте.
    state.scroll_row = state.scroll_row.min(предел_прокрутки(state));

    // Вкладки — поверх всего: они в собственной полосе над сеткой.
    for (i, (tx, ty)) in tab_rects().iter().enumerate() {
        state.hit_rects.push(HitRect {
            x: *tx, y: *ty, w: ARROW, h: ARROW,
            action: UiAction::Вкладка(ВКЛАДКИ[i]),
        });
    }
    let (sx, sy) = search_rect();
    state.hit_rects.push(HitRect { x: sx, y: sy, w: ARROW, h: ARROW, action: UiAction::Поиск });
    if state.вкладка != Вкладка::Мои {
        let (fx, fy) = filter_rect();
        state.hit_rects.push(HitRect { x: fx, y: fy, w: ARROW, h: ARROW, action: UiAction::Фильтр });
    }
    if источники_видны(state.вкладка) {
        for (i, (x, y, ш)) in источник_rects(state.вкладка).into_iter().enumerate() {
            state.hit_rects.push(HitRect {
                x, y, w: ш, h: ARROW, action: UiAction::Источник(i),
            });
        }
    }
    {
        let (x, y, ш) = цикл_rect();
        state.hit_rects.push(HitRect { x, y, w: ш, h: ARROW, action: UiAction::Цикл });
    }

    // Сетевая выдача: своя раскладка, без карточки «+» и без крестиков —
    // удалять из чужого каталога нечего.
    if state.вкладка != Вкладка::Мои {
        let найдено = state.находки.len();
        for карточка in ячейки_по_месту(state) {
            if let Some(область) = карточка_в_ленте(&карточка) {
                let action = if карточка.idx < найдено {
                    UiAction::ВзятьИзСети(карточка.idx)
                } else {
                    UiAction::Далее
                };
                state.hit_rects.push(HitRect { action, ..область });
            }
        }
        if предел_прокрутки(state) > 0 {
            let [(лx, лy), (пx, пy)] = arrow_rects();
            state.hit_rects.push(HitRect { x: лx, y: лy, w: ARROW, h: ARROW, action: UiAction::Scroll(-1) });
            state.hit_rects.push(HitRect { x: пx, y: пy, w: ARROW, h: ARROW, action: UiAction::Scroll(1) });
        }
        return;
    }

    // Стрелки кладём первыми — они перекрывают поле, а не карточки.
    if макс_прокрутка(n) > 0 {
        let [(лx, лy), (пx, пy)] = arrow_rects();
        state.hit_rects.push(HitRect {
            x: лx, y: лy, w: ARROW, h: ARROW, action: UiAction::Scroll(-1),
        });
        state.hit_rects.push(HitRect {
            x: пx, y: пy, w: ARROW, h: ARROW, action: UiAction::Scroll(1),
        });
    }

    for карточка in ячейки_по_месту(state) {
        let idx = карточка.idx;
        let Some(область) = карточка_в_ленте(&карточка) else { continue };
        // Крестик удаления кладём ПЕРВЫМ: попадание ищется по порядку, и он
        // должен перехватывать клик раньше, чем сама карточка (иначе удаление
        // было бы недоступно — карточка накрывает его целиком).
        if idx < n {
            let dx = карточка.x + (карточка.w - DEL_SIZE - 8) as i32;
            let dy = карточка.y + 8;
            if dx >= 0 && dy >= 0 {
                state.hit_rects.push(HitRect {
                    x: dx as u32,
                    y: dy as u32,
                    w: DEL_SIZE,
                    h: DEL_SIZE,
                    action: UiAction::DeleteWallpaper(idx),
                });
            }
        }
        let action = if idx < n { UiAction::SelectWallpaper(idx) } else { UiAction::AddWallpaper };
        state.hit_rects.push(HitRect { action, ..область });
    }
}

/// Те же карточки, но ОТ БЛИЖНИХ К ДАЛЬНИМ — порядок ловли клика. Карточки
/// перекрываются, попадание ищется по списку сверху вниз, и первой обязана
/// стоять та, что нарисована последней: щёлкают по видимому.
fn ячейки_по_месту(state: &Config) -> Vec<Карточка> {
    let mut к = ячейки_сейчас(state);
    к.sort_by(|a, b| a.даль.partial_cmp(&b.даль).unwrap_or(std::cmp::Ordering::Equal));
    к
}

/// Область нажатия карточки, обрезанная прямоугольником ленты.
///
/// `None` — карточку не видно вовсе (уехала за край при листании). Обрезка
/// обязательна: карточка, наполовину вышедшая за ленту, нарисована тоже
/// наполовину, и ловить клик по её невидимой части значило бы принимать
/// нажатия на стрелке листания как нажатия на обоях.
fn карточка_в_ленте(к: &Карточка) -> Option<HitRect> {
    let (лx, _, лш, _) = лента_rect();
    let левый = к.x.max(лx);
    let правый = (к.x + к.w as i32).min(лx + лш as i32);
    if правый <= левый || к.y < 0 {
        return None;
    }
    Some(HitRect {
        x: левый as u32,
        y: к.y as u32,
        w: (правый - левый) as u32,
        h: к.h,
        // Заполняется вызывающим — здесь нужна только геометрия.
        action: UiAction::Scroll(0),
    })
}

/// Считает миниатюры. Дорого: каждая картинка декодируется с диска целиком
/// (обои — это обычно 4K PNG), поэтому результат кэшируется по списку обоев.
/// Раньше вызов шёл на КАЖДОЕ открытие меню, и оно заметно подвисало перед
/// появлением; теперь пересчёт только когда список реально изменился —
/// например после добавления обоев плюсиком.
/// Запускает декодирование обоев в фоне. Результат подхватит главный цикл.
fn start_load_wallpaper(state: &mut Config, path: String) {
    save_current(&path);
    // Режим раскладки едет вместе с обоями: так он восстанавливается и после
    // перезапуска композитора, когда plx-wall поднимает обои заново.
    сообщить_цикл(state.цикл);

    // Палитра считается в СВОЁМ потоке и ничего не ждёт: она никак не влияет
    // на показ обоев, а декодирование картинки под гистограмму стоит столько
    // же, сколько сами обои, — в главном цикле это была бы заметная пауза.
    {
        let p = path.clone();
        std::thread::spawn(move || palette::apply(&p));
    }

    // Снимок того, что сейчас на экране, — с него начнётся плавный переход.
    // Берём именно показанный буфер, а не исходную картинку: так одинаково
    // работает и для статичных обоев, и для видео, где «текущего кадра» в
    // виде файла попросту нет.
    начать_переход(state);
    // Прошлые живые обои останавливаем сразу: Drop убьёт ffmpeg, а поток
    // gif-декодера сам выйдет, когда канал окажется закрыт.
    state.anim = None;
    // Слоты, одолженные СТАРОМУ декодеру, возвращаем: он умер вместе с Anim и
    // не вернёт их никогда. Раньше флаги оставались стоять, и если новый ролик
    // того же размера (а ужатые копии все ровно экранные), слоты не
    // пересоздавались — оба числились занятыми покойником, новому декодеру
    // выдать было нечего, и первый кадр не приходил вовсе: «обои не
    // меняются, пока не перезапустишь».
    state.слоты_у_декодера.iter_mut().for_each(|з| *з = false);
    state.кадр_слота = None;
    // То же для аппаратного пути. Буферы старых поверхностей уничтожаем явно:
    // прокси wayland-client в Drop ничего не разрушает, и при каждой смене
    // обоев на композиторе оседал бы лишний пул.
    state.hw = None;
    state.hw_на_экране.clear();
    for (буфер, _) in state.hw_буферы.values() {
        буфер.destroy();
    }
    state.hw_буферы.clear();
    state.hw_порядок.clear();
    for (буфер, _) in state.hw_мусор.drain(..) {
        буфер.destroy();
    }
    // Обои сменили — прошлый путь и его неудачные подъёмы забываем целиком:
    // поднимать заново надо будет уже НОВЫЙ файл, если он живой (см. ниже).
    state.живые_путь = None;
    state.живые_рестарт = None;
    // Смена обоев — это действие человека, значит обои сейчас ВИДНО, что бы ни
    // думал сторож молчания. Без этого был замкнутый круг: на неподвижном
    // экране композитор не отвечает на кадровый запрос, через ОЖИДАНИЕ_КАДРА
    // мы засыпаем, а спящие не забирают первый кадр новых обоев — переход
    // ждёт его вечно, ничего не коммитится, и ответу композитора взяться
    // неоткуда. Снаружи: «обои не меняются, пока не перезапустишь». Если обои
    // и правда закрыты, сторож снова уснёт через те же 300 мс.
    state.видно = true;
    state.кадр_заказан = None;

    // Живые форматы (видео и многокадровый gif) идут своим путём — кадрами.
    let (w, h) = state.outputs.first().map(|(_, w, h)| (*w, *h)).unwrap_or((0, 0));

    // ── Видео: сперва пробуем видеокарту ────────────────────────────────────
    // Кадр остаётся в видеопамяти от декодера до экрана, процессор не трогает
    // ни одного пикселя (см. hwvideo.rs). Не вышло — молча уходим на путь
    // через процесс ffmpeg ниже: обои важнее экономии.
    if w > 0 && h > 0 && is_video(&path) && state.dmabuf.is_some() {
        if let Some(hw) = hwvideo::запустить(&path, hwvideo::УЗЕЛ_ПО_УМОЛЧАНИЮ) {
            state.hw = Some(hw);
            state.hw_срок = std::time::Instant::now();
            state.кадр_слота = None;
            state.живые_путь = Some(path.clone());
            // Плавный переход играем по неподвижному первому кадру — сам
            // аппаратный кадр смешать не с чем. Пока он считается, декодер
            // стоит на первом же кадре и ничего не тратит.
            let (tx, rx) = std::sync::mpsc::channel();
            state.pending_img = Some(rx);
            let p = path.clone();
            std::thread::spawn(move || {
                let _ = tx.send(кадр_для_перехода(&p));
            });
            return;
        }
        eprintln!("plx-wall: видеокарта этот ролик не взяла — декодируем процессором");
    }

    if w > 0 && h > 0 && (is_video(&path) || path.to_lowercase().ends_with(".gif")) {
        if let Some(anim) = start_anim(&path, w, h) {
            state.anim = Some(anim);
            state.живые_путь = Some(path.clone());
            state.pending_img = None;
            return;
        }
        // Не вышло (одиночный gif, нет ffmpeg) — падаем в обычную картинку.
    }

    let (tx, rx) = std::sync::mpsc::channel();
    state.pending_img = Some(rx);
    std::thread::spawn(move || {
        let _ = tx.send(load_image(&path));
    });
}

/// Каталог, где лежат готовые миниатюры своих обоев.
fn каталог_миниатюр() -> std::path::PathBuf {
    std::path::PathBuf::from(format!("{}/.cache/plx-wall/thumbs", home()))
}

/// Имя файла миниатюры: путь + время правки + размер, свёрнутые в число.
///
/// Время и размер в ключе не для красоты: файл по тому же пути мог смениться
/// (человек перезаписал обои), и без них показывалась бы миниатюра прошлого.
fn ключ_миниатюры(path: &str) -> String {
    use std::hash::{Hash, Hasher};
    let mut h = std::collections::hash_map::DefaultHasher::new();
    path.hash(&mut h);
    if let Ok(м) = std::fs::metadata(path) {
        м.len().hash(&mut h);
        if let Ok(t) = м.modified() {
            if let Ok(d) = t.duration_since(std::time::UNIX_EPOCH) {
                d.as_secs().hash(&mut h);
            }
        }
    }
    format!("{:016x}.rgba", h.finish())
}

/// Одна миниатюра: сперва с диска, и только если её там нет — декодированием.
///
/// **Почему кэш на диске появился.** Свои обои у Ярика все до одной — РОЛИКИ, а
/// кадр из ролика достаёт отдельный запуск ffmpeg (см. `first_video_frame`):
/// 0.2 с на файл на настольной машине. Двадцать два файла — 6.7 с ЗАМЕРОМ, и
/// платились они при каждом первом открытии меню в сеансе. Снаружи это ровно
/// то, на что жаловался Ярик: «plx-wall очень долго грузится».
fn миниатюра_с_кэшем(path: &str) -> (u32, u32, Vec<u8>) {
    let нужно = (МИНИ_W * МИНИ_H * 4) as usize;
    let файл = каталог_миниатюр().join(ключ_миниатюры(path));
    if let Ok(данные) = std::fs::read(&файл) {
        if данные.len() == нужно {
            return (МИНИ_W, МИНИ_H, данные);
        }
    }
    let пиксели = match load_image(path) {
        Some((w, h, px)) => resize(w, h, &px, МИНИ_W, МИНИ_H),
        // Битые или неподдержанные обои — ровная серая плитка. В кэш она тоже
        // идёт: иначе каждое открытие меню заново запускало бы ffmpeg на
        // файле, который заведомо не читается.
        None => vec![60u8; нужно],
    };
    let _ = std::fs::create_dir_all(каталог_миниатюр());
    let _ = std::fs::write(&файл, &пиксели);
    (МИНИ_W, МИНИ_H, пиксели)
}

/// Сколько миниатюр считается разом.
///
/// Восемь — столько же, сколько у сетевых (`миниатюры_разом`), и по той же
/// причине: работа тут не процессорная, а «дождаться отдельного процесса
/// ffmpeg», и потоки почти всё время спят.
const ПОТОКОВ_МИНИАТЮР: usize = 8;

/// Посчитать миниатюры своих обоев: с диска — мгновенно, остальные — в восемь
/// потоков и ПО ОДНОЙ, каждая сразу на экран.
///
/// Раньше поток был один и отдавал ВЕСЬ список разом: пока считалась последняя,
/// меню стояло с пустыми карточками. Теперь пустых карточек нет вовсе (список
/// заполняется серыми плитками сразу), и каждая готовая тут же занимает своё
/// место.
fn load_thumbnails(state: &mut Config) {
    if state.thumbs_for == state.wallpapers && !state.thumbnails.is_empty() {
        return;
    }
    // Список сменился посреди подсчёта — прежний подсчёт бросаем (потоки
    // выйдут на первой же ошибке отправки) и начинаем по новому списку. Раньше
    // здесь стоял ранний выход «уже считаются», и миниатюры оставались от
    // старого списка до следующего открытия меню.
    state.pending_thumbs = None;

    // Готовые миниатюры переносим по ПУТИ: добавили одни обои или удалили —
    // остальные те же самые, и считать их заново (а у роликов это ffmpeg на
    // каждый файл) незачем. Раньше список чистился целиком, и меню на время
    // пересчёта мигало серыми плитками.
    let mut готовые: std::collections::HashMap<String, (u32, u32, Vec<u8>)> =
        std::collections::HashMap::new();
    let старые_пути = std::mem::take(&mut state.thumbs_for);
    let старые = std::mem::take(&mut state.thumbnails);
    let старые_готовы = std::mem::take(&mut state.миниатюра_готова);
    for ((путь, мини), готова) in старые_пути.into_iter().zip(старые).zip(старые_готовы) {
        if готова {
            готовые.insert(путь, мини);
        }
    }

    state.thumbs_for = state.wallpapers.clone();
    let пути = state.wallpapers.clone();
    // Заглушки — только там, где готовой нет: карточка обязана иметь размер и
    // цвет ещё до того, как её миниатюра посчитана, иначе меню рисует дыры.
    let mut нужны = Vec::new();
    state.thumbnails = Vec::with_capacity(пути.len());
    state.миниатюра_готова = Vec::with_capacity(пути.len());
    for (i, путь) in пути.iter().enumerate() {
        match готовые.remove(путь) {
            Some(мини) => {
                state.thumbnails.push(мини);
                state.миниатюра_готова.push(true);
            }
            None => {
                state.thumbnails.push((МИНИ_W, МИНИ_H, vec![40u8; (МИНИ_W * МИНИ_H * 4) as usize]));
                state.миниатюра_готова.push(false);
                нужны.push((i, путь.clone()));
            }
        }
    }
    if нужны.is_empty() {
        return;
    }
    let (tx, rx) = std::sync::mpsc::channel();
    state.pending_thumbs = Some(rx);
    let следующий = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let нужны = std::sync::Arc::new(нужны);
    for _ in 0..ПОТОКОВ_МИНИАТЮР.min(нужны.len()) {
        let tx = tx.clone();
        let нужны = нужны.clone();
        let следующий = следующий.clone();
        std::thread::spawn(move || {
            // Миниатюры — фон: кадр меню, который в это время рисуется, важнее
            // (см. first_video_frame). Картинки декодируются прямо в этом потоке.
            понизить_приоритет_потока();
            loop {
                let k = следующий.fetch_add(1, Ordering::Relaxed);
                let Some((i, path)) = нужны.get(k) else { break };
                // Ошибка отправки — список сменился, работать дальше не для
                // кого.
                if tx.send((*i, миниатюра_с_кэшем(path))).is_err() {
                    break;
                }
            }
        });
    }
}

/// Нарисовать миниатюру в прямоугольник карточки, ПОДГОНЯЯ размер.
///
/// Раньше здесь была обрезка по центру: миниатюра считалась ровно в размер
/// карточки (155×155), и подгонять было нечего. У ленты карточка зависит от
/// выхода — 568×320 на этом мониторе, — а пересчитывать миниатюры под каждый
/// размер значило бы декодировать все обои заново (это 4K PNG, десятки штук).
/// Поэтому миниатюры считаются раз и навсегда в МИНИ_W×МИНИ_H, а сюда
/// приходит масштабирование.
///
/// Уменьшаем усреднением по площади, а не выборкой: на 640→568 разницы почти
/// нет, а на 640→180 (мелкое меню) выборка съедает тонкие детали — ровно та же
/// причина, по которой усредняет `sni::fit_icon` в parallax.
fn draw_thumbnail(холст: &mut ui::Холст,
                  dx: i32, dy: i32, dw: u32, dh: u32,
                  thumb: &(u32, u32, Vec<u8>)) {
    let (tw, th, data) = thumb;
    let (tw, th) = (*tw, *th);
    if tw == 0 || th == 0 || dw == 0 || dh == 0 {
        return;
    }
    // Диапазоны исходника по каждой оси считаются ОДИН раз, а не для каждого
    // пикселя: это четыре деления на точку, и на трёх карточках 604×340 они
    // одни съедали больше двадцати миллисекунд на кадр — при анимации в 60
    // кадров это заведомо не по карману.
    let ряды: Vec<(u32, u32)> = (0..dh)
        .map(|row| {
            let y0 = (row as u64 * th as u64 / dh as u64) as u32;
            let y1 = (((row + 1) as u64 * th as u64 / dh as u64) as u32).max(y0 + 1).min(th);
            (y0, y1)
        })
        .collect();
    let столбцы: Vec<(u32, u32)> = (0..dw)
        .map(|col| {
            let x0 = (col as u64 * tw as u64 / dw as u64) as u32;
            let x1 = (((col + 1) as u64 * tw as u64 / dw as u64) as u32).max(x0 + 1).min(tw);
            (x0, x1)
        })
        .collect();

    // Обрезаем по тому же скруглению, что у карточки: раньше миниатюра
    // ложилась прямоугольником и её углы торчали за дугу.
    холст.картинка(dx, dy, dw, dh, CORNER, |col, row| {
        let (y0, y1) = ряды[row as usize];
        let (x0, x1) = столбцы[col as usize];
        // Частый случай — одна точка исходника на точку карточки (миниатюра
        // 640×360, карточка примерно такая же). Усреднять там нечего, а
        // общий путь стоит вчетверо дороже.
        if y1 == y0 + 1 && x1 == x0 + 1 {
            let si = ((y0 * tw + x0) * 4) as usize;
            return match data.get(si..si + 4) {
                Some(px) if px[3] == 255 => {
                    // Непрозрачную точку премультиплицировать нечем — цвет
                    // уже равен самому себе, и три деления можно не делать.
                    ui::Цвет { r: px[0], g: px[1], b: px[2], a: 255 }
                }
                Some(px) => ui::Цвет::из_argb(
                    ((px[3] as u32) << 24)
                        | ((px[0] as u32) << 16)
                        | ((px[1] as u32) << 8)
                        | px[2] as u32,
                ),
                None => ui::Цвет::ПУСТО,
            };
        }
        let (mut r, mut g, mut b, mut a, mut n) = (0u32, 0u32, 0u32, 0u32, 0u32);
        for y in y0..y1 {
            for x in x0..x1 {
                let si = ((y * tw + x) * 4) as usize;
                let Some(px) = data.get(si..si + 4) else { continue };
                r += px[0] as u32;
                g += px[1] as u32;
                b += px[2] as u32;
                a += px[3] as u32;
                n += 1;
            }
        }
        if n == 0 {
            return ui::Цвет::ПУСТО;
        }
        // Миниатюры приходят непремультиплицированными (обычная RGBA из
        // декодера), поэтому собираем цвет через `из_argb` — он и умножит.
        ui::Цвет::из_argb(
            ((a / n) << 24) | ((r / n) << 16) | ((g / n) << 8) | (b / n),
        )
    });
}

/// Кант по краю карточки — им лента показывает и наведение, и нынешние обои.
///
/// Идёт ровно по дуге скругления: прежний вариант рисовал четыре отрезка и
/// обрывал их, не доходя до углов, — на скруглении оставались заметные
/// разрывы, которые тем виднее, чем крупнее карточка.
fn нарисовать_кант(холст: &mut ui::Холст, x: i32, y: i32, w: u32, h: u32, цвет: ui::Цвет) {
    холст.кант(x, y, w, h, CORNER, 2.0, цвет);
}

/// Плюс на карточке добавления: две перекладины со скруглёнными концами.
fn draw_plus(холст: &mut ui::Холст, dx: i32, dy: i32, size: u32, цвет: ui::Цвет) {
    let cx = dx + size as i32 / 2;
    let cy = dy + size as i32 / 2;
    // Толщина и длина считаются от карточки, а не константами: на маленьком
    // выходе прежние 4×40 занимали почти всю высоту.
    let t = (size / 14).clamp(3, 6);
    let l = (size / 3).clamp(16, 52);
    холст.скругл(cx - l as i32 / 2, cy - t as i32 / 2, l, t, t / 2, цвет);
    холст.скругл(cx - t as i32 / 2, cy - l as i32 / 2, t, l, t / 2, цвет);
}

// ── Значок загрузки ──────────────────────────────────────────────────────────

/// Сколько ждём ответа на кадровый запрос, прежде чем счесть обои закрытыми.
///
/// Ответ приходит с частотой монитора (≈7 мс на 144 Гц), так что треть секунды
/// — это заведомо не «композитор задумался», а «нам не отвечают вовсе». Больше
/// брать незачем: всё это время живые обои считаются впустую.
const ОЖИДАНИЕ_КАДРА: std::time::Duration = std::time::Duration::from_millis(300);

/// Как часто проворачивается значок загрузки. 90 мс на точку — это полный
/// оборот примерно за 0.7 с: видно, что жизнь идёт, и не рябит.
const ШАГ_СПИННЕРА: std::time::Duration = std::time::Duration::from_millis(90);
const ТОЧЕК_СПИННЕРА: u32 = 8;
/// Сторона квадратика со значком, когда он показывается сам по себе (меню
/// закрыто, а обои или картинка ещё грузятся).
const СПИННЕР_ПЛАШКА: u32 = 44;

/// Идёт ли прямо сейчас хоть какая-нибудь загрузка.
///
/// Всё это — фоновая работа, из-за которой на экране какое-то время ничего не
/// происходит: обои декодируются (4K-PNG — сотни миллисекунд), считаются
/// миниатюры для меню, идёт запрос или скачивание из сети.
///
/// Отдельным пунктом — живые обои, у которых ещё не пришёл ПЕРВЫЙ кадр
/// (`fade.ждём`). Через pending_img они не проходят вовсе (см.
/// start_load_wallpaper), а ждать там дольше всего: два вызова ffprobe, запуск
/// ffmpeg и раскрутка декодера.
fn идёт_загрузка(state: &Config) -> bool {
    state.pending_img.is_some()
        || state.pending_thumbs.is_some()
        || state.сетевая_работа
        // Идущие загрузки обоев тоже держат значок: иначе карточка с пеленой
        // стояла бы с застывшим кольцом, и загрузка выглядела бы зависшей.
        || !state.загрузки.is_empty()
        || state.fade.as_ref().map(|f| f.ждём).unwrap_or(false)
}

/// Кольцо из точек, по которому бежит яркость.
///
/// Точки, а не крутящаяся дуга: рисуем без сглаживания и без блендинга (см.
/// fill_rounded_rect), и дуга из таких пикселей выглядела бы рваной лесенкой,
/// а круглая точка — нет.
fn нарисовать_спиннер(холст: &mut ui::Холст, x: u32, y: u32, size: u32, фаза: u32) {
    let центр = (x as f64 + size as f64 / 2.0, y as f64 + size as f64 / 2.0);
    let радиус = size as f64 / 2.0 - 3.0;
    let точка = (size as f64 / 9.0).max(1.5);
    for i in 0..ТОЧЕК_СПИННЕРА {
        let угол = std::f64::consts::TAU * i as f64 / ТОЧЕК_СПИННЕРА as f64
            - std::f64::consts::FRAC_PI_2;
        // Самая яркая — та точка, до которой дошла фаза; дальше по кругу гаснет.
        let позади = ((i + ТОЧЕК_СПИННЕРА - фаза % ТОЧЕК_СПИННЕРА) % ТОЧЕК_СПИННЕРА) as f64;
        let яркость = 1.0 - позади / ТОЧЕК_СПИННЕРА as f64;
        // Премультипликацию теперь делает `ui::Цвет` — гасить цвет руками, как
        // раньше, больше не нужно (и нельзя: вышло бы дважды).
        let a = (60.0 + 195.0 * яркость) as u32;
        нарисовать_точку(
            холст,
            центр.0 + радиус * угол.cos(),
            центр.1 + радиус * угол.sin(),
            точка,
            ui::Цвет::из_argb((a << 24) | 0x00DDDDDD),
        );
    }
}

/// Кадр оверлея, в котором нет ничего, кроме значка загрузки в углу: так он
/// выглядит, когда меню закрыто, а обои или картинка ещё грузятся. Пиксели
/// уже в BGRA (как ждёт wl_shm).
fn плашка_загрузки(фаза: u32) -> Vec<u8> {
    let mut pixels = vec![0u8; (ui_w() * ui_h() * 4) as usize];
    // Плашка под значком: на светлых обоях серые точки сами по себе теряются.
    let (x, y) = (ui_w() - СПИННЕР_ПЛАШКА - 4, ui_h() - СПИННЕР_ПЛАШКА - 4);
    {
        let mut холст = ui::Холст::новый(&mut pixels, ui_w(), ui_h());
        холст.скругл(
            x as i32, y as i32, СПИННЕР_ПЛАШКА, СПИННЕР_ПЛАШКА, CORNER,
            ui::Цвет::из_argb(ФОН_НИЗ),
        );
        холст.кант(
            x as i32, y as i32, СПИННЕР_ПЛАШКА, СПИННЕР_ПЛАШКА, CORNER, 1.0,
            ui::Цвет::из_argb(КАНТ),
        );
        нарисовать_спиннер(&mut холст, x + 8, y + 8, СПИННЕР_ПЛАШКА - 16, фаза);
    }
    for chunk in pixels.chunks_exact_mut(4) { chunk.swap(0, 2); }
    pixels
}

/// Залитый кружок с центром в дробной точке — из него собран спиннер.
/// Круг — это скруглённый квадрат с радиусом в половину стороны, так что
/// сглаживание достаётся ему даром.
fn нарисовать_точку(холст: &mut ui::Холст, cx: f64, cy: f64, r: f64, цвет: ui::Цвет) {
    let сторона = (r * 2.0).round().max(1.0) as u32;
    холст.скругл(
        (cx - r).round() as i32,
        (cy - r).round() as i32,
        сторона,
        сторона,
        сторона / 2,
        цвет,
    );
}

// ── Rounded rect ─────────────────────────────────────────────────────────────

fn fill_rounded_rect(pixels: &mut [u8], sw: u32, _sh: u32,
                     x: u32, y: u32, w: u32, h: u32, r: u32, color: u32) {
    let a = (color >> 24) & 0xFF;
    let rc = (color >> 16) & 0xFF;
    let g = (color >> 8) & 0xFF;
    let b = color & 0xFF;
    let rgba = [rc as u8, g as u8, b as u8, a as u8];

    let corner = |r: u32, row: u32| -> u32 {
        let d = r.saturating_sub(row);
        let xc = ((r as f64 * r as f64 - d as f64 * d as f64).sqrt() + 0.5) as u32;
        r.saturating_sub(xc)
    };

    for row in 0..h {
        let cy = y + row;
        if cy >= _sh { break; }
        let left = if row < r { corner(r, row) } else { 0 };
        let right = if row >= h.saturating_sub(r) { corner(r, h - 1 - row) } else { 0 };
        let cs = x + left;
        let ce = x + w - right;
        if ce <= cs { continue; }
        for col in cs..ce {
            let idx = ((cy * sw + col) * 4) as usize;
            if idx + 3 < pixels.len() { pixels[idx..idx+4].copy_from_slice(&rgba); }
        }
    }
}

// ── SHM helpers ──────────────────────────────────────────────────────────────

fn create_shm_fd(size: usize) -> Option<(i32, *mut libc::c_void)> {
    let fd = unsafe { libc::memfd_create(c"plx-wall".as_ptr(), libc::MFD_CLOEXEC) };
    if fd < 0 { return None; }
    // ftruncate может не дотянуть до size (например, tmpfs кончился) — тогда
    // mmap отдаст область короче буфера, и запись уедет за её край.
    if unsafe { libc::ftruncate(fd, size as i64) } < 0 {
        unsafe { libc::close(fd); }
        return None;
    }
    let ptr = unsafe { libc::mmap(std::ptr::null_mut(), size, libc::PROT_READ | libc::PROT_WRITE, libc::MAP_SHARED, fd, 0) };
    if ptr == libc::MAP_FAILED { unsafe { libc::close(fd); } return None; }
    Some((fd, ptr))
}

// ── Image loading ────────────────────────────────────────────────────────────

fn load_image(path: &str) -> Option<(u32, u32, Vec<u8>)> {
    // Видео: берём один кадр из середины — он идёт и в миниатюру, и как
    // статичная подложка, пока не раскрутится живой декодер.
    if is_video(path) {
        return first_video_frame(path);
    }
    let ext = std::path::Path::new(path).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    match ext.as_str() {
        "gif" => {
            // Первый кадр — тоже заплатка со своим прямоугольником, поэтому
            // кладём его на холст логического размера (см. start_anim). Без
            // этого миниатюра и статичная подложка показывали кусок кадра,
            // растянутый на всю карточку.
            let file = std::fs::File::open(path).ok()?;
            let mut d = gif::DecodeOptions::new();
            d.set_color_output(gif::ColorOutput::RGBA);
            let mut r = d.read_info(file).ok()?;
            let (sw, sh) = (r.width() as usize, r.height() as usize);
            let f = r.read_next_frame().ok()??;
            if sw == 0 || sh == 0 { return None; }
            let mut холст = vec![0u8; sw * sh * 4];
            let (fx, fy) = (f.left as usize, f.top as usize);
            let (fw, fh) = (f.width as usize, f.height as usize);
            for y in 0..fh {
                let dy = fy + y;
                if dy >= sh { break; }
                for x in 0..fw {
                    let dx = fx + x;
                    if dx >= sw { break; }
                    let s = (y * fw + x) * 4;
                    if s + 3 >= f.buffer.len() || f.buffer[s + 3] == 0 { continue; }
                    let d = (dy * sw + dx) * 4;
                    холст[d..d + 4].copy_from_slice(&f.buffer[s..s + 4]);
                }
            }
            for c in холст.chunks_exact_mut(4) { c[3] = 255; }
            Some((sw as u32, sh as u32, холст))
        }
        _ => {
            image::open(path).ok().map(|img| { let (w, h) = img.dimensions(); (w, h, img.to_rgba8().into_raw()) })
        }
    }
}

/// Возвращает картинку, растянутую под выход. Пустой/битый вход не роняет
/// клиент: from_raw отдаёт None, если длина буфера не сходится с iw*ih*4.
/// Масштабирование «ближайшим соседом» напрямую в целевой буфер.
///
/// Исходник растягивается на весь `dst` (как resize_to_fill: по большей
/// стороне, лишнее обрезается). Никаких промежуточных буферов: строка
/// источника выбирается по таблице, столбцы — по заранее посчитанным
/// индексам, дальше только запись 4 байт на пиксель.
fn blit_scaled(src: &[u8], iw: u32, ih: u32, dst: &mut [u8], ow: u32, oh: u32, bgra: bool) {
    if iw == 0 || ih == 0 || ow == 0 || oh == 0 { return; }
    // «Заполнить»: берём общий масштаб по большей стороне и центрируем.
    let k = (ow as f64 / iw as f64).max(oh as f64 / ih as f64);
    let вид_w = (ow as f64 / k).min(iw as f64).max(1.0);
    let вид_h = (oh as f64 / k).min(ih as f64).max(1.0);
    let off_x = (iw as f64 - вид_w) / 2.0;
    let off_y = (ih as f64 - вид_h) / 2.0;

    // Таблица столбцов считается один раз на кадр, а не для каждой строки.
    let mut cols = vec![0usize; ow as usize];
    for (x, c) in cols.iter_mut().enumerate() {
        let sx = (off_x + (x as f64 + 0.5) * вид_w / ow as f64) as usize;
        *c = sx.min(iw as usize - 1) * 4;
    }

    for y in 0..oh as usize {
        let sy = ((off_y + (y as f64 + 0.5) * вид_h / oh as f64) as usize).min(ih as usize - 1);
        let строка = sy * iw as usize * 4;
        let выход = y * ow as usize * 4;
        for x in 0..ow as usize {
            let i = строка + cols[x];
            let o = выход + x * 4;
            if i + 3 >= src.len() || o + 3 >= dst.len() { continue; }
            if bgra {
                dst[o] = src[i];
                dst[o + 1] = src[i + 1];
                dst[o + 2] = src[i + 2];
            } else {
                dst[o] = src[i + 2];
                dst[o + 1] = src[i + 1];
                dst[o + 2] = src[i];
            }
            dst[o + 3] = src[i + 3];
        }
    }
}

fn resize_ex(iw: u32, ih: u32, px: &[u8], ow: u32, oh: u32, быстро: bool) -> Vec<u8> {
    let Some(img) = image::RgbaImage::from_raw(iw, ih, px.to_vec()) else {
        return vec![35u8; (ow * oh * 4) as usize];
    };
    // Для анимации — Nearest: gif обычно мелкий (320×180), а тянуть его надо
    // на весь экран по десять раз в секунду. Triangle на этом съедал пятую
    // часть ядра, Nearest почти бесплатен, а на растянутых в семь раз обоях
    // разницу увидеть трудно.
    let f = if быстро { FilterType::Nearest } else { FilterType::Lanczos3 };
    DynamicImage::ImageRgba8(img).resize_to_fill(ow, oh, f).to_rgba8().into_raw()
}

fn resize(iw: u32, ih: u32, px: &[u8], ow: u32, oh: u32) -> Vec<u8> {
    let Some(img) = image::RgbaImage::from_raw(iw, ih, px.to_vec()) else {
        return vec![35u8; (ow * oh * 4) as usize];
    };
    DynamicImage::ImageRgba8(img)
        .resize_to_fill(ow, oh, FilterType::Lanczos3).to_rgba8().into_raw()
}

/// Диалог выбора файла для карточки «+».
///
/// zenity в системе нет (это NixOS без GTK-обвязки), поэтому спрашиваем
/// каждого кандидата по очереди и берём первого установленного. rofi —
/// нативный Wayland-launcher, он тут есть; список файлов ему подаём сами,
/// собрав картинки из стандартных каталогов.
fn pick_wallpaper_file() -> Option<String> {
    // Графические диалоги, если вдруг появятся в системе.
    for (bin, args) in [
        ("zenity", &["--file-selection", "--title=Выберите обои"][..]),
        ("kdialog", &["--getopenfilename"][..]),
        ("yad", &["--file", "--title=Выберите обои"][..]),
    ] {
        if which(bin).is_none() { continue; }
        let out = std::process::Command::new(bin).args(args).output().ok()?;
        if !out.status.success() { return None; }
        let path = String::from_utf8_lossy(&out.stdout).trim().to_string();
        return if path.is_empty() { None } else { Some(path) };
    }

    // Фолбэк: свой список картинок через dmenu-подобный выбор.
    let candidates = scan_image_files();
    if candidates.is_empty() { return None; }
    for (bin, args) in [
        ("rofi", &["-dmenu", "-p", "обои"][..]),
        ("fuzzel", &["--dmenu", "--layer=overlay", "--prompt=обои: "][..]),
        ("wofi", &["--dmenu"][..]),
        ("bemenu", &["-p", "обои"][..]),
        ("dmenu", &["-p", "обои"][..]),
    ] {
        if which(bin).is_none() { continue; }
        return run_dmenu(bin, args, &candidates);
    }
    None
}

fn which(bin: &str) -> Option<String> {
    let path = std::env::var("PATH").ok()?;
    path.split(':')
        .map(|d| format!("{d}/{bin}"))
        .find(|p| std::fs::metadata(p).map(|m| m.is_file()).unwrap_or(false))
}

/// Скормить список строк dmenu-подобной утилите и вернуть выбранную.
fn run_dmenu(bin: &str, args: &[&str], items: &[String]) -> Option<String> {
    use std::io::Write;
    let mut child = std::process::Command::new(bin)
        .args(args)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .spawn().ok()?;
    // stdin закрываем до wait_with_output, иначе dmenu ждёт EOF, а мы — его.
    if let Some(mut stdin) = child.stdin.take() {
        let _ = stdin.write_all(items.join("\n").as_bytes());
    }
    let out = child.wait_with_output().ok()?;
    if !out.status.success() { return None; }
    let path = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if path.is_empty() { None } else { Some(path) }
}

/// Картинки из привычных каталогов — то, из чего пользователю предлагаем выбрать.
fn scan_image_files() -> Vec<String> {
    let home = home();
    let mut out = Vec::new();
    for dir in [
        format!("{home}/Pictures"),
        format!("{home}/Pictures/Wallpapers"),
        format!("{home}/Загрузки"),
        format!("{home}/Downloads"),
        format!("{home}/.config/plx-wall"),
    ] {
        let Ok(entries) = std::fs::read_dir(&dir) else { continue };
        for e in entries.flatten() {
            let p = e.path();
            if is_image(&p) { out.push(p.to_string_lossy().to_string()); }
        }
    }
    out.sort();
    out.dedup();
    out
}

/// Один кадр видео размером 640×360 — для миниатюры и статичной подложки.
fn first_video_frame(path: &str) -> Option<(u32, u32, Vec<u8>)> {
    use std::os::unix::process::CommandExt;
    const W: u32 = 640;
    const H: u32 = 360;
    let mut команда = std::process::Command::new("ffmpeg");
    // Миниатюры считаются пачкой по ПОТОКОВ_МИНИАТЮР разом, и каждый ffmpeg
    // без ограничения декодировал 4K во все ядра обычным приоритетом. Замер
    // 05.10.2026 на 300 обоях: меню, которое в это время листают, делило
    // процессор с восемью такими — 6–8 кадров в секунду. Один кадр миниатюры
    // одному потоку декодера по силам, а спешить ему некуда.
    // SAFETY: в pre_exec только nice(2) — async-signal-safe.
    unsafe {
        команда.pre_exec(|| {
            libc::nice(10);
            Ok(())
        });
    }
    let out = команда
        .args([
            "-loglevel", "error", "-nostdin",
            "-threads", "1",
            "-ss", "1", "-i", path, "-frames:v", "1",
            "-vf", &format!("scale={W}:{H}:force_original_aspect_ratio=increase,crop={W}:{H}"),
            "-f", "rawvideo", "-pix_fmt", "rgba", "-",
        ])
        .output()
        .ok()?;
    let нужно = (W * H * 4) as usize;
    if out.stdout.len() < нужно {
        return None;
    }
    Some((W, H, out.stdout[..нужно].to_vec()))
}

/// Первый кадр ролика в РОДНОМ разрешении — снимок, по которому играется
/// плавный переход на живые обои.
///
/// Зачем отдельно от [`first_video_frame`]: тот отдаёт миниатюру 640×360 для
/// меню, и на экране 3840×2160 переход по ней шёл бы через заметное мыло.
///
/// Аппаратный декодер смешивать нечем: его кадр лежит в видеопамяти, и
/// процессор до него не дотягивается (в этом вся суть, см. hwvideo.rs).
/// Поэтому переход играется по этому неподвижному кадру обычным путём через
/// общую память, а когда он доигран, эстафету незаметно принимает видеокарта —
/// картинка та же самая, стыка не видно.
///
/// Цена — один запуск ffmpeg на ОДИН кадр при смене обоев. На фоне того, что
/// раньше ffmpeg работал непрерывно все 60 кадров в секунду, это ничто.
fn кадр_для_перехода(path: &str) -> Option<(u32, u32, Vec<u8>)> {
    let (w, h) = размер_видео(path)?;
    if w == 0 || h == 0 {
        return None;
    }
    let out = std::process::Command::new("ffmpeg")
        .args([
            "-loglevel", "error", "-nostdin",
            "-i", path, "-frames:v", "1",
            // rgba, а не bgra: так же, как отдаёт load_image, и общий путь
            // показа сам свопнет каналы (img_bgra = false).
            "-f", "rawvideo", "-pix_fmt", "rgba", "-",
        ])
        .output()
        .ok()?;
    let нужно = (w as usize) * (h as usize) * 4;
    if out.stdout.len() < нужно {
        return None;
    }
    Some((w, h, out.stdout[..нужно].to_vec()))
}

fn is_image(p: &std::path::Path) -> bool {
    matches!(
        p.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase().as_str(),
        // Картинки — через image/gif, видео — через ffmpeg (см. start_anim).
        "png" | "jpg" | "jpeg" | "gif" | "webp" | "bmp"
            | "mp4" | "webm" | "mkv" | "mov" | "avi"
    )
}

// ── Config persistence ───────────────────────────────────────────────────────

fn home() -> String { std::env::var("HOME").unwrap_or_else(|_| "/tmp".into()) }

fn load_config(state: &mut Config) {
    let path = format!("{}/.config/plx-wall/wallpapers.json", home());
    if let Ok(data) = std::fs::read_to_string(&path) {
        if let Ok(list) = serde_json::from_str::<Vec<String>>(&data) { state.wallpapers = list; return; }
    }
    let dir = format!("{}/.config/plx-wall", home());
    let mut list = Vec::new();
    if let Ok(entries) = std::fs::read_dir(&dir) {
        for e in entries.flatten() {
            let p = e.path();
            if is_image(&p) { list.push(p.to_string_lossy().to_string()); }
        }
    }
    list.sort();
    state.wallpapers = list;
}

/// Путь к файлу с ВЫБРАННЫМИ обоями. Список хранится отдельно (wallpapers.json)
/// и порядок в нём может меняться, поэтому запоминаем сам путь, а не индекс.
fn current_path_file() -> String {
    format!("{}/.config/plx-wall/current", home())
}

/// Запомнить, какие обои показаны сейчас.
fn save_current(path: &str) {
    let p = current_path_file();
    if let Some(d) = std::path::Path::new(&p).parent() { let _ = std::fs::create_dir_all(d); }
    let _ = std::fs::write(&p, path);
}

/// Прочитать запомненные обои (если файл ещё существует).
fn load_current() -> Option<String> {
    let s = std::fs::read_to_string(current_path_file()).ok()?;
    let s = s.trim().to_string();
    (!s.is_empty() && std::path::Path::new(&s).exists()).then_some(s)
}

/// Файл галочки «cycle»: `1` или `0`.
fn cycle_path_file() -> String {
    format!("{}/.config/plx-wall/cycle", home())
}

fn load_cycle() -> bool {
    std::fs::read_to_string(cycle_path_file()).is_ok_and(|s| s.trim() == "1")
}

fn save_cycle(вкл: bool) {
    let p = cycle_path_file();
    if let Some(d) = std::path::Path::new(&p).parent() { let _ = std::fs::create_dir_all(d); }
    let _ = std::fs::write(&p, if вкл { "1" } else { "0" });
}

/// Сказать композитору, как класть обои: `wallpaper cycle on|off` в его
/// управляющий сокет (`$XDG_RUNTIME_DIR/plx-<WAYLAND_DISPLAY>.ctl`, либо
/// `PLX_CTL_SOCKET`). Плитку рисует parallax — plx-wall отдаёт одну картинку.
///
/// В своём потоке: на старте сеанса сокета может ещё не быть, и ждать его
/// главным циклом нельзя. Чужой композитор без сокета — просто тишина.
fn сообщить_цикл(вкл: bool) {
    let путь = match std::env::var_os("PLX_CTL_SOCKET") {
        Some(явный) => std::path::PathBuf::from(явный),
        None => {
            let Some(дисплей) = std::env::var_os("WAYLAND_DISPLAY") else { return };
            let каталог = std::env::var_os("XDG_RUNTIME_DIR")
                .map(std::path::PathBuf::from)
                .unwrap_or_else(std::env::temp_dir);
            каталог.join(format!("plx-{}.ctl", дисплей.to_string_lossy()))
        }
    };
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        for _ in 0..10 {
            if let Ok(mut s) = std::os::unix::net::UnixStream::connect(&путь) {
                let _ = s.set_read_timeout(Some(std::time::Duration::from_secs(2)));
                let _ = s.write_all(if вкл { b"wallpaper cycle on\n" } else { b"wallpaper cycle off\n" });
                let _ = s.shutdown(std::net::Shutdown::Write);
                let mut ответ = String::new();
                let _ = s.read_to_string(&mut ответ);
                return;
            }
            std::thread::sleep(std::time::Duration::from_secs(1));
        }
    });
}

fn save_config(wallpapers: &[String]) {
    let path = format!("{}/.config/plx-wall/wallpapers.json", home());
    if let Some(d) = std::path::Path::new(&path).parent() { let _ = std::fs::create_dir_all(d); }
    if let Ok(data) = serde_json::to_string_pretty(wallpapers) { let _ = std::fs::write(&path, &data); }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Размер меню — process-wide атомик (см. `установить_размер_меню`), а
    /// тесты идут ПАРАЛЛЕЛЬНО: тест ленты, подставляющий свой выход, менял
    /// размер прямо под тестом значка, который в этот момент считал буфер по
    /// старому. Падало это плавающе и на ровном месте — ровно та же грабля,
    /// что у темпа анимаций в parallax. Поэтому все, кто размер трогает ИЛИ
    /// читает, делят один замок.
    static ЗАМОК_РАЗМЕРА: std::sync::Mutex<()> = std::sync::Mutex::new(());

    /// Взять замок и вернуть меню к размеру по умолчанию: тест ленты
    /// подставляет свой выход, и следующий не должен зависеть от того, в каком
    /// порядке их запустили.
    pub(super) fn под_замком() -> std::sync::MutexGuard<'static, ()> {
        // `unwrap_or_else` вместо `unwrap`: упавший тест отравляет мьютекс, и
        // без этого все остальные посыпались бы следом, скрыв настоящую причину.
        let замок = ЗАМОК_РАЗМЕРА.lock().unwrap_or_else(|e| e.into_inner());
        установить_размер_меню(1920, 1080);
        замок
    }


    /// Кроп для NVDEC: остаток обязан быть ровно в пропорции экрана (иначе
    /// картинка на обоях растянется), а числа — чётными (иначе декодер не
    /// поделит цветоразностный канал).
    #[test]
    fn кроп_для_видеокарты_даёт_пропорцию_экрана() {
        let случаи = [
            // (исходник, экран, ожидаемые сверху и слева)
            ((3840, 2160), (2560, 1080), (270, 0)), // обои с котёнком, замер 12.08.2026
            ((3840, 2160), (1920, 1080), (0, 0)),   // те же пропорции — резать нечего
            ((3840, 1080), (2560, 1080), (0, 640)), // исходник шире экрана
            ((1920, 1080), (1080, 1920), (0, 656)), // экран «портретом»
        ];
        for ((sw, sh), (tw, th), ждём) in случаи {
            let (сверху, слева) = cuvid_кроп((sw, sh), (tw, th));
            assert_eq!(
                (сверху, слева), ждём,
                "кроп {sw}×{sh} → {tw}×{th}",
            );
            assert_eq!((сверху % 2, слева % 2), (0, 0), "нечётный кроп {sw}×{sh} → {tw}×{th}");
            // Остаток после кропа — в пропорции экрана (с точностью до
            // округления до чётного).
            let (ow, oh) = (sw - 2 * слева, sh - 2 * сверху);
            let перекос = (ow as f64 / oh as f64) - (tw as f64 / th as f64);
            assert!(
                перекос.abs() < 0.01,
                "после кропа {ow}×{oh} — это не пропорция экрана {tw}×{th}",
            );
        }
    }

    /// Значок загрузки: плашка непрозрачна, точки лежат внутри неё, а фаза
    /// действительно проворачивает кольцо (иначе «крутящийся» значок замер бы
    /// намертво, и заметить это на глаз было бы нечем).
    #[test]
    fn значок_загрузки_рисуется_и_крутится() {
        let _замок = под_замком();
        let кадр = плашка_загрузки(0);
        assert_eq!(кадр.len(), (ui_w() * ui_h() * 4) as usize);
        let альфа = |px: &[u8], x: u32, y: u32| px[((y * ui_w() + x) * 4 + 3) as usize];

        // Углы кадра прозрачны: за пределами плашки не должно быть ничего.
        assert_eq!(альфа(&кадр, 0, 0), 0);
        assert_eq!(альфа(&кадр, ui_w() / 2, ui_h() / 2), 0);
        // Центр плашки — сама плашка.
        let (cx, cy) = (ui_w() - СПИННЕР_ПЛАШКА / 2 - 4, ui_h() - СПИННЕР_ПЛАШКА / 2 - 4);
        assert!(альфа(&кадр, cx, cy) > 0, "плашка не нарисована");

        // Точки кольца: между фазами картинка обязана меняться, но пятно
        // остаётся тем же по площади — крутится яркость, а не размер.
        let другой = плашка_загрузки(3);
        assert_ne!(кадр, другой, "фаза не меняет картинку");
        let закрашено = |px: &[u8]| px.chunks_exact(4).filter(|c| c[3] > 0).count();
        assert_eq!(закрашено(&кадр), закрашено(&другой));
    }

    /// Кнопка фильтров: значок рисуется, лежит в своём прямоугольнике и НЕ
    /// совпадает с лупой. Подписей в меню нет — если два значка выйдут
    /// похожими, различить кнопки будет нечем, а на глаз это заметно только в
    /// живом сеансе.
    #[test]
    fn значок_фильтров_отличается_от_лупы() {
        let _замок = под_замком();
        let пусто = || vec![0u8; (ui_w() * ui_h() * 4) as usize];
        let (fx, fy) = filter_rect();

        let цвет = ui::Цвет::из_argb(0xFFEEEEEE);
        let mut воронка = пусто();
        draw_filter_icon(&mut ui::Холст::новый(&mut воронка, ui_w(), ui_h()), fx, fy, цвет);
        let закрашено = |px: &[u8]| px.chunks_exact(4).filter(|c| c[3] > 0).count();
        assert!(закрашено(&воронка) > 20, "значок не нарисован");

        // Всё нарисованное — внутри кнопки: соседние кнопки задевать нельзя.
        for (i, c) in воронка.chunks_exact(4).enumerate() {
            if c[3] == 0 { continue; }
            let (x, y) = (i as u32 % ui_w(), i as u32 / ui_w());
            assert!(
                x >= fx && x < fx + ARROW && y >= fy && y < fy + ARROW,
                "точка ({x},{y}) вне кнопки ({fx},{fy})"
            );
        }

        let mut лупа = пусто();
        draw_search_icon(&mut ui::Холст::новый(&mut лупа, ui_w(), ui_h()), fx, fy, цвет);
        assert_ne!(воронка, лупа, "воронку не отличить от лупы");

        // И сами кнопки не наезжают друг на друга.
        let (sx, _) = search_rect();
        assert!(fx >= sx + ARROW, "кнопка фильтров налезает на поиск");
    }

    /// Геометрия ленты живёт в двух местах — отрисовке и хит-боксах, — и оба
    /// берут её из одних и тех же функций. Проверяем сами функции: карточки
    /// стоят в ОДИН ряд, не налезают друг на друга, целиком помещаются в меню
    /// и не заезжают ни под полосу кнопок сверху, ни под прокрутку снизу.
    #[test]
    fn лента_укладывается_в_меню_на_любом_выходе() {
        let _замок = под_замком();
        for (sw, sh) in [(1366, 768), (1920, 1080), (2560, 1440), (3840, 2160), (800, 600)] {
            установить_размер_меню(sw, sh);
            let (кw, кh) = (карта_w(), карта_h());
            assert!(кw > 0 && кh > 0, "вырожденная карточка при {sw}×{sh}");
            assert_eq!(кw, кh * 16 / 9, "карточка потеряла 16:9 при {sw}×{sh}");

            let видно = видно_карт();
            assert!(видно >= 1);
            let места = сетка(100, 0);
            assert_eq!(места.len(), видно as usize, "показано не столько, сколько влезает");

            for &(_, x, y) in &места {
                assert!(x + кw <= ui_w(), "карточка вылезла вправо при {sw}×{sh}");
                assert!(y >= MY, "карточка заехала под кнопки при {sw}×{sh}");
                assert!(
                    y + кh <= ui_h(),
                    "карточка вылезла вниз при {sw}×{sh}: y={y} h={кh} меню={}", ui_h(),
                );
            }
            // Один ряд: все карточки на одной высоте и идут слева направо.
            for пара in места.windows(2) {
                assert_eq!(пара[0].2, пара[1].2, "лента развалилась на ряды");
                assert!(пара[0].1 + кw <= пара[1].1, "карточки налезли друг на друга");
            }
            // Лента стоит по центру: поля слева и справа одинаковые.
            let (первая, последняя) = (места.first().unwrap(), места.last().unwrap());
            let слева = первая.1;
            let справа = ui_w() - (последняя.1 + кw);
            assert!(
                слева.abs_diff(справа) <= 1,
                "лента не по центру при {sw}×{sh}: {слева} против {справа}",
            );
        }
    }

    /// На целой позиции карточки стоят симметрично: та, что спереди, — ровно
    /// в середине ленты, а соседи по обе стороны от неё одного размера.
    ///
    /// Прежний тест сверял дробную ленту с целой сеткой; со времён глубины
    /// сетка — не та же самая раскладка (карточки разного размера и заходят
    /// друг за друга), и сверять их построчно нечем. Проверяется то, что
    /// осталось верным и стало важнее: середина и симметрия.
    #[test]
    fn на_целой_позиции_лента_симметрична() {
        let _замок = под_замком();
        установить_размер_меню(2560, 1080);
        let (лx, _, лш, _) = лента_rect();
        for scroll in [0u32, 1, 3] {
            let ячейки = сетка_дробно(40, scroll as f32);
            let передняя = ячейки
                .iter()
                .min_by(|a, b| a.даль.partial_cmp(&b.даль).unwrap())
                .expect("лента не бывает пустой");
            assert!(передняя.даль < 0.001, "спереди обязана быть ровно одна: {}", передняя.даль);
            assert_eq!(передняя.w, карта_w(), "передняя карточка — в полный размер");
            let середина = передняя.x + передняя.w as i32 / 2;
            assert!(
                (середина - (лx + лш as i32 / 2)).abs() <= 1,
                "передняя карточка не по центру ленты: {середина}",
            );
            // Соседи по обе стороны ужаты одинаково.
            let слева = ячейки.iter().find(|к| к.idx + 1 == передняя.idx);
            let справа = ячейки.iter().find(|к| к.idx == передняя.idx + 1);
            if let (Some(л), Some(п)) = (слева, справа) {
                assert_eq!(л.w, п.w, "соседи разного размера");
                assert!(л.w < передняя.w, "сосед обязан быть меньше передней");
            }
        }
    }

    /// Посередине между карточками лента сдвинута ровно на полшага, а слева
    /// появляется та карточка, что уезжает: без неё на краю была бы дыра.
    #[test]
    fn на_полпути_лента_сдвинута_и_показывает_уезжающую() {
        let _замок = под_замком();
        установить_размер_меню(2560, 1080);
        let шаг = ((карта_w() + GAP) as f32 * ГЛУБИНА_ШАГ) as i32;
        let на_месте = сетка_дробно(40, 1.0);
        let на_полпути = сетка_дробно(40, 1.5);
        // Сравниваем СЕРЕДИНЫ: размер карточки на полпути другой (она уходит
        // в глубину), и по левому краю сдвиг не считается.
        let середина = |ячейки: &[Карточка], idx: usize| {
            ячейки.iter().find(|к| к.idx == idx).map(|к| к.x + к.w as i32 / 2)
        };
        let было = середина(&на_месте, 2).expect("карточка 2 видна");
        let стало = середина(&на_полпути, 2).expect("карточка 2 видна и на полпути");
        assert!(
            (было - стало - шаг / 2).abs() <= 1,
            "лента сдвинулась не на полшага: {было} → {стало} при шаге {шаг}",
        );
        assert!(середина(&на_полпути, 0).is_some(), "уезжающую карточку надо рисовать");
        assert!(
            середина(&на_полпути, 0).unwrap() < лента_x() as i32,
            "она уже за краем",
        );
    }

    /// Дальняя карточка мельче ближней и притемнена — то, ради чего глубина и
    /// заведена. Проверяется на арифметике, а не на снимке: снимок ловит вид,
    /// а тут важно правило.
    #[test]
    fn дальняя_карточка_мельче_ближней() {
        let _замок = под_замком();
        установить_размер_меню(2560, 1080);
        let ячейки = сетка_дробно(40, 5.0);
        let mut по_дали = ячейки.clone();
        по_дали.sort_by(|a, b| a.даль.partial_cmp(&b.даль).unwrap());
        for пара in по_дали.windows(2) {
            assert!(
                пара[0].w >= пара[1].w && пара[0].h >= пара[1].h,
                "дальняя карточка оказалась крупнее ближней: {:?} и {:?}",
                пара[0], пара[1],
            );
        }
        // Все карточки стоят по одной средней линии: глубина уводит вдаль, а
        // не роняет ленту вниз.
        let линия = |к: &Карточка| к.y + к.h as i32 / 2;
        for к in &ячейки {
            assert!(
                (линия(к) - линия(&по_дали[0])).abs() <= 1,
                "карточка {} съехала с линии ленты",
                к.idx,
            );
        }
        // И ужимаются не бесконечно.
        assert!(масштаб_дали(100.0) >= ГЛУБИНА_МИН);
    }

    /// Область нажатия карточки обрезана лентой: по невидимой половине
    /// уехавшей карточки кликать нельзя — там стрелка листания.
    #[test]
    fn попадание_обрезано_лентой() {
        let _замок = под_замком();
        установить_размер_меню(2560, 1080);
        let (лx, _, лш, _) = лента_rect();
        let карта = |x: i32| Карточка {
            idx: 0, x, y: лента_y() as i32, w: карта_w(), h: карта_h(), даль: 0.0,
        };

        // Целиком внутри — область во всю карточку.
        let целая = карточка_в_ленте(&карта(лx)).expect("карточка видна");
        assert_eq!(целая.w, карта_w());
        assert_eq!(целая.x, лx as u32);

        // Наполовину уехала влево — остаётся только видимая часть.
        let половина = карточка_в_ленте(&карта(лx - карта_w() as i32 / 2))
            .expect("половину карточки видно");
        assert_eq!(половина.x, лx as u32, "область начинается от края ленты");
        assert!(половина.w < карта_w() && половина.w > 0, "ширина {}", половина.w);

        // Уехала целиком — области нет вовсе.
        assert!(карточка_в_ленте(&карта(лx - карта_w() as i32 - 4)).is_none());
        assert!(карточка_в_ленте(&карта(лx + лш as i32 + 4)).is_none());
    }

    /// Прокрутка сдвигает ленту ровно на ОДНУ карточку и не показывает
    /// уехавшие. В сетке этот же тест проверял сдвиг на ряд.
    #[test]
    fn прокрутка_сдвигает_на_карточку() {
        let _замок = под_замком();
        установить_размер_меню(2560, 1440);
        let первый = ui_cells(40, 0);
        let второй = ui_cells(40, 1);
        assert_eq!(первый[0].0, 0);
        assert_eq!(второй[0].0, 1, "первой идёт следующая карточка");
        assert_eq!(первый[0].1, второй[0].1, "место первой карточки не меняется");
        assert_eq!(первый[0].2, второй[0].2, "лента не должна ездить по вертикали");
    }

    /// Листать можно ровно настолько, чтобы последняя карточка (это «+»)
    /// встала в ленту, и ни шагом больше.
    #[test]
    fn предел_прокрутки_доводит_до_плюса() {
        let _замок = под_замком();
        установить_размер_меню(2560, 1440);
        let видно = видно_карт() as usize;
        // Карточек меньше, чем влезает, — листать нечего.
        assert_eq!(макс_прокрутка(видно.saturating_sub(2)), 0);
        // Ровно столько, сколько влезает, — тоже нечего.
        assert_eq!(макс_прокрутка(видно - 1), 0);
        // Ещё одна — появляется ровно один шаг.
        assert_eq!(макс_прокрутка(видно), 1);

        // На пределе видно хвост списка, включая «+».
        let n = видно * 3 + 2;
        let cells = ui_cells(n, макс_прокрутка(n));
        assert!(
            cells.iter().any(|(idx, _, _)| *idx == n),
            "карточка «+» должна доезжать до ленты",
        );
        assert_eq!(cells.len(), видно, "на пределе лента обязана быть полной");
    }

    /// Стрелки листания стоят по краям ленты, на высоте середины карточек, и
    /// не наезжают ни на карточки, ни на края меню.
    #[test]
    fn стрелки_стоят_по_краям_ленты() {
        let _замок = под_замком();
        for (sw, sh) in [(1366, 768), (1920, 1080), (2560, 1440), (800, 600)] {
            установить_размер_меню(sw, sh);
            let [(лx, лy), (пx, пy)] = arrow_rects();
            assert!(лx + ARROW <= ui_w() && пx + ARROW <= ui_w(), "стрелка за краем при {sw}×{sh}");
            assert!(лy + ARROW <= ui_h() && пy + ARROW <= ui_h());
            assert!(лx < пx, "стрелки перепутаны местами при {sw}×{sh}");
            // И ни одна не лежит поверх карточек — ради этого и заведён ЛЕНТА_БОК.
            let места = сетка(100, 0);
            let (первая, последняя) = (места.first().unwrap(), места.last().unwrap());
            assert!(
                лx + ARROW <= первая.1,
                "левая стрелка наехала на карточку при {sw}×{sh}: {} против {}", лx + ARROW, первая.1,
            );
            assert!(
                пx >= последняя.1 + карта_w(),
                "правая стрелка наехала на карточку при {sw}×{sh}",
            );
            let середина = лента_y() + карта_h() / 2;
            for y in [лy, пy] {
                assert!(
                    (y + ARROW / 2).abs_diff(середина) <= 1,
                    "стрелка не по центру ленты при {sw}×{sh}",
                );
            }
        }
    }

}


#[cfg(test)]
mod посмотреть_ленту {
    use super::*;

    /// Сколько стоит ПОЛНЫЙ кадр меню — фон, тень и все видимые миниатюры.
    ///
    /// Это цена одного кадра анимации: пока меню выезжает или под курсором
    /// разгорается карточка, такой кадр рисуется 60 раз в секунду. Раньше
    /// меню перерисовывалось только на событиях мыши, и вопрос так не стоял.
    /// Замер, а не проверка:
    /// `cargo test --release -- --ignored --nocapture цена_кадра`.
    #[test]
    #[ignore = "замер времени"]
    fn цена_кадра() {
        установить_размер_меню(2560, 1080);
        let (w, h) = (ui_w(), ui_h());
        let (кw, кh) = (карта_w(), карта_h());
        // Миниатюра-заглушка того же размера, что настоящая.
        let мини = (МИНИ_W, МИНИ_H, vec![180u8; (МИНИ_W * МИНИ_H * 4) as usize]);
        let mut px = vec![0u8; (w * h * 4) as usize];

        let разов = 20;
        let начало = std::time::Instant::now();
        for _ in 0..разов {
            let mut холст = ui::Холст::новый(&mut px, w, h);
            let (верх, низ) = (ui::Цвет::из_argb(ФОН_ВЕРХ), ui::Цвет::из_argb(ФОН_НИЗ));
            холст.замена = true;
            холст.скругл_с(0, 0, w, h, CORNER, |д| верх.между(низ, д));
            холст.замена = false;
            холст.тень(0, 4, w, h - 4, CORNER, 18, ui::Цвет::из_argb(ТЕНЬ));
            for (_, x, y) in сетка(видно_карт() as usize, 0) {
                холст.скругл(x as i32, y as i32, кw, кh, CORNER, ui::Цвет::из_argb(CARD_COLOR));
                draw_thumbnail(&mut холст, x as i32, y as i32, кw, кh, &мини);
            }
        }
        println!(
            "полный кадр меню {w}×{h}, карточек {}: {:?}",
            видно_карт(),
            начало.elapsed() / разов,
        );
    }

    /// Сколько выигрывают параллельные миниатюры. ХОДИТ В СЕТЬ, поэтому
    /// `#[ignore]`: это замер, а не проверка, и в CI ему делать нечего.
    ///
    /// `cargo test --release -- --ignored --nocapture миниатюры_подряд_и_разом`
    #[test]
    #[ignore = "ходит в сеть"]
    fn миниатюры_подряд_и_разом() {
        let фильтры = online::Фильтры::default();
        let находки = match online::список(online::Источник::Картинки, 1, 2560, 1080, "", &фильтры) {
            Ok(н) if !н.is_empty() => н,
            иное => {
                println!("сеть недоступна ({иное:?}) — замер пропущен");
                return;
            }
        };
        let начало = std::time::Instant::now();
        let подряд: Vec<_> = находки
            .iter()
            .map(|н| match online::миниатюра(н) {
                Some(байты) => разобрать_миниатюру(&байты),
                None => пустая_миниатюра(),
            })
            .collect();
        let время_подряд = начало.elapsed();

        let начало = std::time::Instant::now();
        let разом = миниатюры_разом(&находки);
        let время_разом = начало.elapsed();

        assert_eq!(подряд.len(), разом.len(), "разное число карточек");
        println!(
            "{} миниатюр: подряд {:?}, разом {:?} — быстрее в {:.1} раза",
            находки.len(),
            время_подряд,
            время_разом,
            время_подряд.as_secs_f64() / время_разом.as_secs_f64().max(1e-9),
        );
    }

    /// Карточка «далее» появляется ровно тогда, когда есть что продолжать.
    #[test]
    fn далее_только_при_непустой_выдаче() {
        assert_eq!(карточек_в_сети(0), 0, "на пустой выдаче «далее» показывать нечего");
        assert_eq!(карточек_в_сети(1), 2);
        assert_eq!(карточек_в_сети(24), 25, "страница wallhaven плюс карточка «далее»");
    }

    /// Новый быстрый путь обязан давать ТУ ЖЕ картинку, что и прежний.
    ///
    /// Это не замер, а проверка: кэш карточек и `картинка_готовая` заменили
    /// собой `draw_thumbnail` в каждом кадре меню, и разойдись они — обои в
    /// ленте поехали бы или потеряли скругление, а поймать это глазами на
    /// одной карточке из трёх почти нельзя.
    #[test]
    fn кэш_рисует_то_же_самое() {
        // Размер меню — глобальный, и без общего замка этот тест менял бы его
        // под ногами у соседних (та же причина, что и в `tests::под_замком`).
        let _замок = super::tests::под_замком();
        установить_размер_меню(2560, 1080);
        let (w, h) = (ui_w(), ui_h());
        let (кw, кh) = (карта_w(), карта_h());
        // Не однотонная заливка: на ней совпало бы что угодно. Клетка ловит и
        // сдвиг на пиксель, и перепутанные оси.
        let мини = {
            let mut px = Vec::with_capacity((МИНИ_W * МИНИ_H * 4) as usize);
            for y in 0..МИНИ_H {
                for x in 0..МИНИ_W {
                    let светло = ((x / 17) + (y / 17)) % 2 == 0;
                    let c = if светло { 210 } else { 40 };
                    px.extend_from_slice(&[c, (x % 256) as u8, (y % 256) as u8, 255]);
                }
            }
            (МИНИ_W, МИНИ_H, px)
        };

        let mut старый = vec![0u8; (w * h * 4) as usize];
        {
            let mut холст = ui::Холст::новый(&mut старый, w, h);
            draw_thumbnail(&mut холст, 40, 30, кw, кh, &мини);
        }
        let mut новый = vec![0u8; (w * h * 4) as usize];
        {
            let (готовая, непрозрачная) = под_карточку(&мини, кw, кh);
            assert!(непрозрачная);
            let mut холст = ui::Холст::новый(&mut новый, w, h);
            холст.картинка_готовая(40, 30, кw, кh, CORNER, &готовая, непрозрачная);
        }

        let разошлось = старый
            .iter()
            .zip(&новый)
            .filter(|(a, b)| a.abs_diff(**b) > 1)
            .count();
        assert_eq!(
            разошлось, 0,
            "быстрый путь разошёлся с общим на {разошлось} байтах из {}",
            старый.len()
        );
    }

    /// Полный кадр меню ПО-НОВОМУ: стекло из снимка, миниатюры из кэша.
    /// Сравнивать с `цена_кадра` — это тот же кадр старым путём.
    ///
    /// `cargo test --release -- --ignored --nocapture цена_кадра_с_кэшем`
    #[test]
    #[ignore = "замер времени"]
    fn цена_кадра_с_кэшем() {
        установить_размер_меню(2560, 1080);
        let (w, h) = (ui_w(), ui_h());
        let (кw, кh) = (карта_w(), карта_h());
        // Заглушка НЕПРОЗРАЧНА (альфа 255) — как настоящие обои из JPEG.
        // С альфой 180, как в соседнем замере, путь был бы другой.
        let мини = (
            МИНИ_W,
            МИНИ_H,
            (0..(МИНИ_W * МИНИ_H) as usize)
                .flat_map(|_| [180u8, 180, 180, 255])
                .collect::<Vec<u8>>(),
        );
        let (готовая, непрозрачная) = под_карточку(&мини, кw, кh);
        assert!(непрозрачная, "заглушка непрозрачна — иначе замер мерил бы не тот путь");
        let mut px = vec![0u8; (w * h * 4) as usize];

        // Снимок стекла — то, что живой plx-wall держит в кэш_стекла.
        let mut снимок = vec![0u8; (w * h * 4) as usize];
        {
            let mut холст = ui::Холст::новый(&mut снимок, w, h);
            let (верх, низ) = (ui::Цвет::из_argb(ФОН_ВЕРХ), ui::Цвет::из_argb(ФОН_НИЗ));
            холст.замена = true;
            холст.скругл_с(0, 0, w, h, CORNER, |д| верх.между(низ, д));
            холст.замена = false;
            холст.тень(0, 4, w, h - 4, CORNER, 18, ui::Цвет::из_argb(ТЕНЬ));
        }

        let разов = 20;
        let начало = std::time::Instant::now();
        for _ in 0..разов {
            px.copy_from_slice(&снимок);
            let mut холст = ui::Холст::новый(&mut px, w, h);
            for (_, x, y) in сетка(видно_карт() as usize, 0) {
                // Подложки нет: миниатюра непрозрачна и закрывает карточку.
                холст.картинка_готовая(x as i32, y as i32, кw, кh, CORNER, &готовая, true);
            }
        }
        println!(
            "кадр меню {w}×{h} с кэшем, карточек {}: {:?}",
            видно_карт(),
            начало.elapsed() / разов,
        );
    }

    /// То же, но ПО ФАЗАМ: без разбивки видно только «кадр стоит столько-то»,
    /// а чинить надо то, что внутри него дороже всего.
    ///
    /// `cargo test --release -- --ignored --nocapture цена_по_фазам`
    #[test]
    #[ignore = "замер времени"]
    fn цена_по_фазам() {
        установить_размер_меню(2560, 1080);
        let (w, h) = (ui_w(), ui_h());
        let (кw, кh) = (карта_w(), карта_h());
        let мини = (МИНИ_W, МИНИ_H, vec![180u8; (МИНИ_W * МИНИ_H * 4) as usize]);
        let mut px = vec![0u8; (w * h * 4) as usize];
        let разов = 20;

        let замерить = |имя: &str, mut дело: &mut dyn FnMut()| {
            let начало = std::time::Instant::now();
            for _ in 0..разов {
                дело();
            }
            println!("  {имя}: {:?}", начало.elapsed() / разов);
        };

        println!("кадр меню {w}×{h}, карточек {}:", видно_карт());
        let (верх, низ) = (ui::Цвет::из_argb(ФОН_ВЕРХ), ui::Цвет::из_argb(ФОН_НИЗ));
        замерить("фон (скругл_с на весь холст)", &mut || {
            let mut холст = ui::Холст::новый(&mut px, w, h);
            холст.замена = true;
            холст.скругл_с(0, 0, w, h, CORNER, |д| верх.между(низ, д));
        });
        замерить("тень (разлёт 18)", &mut || {
            let mut холст = ui::Холст::новый(&mut px, w, h);
            холст.тень(0, 4, w, h - 4, CORNER, 18, ui::Цвет::из_argb(ТЕНЬ));
        });
        замерить("карточки без миниатюр", &mut || {
            let mut холст = ui::Холст::новый(&mut px, w, h);
            for (_, x, y) in сетка(видно_карт() as usize, 0) {
                холст.скругл(x as i32, y as i32, кw, кh, CORNER, ui::Цвет::из_argb(CARD_COLOR));
            }
        });
        замерить("миниатюры", &mut || {
            let mut холст = ui::Холст::новый(&mut px, w, h);
            for (_, x, y) in сетка(видно_карт() as usize, 0) {
                draw_thumbnail(&mut холст, x as i32, y as i32, кw, кh, &мини);
            }
        });
        // Та же отрисовка, но миниатюра УЖЕ размером с карточку: точка в
        // точку, без усреднения. Разница между этой строкой и предыдущей —
        // ровно цена масштабирования, которое сейчас делается каждый кадр
        // заново (см. кэш карточек).
        let под_карточку = (кw, кh, vec![180u8; (кw * кh * 4) as usize]);
        замерить("миниатюры (уже под размер карточки)", &mut || {
            let mut холст = ui::Холст::новый(&mut px, w, h);
            for (_, x, y) in сетка(видно_карт() as usize, 0) {
                draw_thumbnail(&mut холст, x as i32, y as i32, кw, кh, &под_карточку);
            }
        });
        // Новый путь: миниатюра лежит готовой (её считает кэш), кадр только
        // укладывает строки. Ради этой строки и заведён КэшКарточек.
        let готовая = vec![180u8; (кw * кh * 4) as usize];
        замерить("миниатюры из кэша (картинка_готовая)", &mut || {
            let mut холст = ui::Холст::новый(&mut px, w, h);
            for (_, x, y) in сетка(видно_карт() as usize, 0) {
                холст.картинка_готовая(x as i32, y as i32, кw, кh, CORNER, &готовая, true);
            }
        });
        замерить("RGBA→BGRA по всему буферу", &mut || {
            for chunk in px.chunks_exact_mut(4) {
                chunk.swap(0, 2);
            }
        });
    }

    /// Нарисовать ленту НАСТОЯЩИМИ обоями Ярика и положить картинку файлом.
    ///
    /// `#[ignore]` — это не проверка, а способ увидеть результат глазами, не
    /// поднимая сеанс: plx-wall рисует меню сам, в свой буфер, и всё, что для
    /// этого нужно, — чистые функции отрисовки. Запуск:
    /// `cargo test --release -- --ignored --nocapture посмотреть_ленту`.
    #[test]
    #[ignore = "рисует файл, смотреть глазами"]
    fn посмотреть_ленту() {
        let (sw, sh) = (2560u32, 1080u32);
        установить_размер_меню(sw, sh);
        let (w, h) = (ui_w(), ui_h());
        let mut px = vec![0u8; (w * h * 4) as usize];

        // Обои берём те же, что у живого plx-wall.
        let mut cfg_пути: Vec<String> = Vec::new();
        let список = format!("{}/.config/plx-wall/wallpapers.json", home());
        if let Ok(data) = std::fs::read_to_string(&список) {
            if let Ok(list) = serde_json::from_str::<Vec<String>>(&data) {
                cfg_пути = list;
            }
        }
        println!("обоев в списке: {}", cfg_пути.len());
        let миниатюры: Vec<(u32, u32, Vec<u8>)> = cfg_пути.iter()
            .take(видно_карт() as usize + 2)
            .map(|p| match load_image(p) {
                Some((iw, ih, data)) => (МИНИ_W, МИНИ_H, resize(iw, ih, &data, МИНИ_W, МИНИ_H)),
                None => пустая_миниатюра(),
            })
            .collect();

        let (кw, кh) = (карта_w(), карта_h());
        println!("карточка {кw}×{кh}, видно {}, меню {w}×{h}", видно_карт());
        let n = миниатюры.len();

        let mut холст = ui::Холст::новый(&mut px, w, h);
        // Стекло — тем же порядком, что в render_overlay.
        холст.тень(0, 4, w, h.saturating_sub(4), CORNER, 18, ui::Цвет::из_argb(ТЕНЬ));
        let (верх, низ) = (ui::Цвет::из_argb(ФОН_ВЕРХ), ui::Цвет::из_argb(ФОН_НИЗ));
        холст.скругл_с(0, 0, w, h, CORNER, |доля| верх.между(низ, доля));
        холст.кант(0, 0, w, h, CORNER, 1.0, ui::Цвет::из_argb(КАНТ));
        холст.скругл(CORNER as i32, 0, w.saturating_sub(CORNER * 2), 1, 0,
                     ui::Цвет::из_argb(БЛИК));

        // Лента показана В СЕРЕДИНЕ ПРОЕЗДА (позиция 0.5): так на снимке
        // видно и сдвиг, и обрезку по краям — то, ради чего листание вообще
        // стало плавным.
        холст.обрезка = Some(лента_rect());
        for карточка in сетка_дробно(n + 1, 0.5) {
            let (idx, x, y) = (карточка.idx, карточка.x, карточка.y);
            let (кw, кh) = (карточка.w, карточка.h);
            if idx < n {
                холст.скругл(x as i32, y as i32, кw, кh, CORNER, ui::Цвет::из_argb(CARD_COLOR));
                draw_thumbnail(&mut холст, x as i32, y as i32, кw, кh, &миниатюры[idx]);
                if idx == 1 {
                    // Так выглядят нынешние обои…
                    нарисовать_кант(&mut холст, x as i32, y as i32, кw, кh, ui::Цвет::из_argb(SEL_COLOR));
                } else if idx == 2 {
                    // …а так — карточка под курсором, с крестиком удаления.
                    холст.тень(x as i32, y as i32 + 2, кw, кh, CORNER, 10,
                               ui::Цвет::из_argb(ТЕНЬ));
                    нарисовать_кант(&mut холст, x as i32, y as i32, кw, кh,
                                    ui::Цвет::из_argb(SEL_COLOR).с_прозрачностью(0.55));
                    let (dx, dy) = (x + (кw - DEL_SIZE - 8) as i32, y as i32 + 8);
                    холст.скругл(dx, dy, DEL_SIZE, DEL_SIZE, DEL_SIZE / 2,
                                 ui::Цвет::из_argb(DEL_BG));
                    draw_cross(&mut холст, dx, dy, DEL_SIZE);
                }
            } else {
                холст.скругл(x as i32, y as i32, кw, кh, CORNER, ui::Цвет::из_argb(PLUS_COLOR));
                draw_plus(&mut холст, x + ((кw - кh) / 2) as i32, y as i32, кh, ui::Цвет::из_argb(ТЕКСТ_ТИХО));
            }
        }

        холст.обрезка = None;

        // Кнопки сверху и прокрутка снизу — рисуем как в render_overlay.
        // Вкладка «Картинки» выбрана нарочно: только на ней виден ряд
        // источников, ради которого снимок и нужен.
        for (i, (tx, ty)) in tab_rects().iter().enumerate() {
            let выбрана = i == 1;
            кнопка_полосы(&mut холст, *tx, *ty, ARROW, выбрана, 0.0);
            draw_tab_icon(&mut холст, ВКЛАДКИ[i], *tx, *ty, цвет_значка(выбрана, 0.0));
        }
        холст.скругл(tab_rects()[1].0 as i32, (tab_rects()[1].1 + ARROW + 3) as i32,
                     ARROW, 2, 1, ui::Цвет::из_argb(SEL_COLOR));
        let (sx, sy) = search_rect();
        кнопка_полосы(&mut холст, sx, sy, ARROW, false, 0.0);
        draw_search_icon(&mut холст, sx, sy, цвет_значка(false, 0.0));
        let (fx, fy) = filter_rect();
        кнопка_полосы(&mut холст, fx, fy, ARROW, false, 0.0);
        draw_filter_icon(&mut холст, fx, fy, цвет_значка(false, 0.0));

        // Ряд источников: первый выбран, второй — под курсором.
        let подписи = подписи_источников(Вкладка::Картинки);
        for (i, (x, y, ш)) in источник_rects(Вкладка::Картинки).into_iter().enumerate() {
            let выбран = i == 0;
            let подсветка = if i == 1 { 1.0 } else { 0.0 };
            let фон = ui::Цвет::из_argb(if выбран { HOVER_COLOR } else { PLUS_COLOR })
                .между(ui::Цвет::из_argb(HOVER_COLOR), подсветка);
            холст.скругл(x as i32, y as i32, ш, ARROW, ARROW / 2, фон);
            if выбран {
                холст.кант(x as i32, y as i32, ш, ARROW, ARROW / 2, 1.2,
                           ui::Цвет::из_argb(SEL_COLOR));
            }
            холст.текст_по_центру(
                x as i32, y as i32, ш, ARROW, подписи[i], КЕГЛЬ,
                if выбран { ui::Начертание::Полужирное } else { ui::Начертание::Обычное },
                цвет_значка(выбран, подсветка),
            );
        }

        нарисовать_прокрутку(&mut холст, 0.5, &|_| 0.0, 6, n + 1);

        // Пишем через `image`, который уже в зависимостях: свой png-крейт
        // ради одного отладочного снимка тащить незачем.
        let путь = format!("{}/Workbench/dawn-check/lenta.png", home());
        let _ = std::fs::create_dir_all(format!("{}/Workbench/dawn-check", home()));
        let буфер = image::RgbaImage::from_raw(w, h, px).expect("буфер картинки");
        буфер.save(&путь).expect("сохранить картинку");
        println!("картинка: {путь}");
    }
}
